      const finalGross =
        CTC_Gross_Net.find((e) => e.payheadMasterId == 50)
          ?.EmployeeSalaryAmount || 0;
      const finalNetPay =
        CTC_Gross_Net.find((e) => e.payheadMasterId == 92)
