// Helper function to format month YYYYMM to "Mon-YYYY" format
const formatMonthDisplay = (yyyymm) => {
  const monthNames = [
    'Jan',
    'Feb',
    'Mar',
    'Apr',
    'May',
    'Jun',
    'Jul',
    'Aug',
    'Sep',
    'Oct',
    'Nov',
    'Dec',
  ];
  const year = String(yyyymm).slice(0, 4);
  const month = parseInt(String(yyyymm).slice(4, 6), 10);
  return `${monthNames[month - 1]}-${year}`;
};

// Helper function to calculate actual amounts for salary components
const calculateActualAmounts = (ctc, projectAllocation, salaryComponents) => {
  const result = {};
  if (!ctc || ctc === 0) return result;

  salaryComponents.forEach((comp) => {
    const componentActual = parseFloat(comp.actualAmount) || 0;
    const percentage = (componentActual / ctc) * 100;
    const projectAmount = (percentage / 100) * projectAllocation;
    result[comp.displayName] = Math.round(projectAmount * 100) / 100;
  });

  return result;
};

// Helper function to sum objects by keys
const sumObjectsByKeys = (objects) => {
  const result = {};
  objects.forEach((obj) => {
    Object.keys(obj).forEach((key) => {
      if (typeof obj[key] === 'number') {
        result[key] = (result[key] || 0) + obj[key];
      }
    });
  });
  return result;
};

exports.projectWiseSalaryReport = async (req, res, next) => {
  try {
    const {
      startMonth,
      endMonth,
      userMasterID,
      type,
      projectId,
      companyMasterId,
      branchId,
      departmentId,
      designationId,
      divisionId,
      workingAreaId,
      payrollFrequency = PayrollFrequencyType.MONTHLY,
      salaryStatus = salaryStatusEnum.ALL,
    } = req.body;

    if (!companyMasterId || !startMonth || !endMonth || !type)
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message:
          'companyMasterId,startMonth,endMonth,Type are required fields!',
      });

    const currentdate = asiaKolkataDateTime(new Date()).slice(0, 10);

    const projectCondition = {};

    if (projectId && projectId.length && type == 'projectwise') {
      projectCondition.projectID = projectId;
    }
    const { where, includeModels } = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: false,
    });

    const includeArray = [
      ...includeModels,
      {
        required: true,
        model: HrSalaryTransaction,
        where: {
          salaryYYYYMM: {
            [Sequelize.Op.between]: [startMonth, endMonth],
          },
        },
        attributes: [
          'salaryMasterID',
          'userMasterID',
          'salaryYYYYMM',
          'EmployeeSalaryAmount',
        ],
        include: [
          {
            model: HrSalaryMaster,
            as: 'HSM',
            attributes: ['gradeSalaryStructureID', 'EmployeeSalaryAmount'],
            include: [
              {
                model: GradeSalaryStructure,
                as: 'GSS',
                attributes: ['salaryFieldID'],
                include: [
                  {
                    model: HRSalaryFields,
                    as: 'HSF',
                    attributes: [
                      'salaryFieldSrNo',
                      'salaryFieldSide',
                      'considerIn',
                      'payheadDisplayName',
                      'payheadMasterId',
                    ],
                    include: [
                      {
                        model: Payheadmaster,
                        as: 'PHM',
                        attributes: ['payheadName'],
                      },
                    ],
                  },
                ],
              },
            ],
          },
          {
            required: false,
            model: EmployeePenalty,
            include: [
              { model: Penalty, as: 'penalty', attributes: ['penaltyName'] },
            ],
          },
          {
            required: false,
            model: EmployeeIncentive,
            include: [
              {
                model: Incentivetype,
                as: 'IncType',
                attributes: [
                  ['incentivetypename', 'name'],
                  ['inc_type_displayName', 'displayName'],
                  ['IncentivetypeID', 'id'],
                ],
              },
            ],
          },
        ],
      },
      {
        model: EmployeeBranch,
        where: {
          status: 1,
          ...(branchId && branchId.length && { branchID: branchId }),
          applicableDate: {
            [Sequelize.Op.lte]: currentdate,
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: currentdate,
              },
            },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: branchId.length ? true : false,
        attributes: ['branchID'],
        include: [
          {
            model: BranchMaster,
            as: 'branchMaster',
            attributes: ['branchName'],
          },
        ],
      },
      {
        required: designationId.length ? true : false,
        model: EmployeeDesignation,
        where: {
          status: 1,
          ...(designationId &&
            designationId.length && { designationID: designationId }),
          applicableDate: { [Sequelize.Op.lte]: currentdate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: currentdate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        attributes: ['designationID'],
        include: [
          {
            model: Designation,
            as: 'designation',
            attributes: ['designationName'],
          },
        ],
      },
      {
        required: departmentId.length ? true : false,
        model: EmployeeDepartment,
        where: {
          status: 1,
          ...(departmentId &&
            departmentId.length && { departmentID: departmentId }),
          applicableDate: { [Sequelize.Op.lte]: new Date(currentdate) },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: new Date(currentdate) } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        attributes: ['departmentID'],
        include: [
          {
            model: Department,
            as: 'department',
            attributes: ['departmentName'],
          },
        ],
      },
      {
        required: divisionId.length ? true : false,
        model: EmployeeDivision,
        where: {
          status: 1,
          ...(divisionId && divisionId.length && { divisionId }),
          startDate: { [Sequelize.Op.lte]: currentdate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: currentdate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        attributes: ['divisionId'],
        include: [
          {
            model: Division,
            attributes: ['divisionName'],
          },
        ],
      },
      {
        required: workingAreaId.length ? true : false,
        model: EmployeeWorkingArea,
        where: {
          status: 1,
          ...(workingAreaId &&
            workingAreaId.length && { workingAreaId: workingAreaId }),
          startDate: { [Sequelize.Op.lte]: currentdate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: currentdate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        attributes: ['workingAreaId'],
        include: [
          {
            model: WorkingArea,
            attributes: ['workingAreaName'],
          },
        ],
      },
      {
        model: EmployeeJoiningDetails,
        attributes: ['employeeCode'],
        required: true,
      },
      {
        model: ProjectWiseSalaryDistribution,
        as: 'PWSD',
        where: {
          payrollFrequency,
          applicableYYYYMM: {
            [Sequelize.Op.lte]: endMonth,
          },
        },
        attributes: ['userMasterID', 'applicableYYYYMM', 'payrollFrequency'],
        include: [
          {
            model: ProjectWiseSalaryDistributionDetails,
            as: 'PWSDD',
            where: projectCondition,
            required: false,
            attributes: [
              'projectID',
              'pwsdID',
              'amount',
              'absentDeduction',
              'penaltyDeduction',
              'advanceDeduction',
              'loanDeduction',
            ],
            include: [{ model: Project, attributes: ['projectName'] }],
          },
        ],
      },
    ];

    const salarySlipCondition = {
      salaryYYYYMM: {
        [Sequelize.Op.between]: [startMonth, endMonth],
      },
    };

    let salarySlipRequired = false;

    switch (salaryStatus) {
      case salaryStatusEnum.EXCLUDE_ON_HOLD:
        salarySlipCondition.holdBy = {
          [Sequelize.Op.is]: null,
        };
        salarySlipRequired = true;
        break;

      case salaryStatusEnum.ON_HOLD:
        salarySlipCondition.holdBy = {
          [Sequelize.Op.not]: null,
        };
        salarySlipRequired = true;
        break;
    }

    if (salarySlipRequired) {
      includeArray.push({
        required: salarySlipRequired,
        model: HRSalarySlip,
        where: salarySlipCondition,
        attributes: [],
      });
    }

    const condition = { companyMasterId };

    if (Array.isArray(userMasterID) && userMasterID.length) {
      condition.userMasterID = userMasterID;
    }

    const userData = await UserMaster.findAll({
      where: { ...where, ...condition },
      include: includeArray,
      order: [['displayName', 'ASC']],
      attributes: ['userMasterID', 'displayName', 'userNumber'],
    });

    // Check if no data found
    if (!userData || userData.length === 0) {
      return res.status(200).json({
        status: 200,
        message: 'No data found to export!',
      });
    }

    // Collect all unique salary components with their amounts and index for dynamic columns
    const earningComponentsMap = new Map(); // { displayName: { actual, earned, index, isIncentive } }
    const deductionComponentsMap = new Map(); // { displayName: { actual, earned, index, isPenalty } }
    const employerComponentsMap = new Map(); // { displayName: { actual, earned, index } }

    // Exclude payheadMasterId: 1 (CTC), 50 (Gross), 92 (Net Pay) - these are calculated
    const excludedPayheadIds = [
      payheadMasterIdsMapping.CTC,
      payheadMasterIdsMapping.GROSS,
      payheadMasterIdsMapping.NETSALARY,
      payheadMasterIdsMapping.PENALTY,
      payheadMasterIdsMapping.INCENTIVE,
    ];

    // Process user data to extract salary components and track amounts
    userData.forEach((user) => {
      if (user.hrSalaryTrasactions) {
        user.hrSalaryTrasactions.forEach((trans) => {
          const hsf = trans.HSM?.GSS?.HSF;
          const gss = trans.HSM?.GSS;
          const payheadMasterId = hsf?.payheadMasterId;
          if (hsf && !excludedPayheadIds.includes(payheadMasterId)) {
            const displayName =
              hsf.payheadDisplayName || hsf.PHM?.payheadName || 'Unknown';
            const srNo = hsf.salaryFieldSrNo?.toUpperCase();
            const salaryFieldIndex = gss?.salaryfieldindex || 9999; // Default high index if not set
            const masterAmount =
              parseFloat(trans.HSM?.EmployeeSalaryAmount) || 0;
            const transAmount = parseFloat(trans.EmployeeSalaryAmount) || 0;

            // A = Earning, B = Employee Deduction, C = Employer Deduction
            if (srNo === salaryFieldSrNoFields.EARNING) {
              const existing = earningComponentsMap.get(displayName) || {
                actual: 0,
                earned: 0,
                index: salaryFieldIndex,
                isIncentive: false,
              };
              existing.actual += masterAmount;
              existing.earned += transAmount;
              // Keep the lowest index
              if (salaryFieldIndex < existing.index)
                existing.index = salaryFieldIndex;
              earningComponentsMap.set(displayName, existing);
            } else if (srNo === salaryFieldSrNoFields.EMPLOYEE_DEDUCTION) {
              const existing = deductionComponentsMap.get(displayName) || {
                actual: 0,
                earned: 0,
                index: salaryFieldIndex,
                isPenalty: false,
              };
              existing.actual += masterAmount;
              existing.earned += transAmount;
              if (salaryFieldIndex < existing.index)
                existing.index = salaryFieldIndex;
              deductionComponentsMap.set(displayName, existing);
            } else if (srNo === salaryFieldSrNoFields.EMPLOYER_DEDUCTION) {
              const existing = employerComponentsMap.get(displayName) || {
                actual: 0,
                earned: 0,
                index: salaryFieldIndex,
              };
              existing.actual += masterAmount;
              existing.earned += transAmount;
              if (salaryFieldIndex < existing.index)
                existing.index = salaryFieldIndex;
              employerComponentsMap.set(displayName, existing);
            }
          }

          // Add penalty types as deduction components (mark as penalty, put at end)
          if (trans.employeePenalties && trans.employeePenalties.length > 0) {
            trans.employeePenalties.forEach((penalty) => {
              const penaltyName = penalty.penalty?.penaltyName || 'Penalty';
              const amount = parseFloat(penalty.penaltyAmount) || 0;
              const existing = deductionComponentsMap.get(penaltyName) || {
                actual: 0,
                earned: 0,
                index: 99999,
                isPenalty: true,
              };
              existing.actual += amount;
              existing.earned += amount;
              existing.isPenalty = true; // Mark as penalty type
              deductionComponentsMap.set(penaltyName, existing);
            });
          }

          // Add incentive types as earning components (mark as incentive, put at end)
          if (trans.employeeincentives && trans.employeeincentives.length > 0) {
            trans.employeeincentives.forEach((incentive) => {
              const incentiveName =
                incentive.IncType?.dataValues?.displayName ||
                incentive.IncType?.dataValues?.name ||
                'Incentive';
              const amount = parseFloat(incentive.amount) || 0;
              const existing = earningComponentsMap.get(incentiveName) || {
                actual: 0,
                earned: 0,
                index: 99999,
                isIncentive: true,
              };
              existing.actual += amount;
              existing.earned += amount;
              existing.isIncentive = true; // Mark as incentive type
              earningComponentsMap.set(incentiveName, existing);
            });
          }
        });
      }
    });

    // Filter out components where both actual and earned are zero, then sort
    // Sort by: 1) isIncentive/isPenalty (false first), 2) salaryFieldIndex, 3) name
    const earningColsWithIncentiveFlag = Array.from(
      earningComponentsMap.entries(),
    )
      .filter(([name, data]) => data.actual !== 0 || data.earned !== 0)
      .sort((a, b) => {
        // Incentives go to the end
        if (a[1].isIncentive !== b[1].isIncentive) {
          return a[1].isIncentive ? 1 : -1;
        }
        // Then sort by index
        if (a[1].index !== b[1].index) {
          return a[1].index - b[1].index;
        }
        // Then by name
        return a[0].localeCompare(b[0]);
      });

    // All earning columns (for earned columns - includes incentives)
    const earningCols = earningColsWithIncentiveFlag.map(([name]) => name);

    // Non-incentive earning columns (for actual columns - excludes incentives)
    const actualEarningCols = earningColsWithIncentiveFlag
      .filter(([name, data]) => !data.isIncentive)
      .map(([name]) => name);

    const deductionCols = Array.from(deductionComponentsMap.entries())
      .filter(([name, data]) => data.actual !== 0 || data.earned !== 0)
      .sort((a, b) => {
        // Penalties go to the end
        if (a[1].isPenalty !== b[1].isPenalty) {
          return a[1].isPenalty ? 1 : -1;
        }
        // Then sort by index
        if (a[1].index !== b[1].index) {
          return a[1].index - b[1].index;
        }
        // Then by name
        return a[0].localeCompare(b[0]);
      })
      .map(([name]) => name);

    const employerCols = Array.from(employerComponentsMap.entries())
      .filter(([name, data]) => data.actual !== 0 || data.earned !== 0)
      .sort((a, b) => {
        // Sort by index
        if (a[1].index !== b[1].index) {
          return a[1].index - b[1].index;
        }
        // Then by name
        return a[0].localeCompare(b[0]);
      })
      .map(([name]) => name);

    // Process data into report structure
    const reportData = [];

    userData.forEach((user) => {
      const employeeCode = user.employeeJoiningDetails?.[0]?.employeeCode || '';
      const employeeName = user.displayName || '';
      const employeeNumber = user.userNumber || '';
      const branch = user.employeeBranches?.[0]?.branchMaster?.branchName || '';
      const department =
        user.employeeDepartments?.[0]?.department?.departmentName || '';
      const designation =
        user.employeeDesignations?.[0]?.designation?.designationName || '';
      const division =
        user.employeeDivisions?.[0]?.division?.divisionName || '';
      const workingArea =
        user.employeeWorkingAreas?.[0]?.workingArea?.workingAreaName || '';

      // Group salary transactions by month
      const transactionsByMonth = {};
      if (user.hrSalaryTrasactions) {
        user.hrSalaryTrasactions.forEach((trans) => {
          const month = trans.salaryYYYYMM;
          if (!transactionsByMonth[month]) {
            transactionsByMonth[month] = [];
          }
          transactionsByMonth[month].push(trans);
        });
      }

      // Sort project distributions by applicableYYYYMM descending to find most recent
      const sortedPWSD = (user.PWSD || [])
        .slice()
        .sort((a, b) => b.applicableYYYYMM - a.applicableYYYYMM);

      // Build allocations for each salary month in the report range
      const allocationsByMonth = {};
      const salaryMonths = Object.keys(transactionsByMonth).filter(
        (m) => m >= startMonth && m <= endMonth,
      );

      salaryMonths.forEach((salaryMonth) => {
        // Find the most recent distribution applicable to this salary month
        // (applicableYYYYMM <= salaryMonth)
        const applicableDistribution = sortedPWSD.find(
          (pwsd) => pwsd.applicableYYYYMM <= salaryMonth,
        );

        if (applicableDistribution && applicableDistribution.PWSDD) {
          if (!allocationsByMonth[salaryMonth]) {
            allocationsByMonth[salaryMonth] = [];
          }
          applicableDistribution.PWSDD.forEach((detail) => {
            // Filter by projectId if provided (convert to string for comparison since projectId array may contain strings)
            const detailProjectIdStr = String(detail.projectID);
            if (
              !projectId ||
              !Array.isArray(projectId) ||
              projectId.length === 0 ||
              projectId.map(String).includes(detailProjectIdStr)
            ) {
              allocationsByMonth[salaryMonth].push({
                projectName: detail.project?.projectName || 'Unknown Project',
                projectID: detail.projectID,
                allocatedAmount: parseFloat(detail.amount) || 0,
                absentDeduction: detail.absentDeduction || false,
                loanDeduction: detail.loanDeduction || false,
                advanceDeduction: detail.advanceDeduction || false,
                penaltyDeduction: detail.penaltyDeduction || false,
              });
            }
          });
        }
      });

      // Skip if no allocations
      if (Object.keys(allocationsByMonth).length === 0) return;

      const employeeRows = [];
      const monthlyTotals = [];

      // Payhead IDs for conditional deductions
      const LOAN_PAYHEAD_ID = payheadMasterIdsMapping.LOAN;
      const ADVANCE_PAYHEAD_ID = payheadMasterIdsMapping.ADVANCE;
      const PENALTY_PAYHEAD_ID = payheadMasterIdsMapping.PENALTY;
      const ATTENDANCE_PENALTY_PAYHEAD_ID =
        payheadMasterIdsMapping.ATTENDANCE_PENALTY;

      // Process each month
      const sortedMonths = Object.keys(allocationsByMonth).sort();
      sortedMonths.forEach((month) => {
        const allocations = allocationsByMonth[month];
        const transactions = transactionsByMonth[month] || [];

        // Build salary component maps from transactions
        const actualFromMaster = {};
        const earnedFromTransaction = {};
        let totalCTC = 0;

        // First pass: Get CTC from payheadMasterId = 1
        transactions.forEach((trans) => {
          const hsf = trans.HSM?.GSS?.HSF;
          const payheadMasterId = hsf?.payheadMasterId;
          if (payheadMasterId === 1 || payheadMasterId === '1') {
            totalCTC = parseFloat(trans.HSM?.EmployeeSalaryAmount) || 0;
          }
        });

        // Second pass: Build earning component maps
        transactions.forEach((trans) => {
          const hsf = trans.HSM?.GSS?.HSF;
          const srNo = hsf?.salaryFieldSrNo?.toUpperCase();
          if (hsf && srNo === salaryFieldSrNoFields.EARNING) {
            const displayName =
              hsf.payheadDisplayName || hsf.PHM?.payheadName || 'Unknown';
            const masterAmount =
              parseFloat(trans.HSM?.EmployeeSalaryAmount) || 0;
            const transAmount = parseFloat(trans.EmployeeSalaryAmount) || 0;
            actualFromMaster[displayName] = masterAmount;
            earnedFromTransaction[displayName] = transAmount;
          }

          // Add incentive amounts to earning maps
          if (trans.employeeincentives && trans.employeeincentives.length > 0) {
            trans.employeeincentives.forEach((incentive) => {
              const incentiveName =
                incentive.IncType?.dataValues?.displayName ||
                incentive.IncType?.dataValues?.name ||
                'Incentive';
              const amount = parseFloat(incentive.amount) || 0;
              actualFromMaster[incentiveName] =
                (actualFromMaster[incentiveName] || 0) + amount;
              earnedFromTransaction[incentiveName] =
                (earnedFromTransaction[incentiveName] || 0) + amount;
            });
          }
        });

        // Build deduction maps (B = Employee Deduction) with payheadMasterId tracking
        const deductionFromMaster = {};
        const deductionFromTransaction = {};
        const deductionPayheadIdMap = {}; // Map displayName to payheadMasterId

        transactions.forEach((trans) => {
          const hsf = trans.HSM?.GSS?.HSF;
          const srNo = hsf?.salaryFieldSrNo?.toUpperCase();
          const payheadMasterId = hsf?.payheadMasterId;
          if (hsf && srNo === salaryFieldSrNoFields.EMPLOYEE_DEDUCTION) {
            const displayName =
              hsf.payheadDisplayName || hsf.PHM?.payheadName || 'Unknown';
            const masterAmount =
              parseFloat(trans.HSM?.EmployeeSalaryAmount) || 0;
            const transAmount = parseFloat(trans.EmployeeSalaryAmount) || 0;
            deductionFromMaster[displayName] = masterAmount;
            deductionFromTransaction[displayName] = transAmount;
            deductionPayheadIdMap[displayName] = payheadMasterId;
          }

          // Add penalty amounts to deduction maps (mark as penalty type)
          if (trans.employeePenalties && trans.employeePenalties.length > 0) {
            trans.employeePenalties.forEach((penalty) => {
              const penaltyName = penalty.penalty?.penaltyName || 'Penalty';
              const amount = parseFloat(penalty.penaltyAmount) || 0;
              deductionFromMaster[penaltyName] =
                (deductionFromMaster[penaltyName] || 0) + amount;
              deductionFromTransaction[penaltyName] =
                (deductionFromTransaction[penaltyName] || 0) + amount;
              deductionPayheadIdMap[penaltyName] = PENALTY_PAYHEAD_ID; // Mark as penalty
            });
          }
        });

        // Build employer contribution maps (C = Employer Deduction)
        const employerFromMaster = {};
        const employerFromTransaction = {};
        transactions.forEach((trans) => {
          const hsf = trans.HSM?.GSS?.HSF;
          const srNo = hsf?.salaryFieldSrNo?.toUpperCase();
          if (hsf && srNo === salaryFieldSrNoFields.EMPLOYER_DEDUCTION) {
            const displayName =
              hsf.payheadDisplayName || hsf.PHM?.payheadName || 'Unknown';
            const masterAmount =
              parseFloat(trans.HSM?.EmployeeSalaryAmount) || 0;
            const transAmount = parseFloat(trans.EmployeeSalaryAmount) || 0;
            employerFromMaster[displayName] = masterAmount;
            employerFromTransaction[displayName] = transAmount;
          }
        });

        // Build salary components array for calculation
        const salaryComponents = earningCols.map((name) => ({
          displayName: name,
          actualAmount: actualFromMaster[name] || 0,
        }));

        const monthProjectRows = [];

        // Pre-calculate total allocations for each flag type (for ratio-based distribution)
        const totalAllocationByFlag = {
          absentDeduction: 0,
          loanDeduction: 0,
          advanceDeduction: 0,
          penaltyDeduction: 0,
        };

        allocations.forEach((allocation) => {
          if (allocation.absentDeduction) {
            totalAllocationByFlag.absentDeduction +=
              allocation.allocatedAmount || 0;
          }
          if (allocation.loanDeduction) {
            totalAllocationByFlag.loanDeduction +=
              allocation.allocatedAmount || 0;
          }
          if (allocation.advanceDeduction) {
            totalAllocationByFlag.advanceDeduction +=
              allocation.allocatedAmount || 0;
          }
          if (allocation.penaltyDeduction) {
            totalAllocationByFlag.penaltyDeduction +=
              allocation.allocatedAmount || 0;
          }
        });

        // Pre-calculate total actual amounts for projects with absentDeduction = false
        // This is needed to calculate how much deduction goes to enabled projects
        const totalActualByFlagFalse = {};
        earningCols.forEach((name) => {
          totalActualByFlagFalse[name] = 0;
        });
        deductionCols.forEach((name) => {
          totalActualByFlagFalse[name] = 0;
        });
        employerCols.forEach((name) => {
          totalActualByFlagFalse[name] = 0;
        });

        // Calculate actual amounts for flag=false projects
        allocations.forEach((allocation) => {
          if (!allocation.absentDeduction) {
            const projectAllocation = allocation.allocatedAmount;
            // Calculate actual earning amounts for this project
            earningCols.forEach((name) => {
              const masterAmount = actualFromMaster[name] || 0;
              const actualAmount =
                totalCTC > 0
                  ? (masterAmount / totalCTC) * projectAllocation
                  : 0;
              totalActualByFlagFalse[name] += actualAmount;
            });
            // Calculate actual deduction amounts for this project
            deductionCols.forEach((name) => {
              const masterAmount = deductionFromMaster[name] || 0;
              const actualAmount =
                totalCTC > 0
                  ? (masterAmount / totalCTC) * projectAllocation
                  : 0;
              totalActualByFlagFalse[name] += actualAmount;
            });
            // Calculate actual employer amounts for this project
            employerCols.forEach((name) => {
              const masterAmount = employerFromMaster[name] || 0;
              const actualAmount =
                totalCTC > 0
                  ? (masterAmount / totalCTC) * projectAllocation
                  : 0;
              totalActualByFlagFalse[name] += actualAmount;
            });
          }
        });

        // Process each project allocation
        allocations.forEach((allocation) => {
          const projectAllocation = allocation.allocatedAmount;
          const absentDeduction = allocation.absentDeduction;

          // Track negative values for remarks
          const negativeFields = [];

          // Calculate actual earning amounts
          const actualEarnings = calculateActualAmounts(
            totalCTC,
            projectAllocation,
            salaryComponents,
          );

          // Calculate earned amounts with deduction distribution logic
          const earnedEarnings = {};
          earningCols.forEach((name) => {
            const actualAmount = actualEarnings[name] || 0;
            const masterAmount = actualFromMaster[name] || 0;
            const transAmount = earnedFromTransaction[name] || 0;

            let earnedValue = 0;

            // NEW LOGIC: If actual amount is 0, distribute earned by allocation percentage (ignore flag)
            if (actualAmount === 0) {
              // Distribute earned amount across all projects based on allocation percentage
              const totalAllocation = allocations.reduce(
                (sum, a) => sum + (a.allocatedAmount || 0),
                0,
              );
              if (totalAllocation > 0) {
                earnedValue =
                  transAmount * (projectAllocation / totalAllocation);
              } else {
                earnedValue = 0;
              }
            }
            // EXISTING LOGIC: If actual amount > 0, use flag-based logic
            else if (!absentDeduction) {
              // Flag is false - earned = actual (no deduction, full amount)
              earnedValue = actualAmount;
            } else if (totalAllocationByFlag.absentDeduction === 0) {
              // No enabled projects - no earned amount
              earnedValue = 0;
            } else {
              // Calculate total deduction for this component
              // Total Deduction = Master Amount - Transaction Amount
              const totalDeduction = masterAmount - transAmount;

              // Calculate ratio of this project's allocation among enabled projects
              const projectRatio =
                projectAllocation / totalAllocationByFlag.absentDeduction;

              // This project's share of the deduction
              const projectDeduction = totalDeduction * projectRatio;

              // Earned = Actual - Project's share of deduction
              earnedValue = actualAmount - projectDeduction;
            }

            // Check for negative value
            if (earnedValue < 0) {
              negativeFields.push(`Earn_${name}`);
              earnedEarnings[name] = 0;
            } else {
              earnedEarnings[name] = Math.round(earnedValue * 100) / 100;
            }
          });

          // Calculate deductions with deduction distribution logic
          const deductions = {};
          deductionCols.forEach((name) => {
            const transAmount = deductionFromTransaction[name] || 0;
            const payheadId = deductionPayheadIdMap[name];
            const masterAmount = deductionFromMaster[name] || 0;

            // Calculate actual deduction amount for this project
            const actualDeduction =
              totalCTC > 0 ? (masterAmount / totalCTC) * projectAllocation : 0;

            let deductionValue = 0;

            // Loan (payheadMasterId: 17) - only if loanDeduction is true
            if (payheadId === LOAN_PAYHEAD_ID) {
              // NEW LOGIC: If actual = 0, distribute by allocation % (ignore flag)
              if (actualDeduction === 0) {
                const totalAllocation = allocations.reduce(
                  (sum, a) => sum + (a.allocatedAmount || 0),
                  0,
                );
                deductionValue =
                  totalAllocation > 0
                    ? transAmount * (projectAllocation / totalAllocation)
                    : 0;
              }
              // EXISTING LOGIC: If actual > 0, use flag-based logic
              else if (!allocation.loanDeduction) {
                deductionValue = 0;
              } else if (totalAllocationByFlag.loanDeduction === 0) {
                deductionValue = 0;
              } else {
                const projectRatio =
                  projectAllocation / totalAllocationByFlag.loanDeduction;
                deductionValue = transAmount * projectRatio;
              }
            }
            // Advance (payheadMasterId: 16) - only if advanceDeduction is true
            else if (payheadId === ADVANCE_PAYHEAD_ID) {
              // NEW LOGIC: If actual = 0, distribute by allocation % (ignore flag)
              if (actualDeduction === 0) {
                const totalAllocation = allocations.reduce(
                  (sum, a) => sum + (a.allocatedAmount || 0),
                  0,
                );
                deductionValue =
                  totalAllocation > 0
                    ? transAmount * (projectAllocation / totalAllocation)
                    : 0;
              }
              // EXISTING LOGIC: If actual > 0, use flag-based logic
              else if (!allocation.advanceDeduction) {
                deductionValue = 0;
              } else if (totalAllocationByFlag.advanceDeduction === 0) {
                deductionValue = 0;
              } else {
                const projectRatio =
                  projectAllocation / totalAllocationByFlag.advanceDeduction;
                deductionValue = transAmount * projectRatio;
              }
            }
            // Penalty (payheadMasterId: 34) and Attendance Penalty (78) - only if penaltyDeduction is true
            else if (
              payheadId === PENALTY_PAYHEAD_ID ||
              payheadId === ATTENDANCE_PENALTY_PAYHEAD_ID
            ) {
              // NEW LOGIC: If actual = 0, distribute by allocation % (ignore flag)
              if (actualDeduction === 0) {
                const totalAllocation = allocations.reduce(
                  (sum, a) => sum + (a.allocatedAmount || 0),
                  0,
                );
                deductionValue =
                  totalAllocation > 0
                    ? transAmount * (projectAllocation / totalAllocation)
                    : 0;
              }
              // EXISTING LOGIC: If actual > 0, use flag-based logic
              else if (!allocation.penaltyDeduction) {
                deductionValue = 0;
              } else if (totalAllocationByFlag.penaltyDeduction === 0) {
                deductionValue = 0;
              } else {
                const projectRatio =
                  projectAllocation / totalAllocationByFlag.penaltyDeduction;
                deductionValue = transAmount * projectRatio;
              }
            }
            // Regular deductions - use absentDeduction flag
            else {
              // NEW LOGIC: If actual = 0, distribute by allocation % (ignore flag)
              if (actualDeduction === 0) {
                const totalAllocation = allocations.reduce(
                  (sum, a) => sum + (a.allocatedAmount || 0),
                  0,
                );
                deductionValue =
                  totalAllocation > 0
                    ? transAmount * (projectAllocation / totalAllocation)
                    : 0;
              }
              // EXISTING LOGIC: If actual > 0, use flag-based logic
              else if (!absentDeduction) {
                // Flag is false - assign actual amount
                deductionValue = actualDeduction;
              } else if (totalAllocationByFlag.absentDeduction === 0) {
                deductionValue = 0;
              } else {
                // Calculate remaining amount after flag=false projects
                const remaining = transAmount - totalActualByFlagFalse[name];
                const projectRatio =
                  projectAllocation / totalAllocationByFlag.absentDeduction;
                deductionValue = remaining * projectRatio;
              }
            }

            // Check for negative value
            if (deductionValue < 0) {
              negativeFields.push(name);
              deductions[name] = 0;
            } else {
              deductions[name] = Math.round(deductionValue * 100) / 100;
            }
          });

          // Calculate employer contributions with same logic as deductions
          const employerContributions = {};
          employerCols.forEach((name) => {
            const masterAmount = employerFromMaster[name] || 0;
            const transAmount = employerFromTransaction[name] || 0;

            // Calculate actual employer amount for this project (based on CTC ratio)
            const actualEmployer =
              totalCTC > 0 ? (masterAmount / totalCTC) * projectAllocation : 0;

            let employerValue = 0;

            // NEW LOGIC: If actual = 0, distribute by allocation % (ignore flag)
            if (actualEmployer === 0) {
              const totalAllocation = allocations.reduce(
                (sum, a) => sum + (a.allocatedAmount || 0),
                0,
              );
              employerValue =
                totalAllocation > 0
                  ? transAmount * (projectAllocation / totalAllocation)
                  : 0;
            }
            // EXISTING LOGIC: If actual > 0, use flag-based logic
            else if (!absentDeduction) {
              // Flag is false - assign actual amount
              employerValue = actualEmployer;
            } else if (totalAllocationByFlag.absentDeduction === 0) {
              employerValue = 0;
            } else {
              // Calculate remaining amount after flag=false projects
              const remaining = transAmount - totalActualByFlagFalse[name];
              const projectRatio =
                projectAllocation / totalAllocationByFlag.absentDeduction;
              employerValue = remaining * projectRatio;
            }

            // Check for negative value
            if (employerValue < 0) {
              negativeFields.push(name);
              employerContributions[name] = 0;
            } else {
              employerContributions[name] =
                Math.round(employerValue * 100) / 100;
            }
          });

          // Calculate Gross (sum of all earned earnings)
          const gross = Object.values(earnedEarnings).reduce(
            (sum, val) => sum + (parseFloat(val) || 0),
            0,
          );
          const grossRounded = Math.round(gross * 100) / 100;

          // Calculate Net Pay (Gross - Employee Deductions)
          const totalDeductions = Object.values(deductions).reduce(
            (sum, val) => sum + (parseFloat(val) || 0),
            0,
          );
          const netPay =
            Math.round((grossRounded - totalDeductions) * 100) / 100;

          // Build remarks for negative values
          const remarks =
            negativeFields.length > 0
              ? `Negative value in: ${negativeFields.join(', ')}`
              : '';

          const row = {
            employeeCode,
            employeeName,
            employeeNumber,
            branch,
            department,
            designation,
            division,
            workingArea,
            month: formatMonthDisplay(month),
            monthYYYYMM: month, // Store original format for sorting
            projectName: allocation.projectName,
            projectID: allocation.projectID,
            allocatedAmount: projectAllocation,
            actualEarnings,
            earnedEarnings,
            deductions,
            employerContributions,
            gross: grossRounded,
            netPay,
            remarks,
            isTotal: false,
            isGrandTotal: false,
          };

          monthProjectRows.push(row);
          employeeRows.push(row);
        });

        // Calculate monthly total
        if (monthProjectRows.length > 0) {
          const monthTotal = {
            employeeCode: '',
            employeeName: '',
            employeeNumber: '',
            branch: '',
            department: '',
            designation: '',
            division: '',
            workingArea: '',
            month: formatMonthDisplay(month),
            monthYYYYMM: month, // Store original format for sorting
            projectName: 'Total',
            allocatedAmount: monthProjectRows.reduce(
              (sum, r) => sum + r.allocatedAmount,
              0,
            ),
            actualEarnings: sumObjectsByKeys(
              monthProjectRows.map((r) => r.actualEarnings),
            ),
            earnedEarnings: sumObjectsByKeys(
              monthProjectRows.map((r) => r.earnedEarnings),
            ),
            deductions: sumObjectsByKeys(
              monthProjectRows.map((r) => r.deductions),
            ),
            employerContributions: sumObjectsByKeys(
              monthProjectRows.map((r) => r.employerContributions),
            ),
            gross: monthProjectRows.reduce((sum, r) => sum + (r.gross || 0), 0),
            netPay: monthProjectRows.reduce((sum, r) => sum + r.netPay, 0),
            isTotal: true,
            isGrandTotal: false,
          };
          employeeRows.push(monthTotal);
          monthlyTotals.push(monthTotal);
        }
      });

      // Calculate grand total for employee
      if (monthlyTotals.length > 0) {
        const grandTotal = {
          employeeCode: '',
          employeeName: '',
          employeeNumber: '',
          branch: '',
          department: '',
          designation: '',
          division: '',
          workingArea: '',
          month: '',
          projectName: 'Grand Total',
          allocatedAmount: monthlyTotals.reduce(
            (sum, r) => sum + r.allocatedAmount,
            0,
          ),
          actualEarnings: sumObjectsByKeys(
            monthlyTotals.map((r) => r.actualEarnings),
          ),
          earnedEarnings: sumObjectsByKeys(
            monthlyTotals.map((r) => r.earnedEarnings),
          ),
          deductions: sumObjectsByKeys(monthlyTotals.map((r) => r.deductions)),
          employerContributions: sumObjectsByKeys(
            monthlyTotals.map((r) => r.employerContributions),
          ),
          gross: monthlyTotals.reduce((sum, r) => sum + (r.gross || 0), 0),
          netPay: monthlyTotals.reduce((sum, r) => sum + r.netPay, 0),
          isTotal: false,
          isGrandTotal: true,
        };
        employeeRows.push(grandTotal);
      }

      reportData.push(...employeeRows);
    });

    // Check if no data after processing
    if (reportData.length === 0) {
      return res.status(200).json({
        status: 200,
        message: 'No data found to export!',
      });
    }

    // Create temporary file path
    const tempFileName = `ProjectWiseSalaryReport_${startMonth}_${endMonth}_${Date.now()}.xlsx`;
    const tempFilePath = path.join(__dirname, '../uploads', tempFileName);

    // Use streaming workbook to write to file
    const workbook = new ExcelJS.stream.xlsx.WorkbookWriter({
      filename: tempFilePath,
      useStyles: true,
      useSharedStrings: false,
    });

    const worksheet = workbook.addWorksheet('Project Wise Salary Report');

    // Build column headers based on type
    let columns = [];

    if (type === 'projectwise') {
      // For projectwise: Project Name header row, then employee details
      columns = [
        { header: 'Employee Code', key: 'employeeCode', width: 15 },
        { header: 'Name', key: 'employeeName', width: 25 },
        { header: 'Number', key: 'employeeNumber', width: 15 },
        { header: 'Branch', key: 'branch', width: 15 },
        { header: 'Department', key: 'department', width: 15 },
        { header: 'Designation', key: 'designation', width: 15 },
        { header: 'Division', key: 'division', width: 15 },
        { header: 'WorkingArea', key: 'workingArea', width: 15 },
        { header: 'Month', key: 'month', width: 12 },
        { header: 'Allocated', key: 'allocatedAmount', width: 12 },
      ];
    } else {
      // For employeewise: Include Project column
      columns = [
        { header: 'Employee Code', key: 'employeeCode', width: 15 },
        { header: 'Name', key: 'employeeName', width: 25 },
        { header: 'Number', key: 'employeeNumber', width: 15 },
        { header: 'Branch', key: 'branch', width: 15 },
        { header: 'Department', key: 'department', width: 15 },
        { header: 'Designation', key: 'designation', width: 15 },
        { header: 'Division', key: 'division', width: 15 },
        { header: 'WorkingArea', key: 'workingArea', width: 15 },
        { header: 'Month', key: 'month', width: 12 },
        { header: 'Project', key: 'projectName', width: 20 },
        { header: 'Allocated', key: 'allocatedAmount', width: 12 },
      ];
    }

    // Add actual earning columns (payhead name only, no prefix) - excludes incentives
    actualEarningCols.forEach((name) => {
      columns.push({ header: name, key: `actual_${name}`, width: 15 });
    });

    // Add earned earning columns with Earn_ prefix
    earningCols.forEach((name) => {
      columns.push({ header: `Earn_${name}`, key: `earn_${name}`, width: 15 });
    });

    // Add Gross column (sum of all earnings)
    columns.push({ header: 'Gross', key: 'gross', width: 12 });

    // Add deduction columns
    deductionCols.forEach((name) => {
      columns.push({ header: name, key: `ded_${name}`, width: 15 });
    });

    // Add Net Pay column (Gross - Employee Deductions)
    columns.push({ header: 'Net Pay', key: 'netPay', width: 12 });

    // Add employer contribution columns
    employerCols.forEach((name) => {
      columns.push({ header: name, key: `emp_${name}`, width: 15 });
    });

    // Add Remarks column at the end for negative value notes
    columns.push({ header: 'Remarks', key: 'remarks', width: 30 });

    // Only set worksheet.columns for employeewise (creates automatic header row)
    // For projectwise, we manually add headers per project section
    if (type !== 'projectwise') {
      worksheet.columns = columns;
    }

    if (type === 'projectwise') {
      // Group data by project for projectwise format
      const projectDataMap = new Map();

      // Collect all unique projects from reportData
      reportData.forEach((row) => {
        if (!row.isTotal && !row.isGrandTotal && row.projectName) {
          if (!projectDataMap.has(row.projectName)) {
            projectDataMap.set(row.projectName, []);
          }
          projectDataMap.get(row.projectName).push(row);
        }
      });

      // Filter to only selected projects if projectId array is provided
      const selectedProjects =
        Array.isArray(projectId) && projectId.length > 0
          ? Array.from(projectDataMap.keys()).filter((pName) => {
              // Find project rows and check if any match the selected projectIds (convert to string for comparison)
              const projectRows = projectDataMap.get(pName);
              const projectIdStrings = projectId.map(String);
              return projectRows.some((r) =>
                projectIdStrings.includes(String(r.projectID)),
              );
            })
          : Array.from(projectDataMap.keys()).sort();

      // Set column widths for projectwise (since we don't use worksheet.columns)
      columns.forEach((col, idx) => {
        worksheet.getColumn(idx + 1).width = col.width;
      });

      // Process each project
      for (const projectName of selectedProjects) {
        const projectRows = projectDataMap.get(projectName);
        if (!projectRows || projectRows.length === 0) continue;

        // Add Project Name header row
        // Define border style
        const borderStyle = {
          top: { style: 'thin' },
          left: { style: 'thin' },
          bottom: { style: 'thin' },
          right: { style: 'thin' },
        };

        const projectHeaderRow = worksheet.addRow({});
        projectHeaderRow.getCell(1).value = `Project Name : ${projectName}`;
        projectHeaderRow.getCell(1).font = { bold: true };
        projectHeaderRow.fill = {
          type: 'pattern',
          pattern: 'solid',
          fgColor: { argb: 'FF4FC3F7' },
        };
        projectHeaderRow.commit();

        // Add column headers row
        const headerRow = worksheet.addRow({});
        columns.forEach((col, idx) => {
          headerRow.getCell(idx + 1).value = col.header;
          headerRow.getCell(idx + 1).border = borderStyle;
        });
        headerRow.font = { bold: true };
        headerRow.fill = {
          type: 'pattern',
          pattern: 'solid',
          fgColor: { argb: 'FFD3D3D3' },
        };
        headerRow.commit();

        // Group by employee within this project
        const employeeDataMap = new Map();
        projectRows.forEach((row) => {
          const empKey = row.employeeCode || row.employeeName;
          if (!employeeDataMap.has(empKey)) {
            employeeDataMap.set(empKey, []);
          }
          employeeDataMap.get(empKey).push(row);
        });

        // Process each employee within this project
        for (const [empKey, empRows] of employeeDataMap) {
          // Sort by month (ascending order using YYYYMM format)
          empRows.sort((a, b) =>
            (a.monthYYYYMM || '').localeCompare(b.monthYYYYMM || ''),
          );

          // Track for showing employee details only on first row
          let isFirstRowForEmployee = true;

          // Add employee rows
          let prevMonth = null;
          for (const row of empRows) {
            // Check if month is same as previous
            const isSameMonth = row.month === prevMonth;

            // Build row values as array (matching column order)
            const rowValues = [];

            // Employee details (show only on first row)
            rowValues.push(isFirstRowForEmployee ? row.employeeCode : '');
            rowValues.push(isFirstRowForEmployee ? row.employeeName : '');
            rowValues.push(isFirstRowForEmployee ? row.employeeNumber : '');
            rowValues.push(isFirstRowForEmployee ? row.branch : '');
            rowValues.push(isFirstRowForEmployee ? row.department : '');
            rowValues.push(isFirstRowForEmployee ? row.designation : '');
            rowValues.push(isFirstRowForEmployee ? row.division : '');
            rowValues.push(isFirstRowForEmployee ? row.workingArea : '');
            rowValues.push(row.month);
            rowValues.push(row.allocatedAmount);

            // Update tracking variables
            prevMonth = row.month;
            isFirstRowForEmployee = false;

            // Add actual earning columns (excludes incentives)
            actualEarningCols.forEach((name) => {
              rowValues.push(row.actualEarnings?.[name] || 0);
            });
            // Add earned earning columns (already set to 0 if negative)
            earningCols.forEach((name) => {
              rowValues.push(row.earnedEarnings?.[name] || 0);
            });

            // Add Gross
            rowValues.push(row.gross);

            // Add deduction columns (already set to 0 if negative)
            deductionCols.forEach((name) => {
              rowValues.push(row.deductions?.[name] || 0);
            });

            // Add Net Pay
            rowValues.push(row.netPay);

            // Add employer columns (already set to 0 if negative)
            employerCols.forEach((name) => {
              rowValues.push(row.employerContributions?.[name] || 0);
            });

            // Add remarks from row data (set during data processing)
            rowValues.push(row.remarks || '');

            const addedRow = worksheet.addRow(rowValues);
            // Add borders to all cells
            addedRow.eachCell({ includeEmpty: true }, (cell) => {
              cell.border = borderStyle;
            });
            addedRow.commit();
          }

          // Add employee total row
          const totalNegativeFields = [];
          const totalValues = [];

          // Employee details (empty for total row)
          totalValues.push(''); // employeeCode
          totalValues.push(''); // employeeName
          totalValues.push(''); // employeeNumber
          totalValues.push(''); // branch
          totalValues.push(''); // department
          totalValues.push(''); // designation
          totalValues.push(''); // division
          totalValues.push(''); // workingArea
          totalValues.push('Total'); // month
          totalValues.push(
            empRows.reduce((sum, r) => sum + (r.allocatedAmount || 0), 0),
          ); // allocatedAmount

          // Add actual earning totals (excludes incentives)
          actualEarningCols.forEach((name) => {
            totalValues.push(
              empRows.reduce(
                (sum, r) => sum + (r.actualEarnings?.[name] || 0),
                0,
              ),
            );
          });
          // Add earned earning totals - check for negative
          earningCols.forEach((name) => {
            const value = empRows.reduce(
              (sum, r) => sum + (r.earnedEarnings?.[name] || 0),
              0,
            );
            if (value < 0) {
              totalNegativeFields.push(`Earn_${name}`);
              totalValues.push(0);
            } else {
              totalValues.push(value);
            }
          });

          // Add Gross total
          totalValues.push(empRows.reduce((sum, r) => sum + (r.gross || 0), 0));

          // Add deduction totals - check for negative
          deductionCols.forEach((name) => {
            const value = empRows.reduce(
              (sum, r) => sum + (r.deductions?.[name] || 0),
              0,
            );
            if (value < 0) {
              totalNegativeFields.push(name);
              totalValues.push(0);
            } else {
              totalValues.push(value);
            }
          });

          // Add Net Pay total
          totalValues.push(
            empRows.reduce((sum, r) => sum + (r.netPay || 0), 0),
          );

          // Add employer totals - check for negative
          employerCols.forEach((name) => {
            const value = empRows.reduce(
              (sum, r) => sum + (r.employerContributions?.[name] || 0),
              0,
            );
            if (value < 0) {
              totalNegativeFields.push(`Employer_${name}`);
              totalValues.push(0);
            } else {
              totalValues.push(value);
            }
          });

          // Add remarks
          totalValues.push(
            totalNegativeFields.length > 0
              ? `Negative value in: ${totalNegativeFields.join(', ')}`
              : '',
          );

          const totalRow = worksheet.addRow(totalValues);
          totalRow.font = { bold: true };
          totalRow.fill = {
            type: 'pattern',
            pattern: 'solid',
            fgColor: { argb: 'FFFFE0B2' },
          };
          // Add borders to total row
          totalRow.eachCell({ includeEmpty: true }, (cell) => {
            cell.border = borderStyle;
          });
          totalRow.commit();

          // Add empty row after each employee
          const empEmptyRow = worksheet.addRow([]);
          empEmptyRow.commit();
        }

        // Add Project Grand Total row
        const projectGrandTotalNegativeFields = [];
        const projectGrandTotalValues = [];

        // Employee details (empty for grand total row)
        projectGrandTotalValues.push(''); // employeeCode
        projectGrandTotalValues.push(''); // employeeName
        projectGrandTotalValues.push(''); // employeeNumber
        projectGrandTotalValues.push(''); // branch
        projectGrandTotalValues.push(''); // department
        projectGrandTotalValues.push(''); // designation
        projectGrandTotalValues.push(''); // division
        projectGrandTotalValues.push(''); // workingArea
        projectGrandTotalValues.push('Project Total'); // month
        projectGrandTotalValues.push(
          projectRows.reduce((sum, r) => sum + (r.allocatedAmount || 0), 0),
        ); // allocatedAmount

        // Add actual earning grand totals (excludes incentives)
        actualEarningCols.forEach((name) => {
          projectGrandTotalValues.push(
            projectRows.reduce(
              (sum, r) => sum + (r.actualEarnings?.[name] || 0),
              0,
            ),
          );
        });
        // Add earned earning grand totals - check for negative
        earningCols.forEach((name) => {
          const value = projectRows.reduce(
            (sum, r) => sum + (r.earnedEarnings?.[name] || 0),
            0,
          );
          if (value < 0) {
            projectGrandTotalNegativeFields.push(`Earn_${name}`);
            projectGrandTotalValues.push(0);
          } else {
            projectGrandTotalValues.push(value);
          }
        });

        // Add Gross grand total
        projectGrandTotalValues.push(
          projectRows.reduce((sum, r) => sum + (r.gross || 0), 0),
        );

        // Add deduction grand totals - check for negative
        deductionCols.forEach((name) => {
          const value = projectRows.reduce(
            (sum, r) => sum + (r.deductions?.[name] || 0),
            0,
          );
          if (value < 0) {
            projectGrandTotalNegativeFields.push(name);
            projectGrandTotalValues.push(0);
          } else {
            projectGrandTotalValues.push(value);
          }
        });

        // Add Net Pay grand total
        projectGrandTotalValues.push(
          projectRows.reduce((sum, r) => sum + (r.netPay || 0), 0),
        );

        // Add employer grand totals - check for negative
        employerCols.forEach((name) => {
          const value = projectRows.reduce(
            (sum, r) => sum + (r.employerContributions?.[name] || 0),
            0,
          );
          if (value < 0) {
            projectGrandTotalNegativeFields.push(`Employer_${name}`);
            projectGrandTotalValues.push(0);
          } else {
            projectGrandTotalValues.push(value);
          }
        });

        // Add remarks
        projectGrandTotalValues.push(
          projectGrandTotalNegativeFields.length > 0
            ? `Negative value in: ${projectGrandTotalNegativeFields.join(', ')}`
            : '',
        );

        const projectGrandTotalRow = worksheet.addRow(projectGrandTotalValues);
        projectGrandTotalRow.font = { bold: true };
        projectGrandTotalRow.fill = {
          type: 'pattern',
          pattern: 'solid',
          fgColor: { argb: 'FFFFCC80' }, // Orange color for project grand total
        };
        // Add borders to project grand total row
        projectGrandTotalRow.eachCell({ includeEmpty: true }, (cell) => {
          cell.border = borderStyle;
        });
        projectGrandTotalRow.commit();

        // Add empty row between projects
        const emptyRow = worksheet.addRow([]);
        emptyRow.commit();
      }
    } else {
      // Employeewise format (original)
      // Define border style
      const borderStyle = {
        top: { style: 'thin' },
        left: { style: 'thin' },
        bottom: { style: 'thin' },
        right: { style: 'thin' },
      };

      // Style and commit header row
      const headerRow = worksheet.getRow(1);
      headerRow.font = { bold: true };
      headerRow.fill = {
        type: 'pattern',
        pattern: 'solid',
        fgColor: { argb: 'FFD3D3D3' },
      };
      // Add borders to header
      headerRow.eachCell({ includeEmpty: true }, (cell) => {
        cell.border = borderStyle;
      });
      headerRow.commit();

      // Group reportData by employee for proper display
      let currentEmployeeRows = [];
      let lastEmployeeKey = null;

      // Helper function to write employee rows
      const writeEmployeeRows = (rows) => {
        if (rows.length === 0) return;

        let isFirstRow = true;
        for (const row of rows) {
          const isTotalRow = row.isTotal || row.isGrandTotal;

          // Show employee details only on first data row (not total rows)
          const showEmployeeDetails = isFirstRow && !isTotalRow;

          const rowData = {
            employeeCode: showEmployeeDetails ? row.employeeCode : '',
            employeeName: showEmployeeDetails ? row.employeeName : '',
            employeeNumber: showEmployeeDetails ? row.employeeNumber : '',
            branch: showEmployeeDetails ? row.branch : '',
            department: showEmployeeDetails ? row.department : '',
            designation: showEmployeeDetails ? row.designation : '',
            division: showEmployeeDetails ? row.division : '',
            workingArea: showEmployeeDetails ? row.workingArea : '',
            month: row.month,
            projectName: row.projectName,
            allocatedAmount: row.allocatedAmount,
            gross: row.gross,
            netPay: row.netPay,
          };

          if (showEmployeeDetails) {
            isFirstRow = false;
          }

          // Add actual earning columns (excludes incentives)
          actualEarningCols.forEach((name) => {
            rowData[`actual_${name}`] = row.actualEarnings?.[name] || 0;
          });
          // Add earned earning columns (already set to 0 if negative)
          earningCols.forEach((name) => {
            rowData[`earn_${name}`] = row.earnedEarnings?.[name] || 0;
          });
          // Add deduction columns (already set to 0 if negative)
          deductionCols.forEach((name) => {
            rowData[`ded_${name}`] = row.deductions?.[name] || 0;
          });
          // Add employer columns (already set to 0 if negative)
          employerCols.forEach((name) => {
            rowData[`emp_${name}`] = row.employerContributions?.[name] || 0;
          });

          // Add remarks from row data (set during data processing)
          rowData.remarks = row.remarks || '';

          const addedRow = worksheet.addRow(rowData);

          // Add borders to all cells
          addedRow.eachCell({ includeEmpty: true }, (cell) => {
            cell.border = borderStyle;
          });

          if (row.isTotal) {
            addedRow.font = { bold: true };
            addedRow.fill = {
              type: 'pattern',
              pattern: 'solid',
              fgColor: { argb: 'FFFFE0B2' },
            };
          } else if (row.isGrandTotal) {
            addedRow.font = { bold: true };
            addedRow.fill = {
              type: 'pattern',
              pattern: 'solid',
              fgColor: { argb: 'FFFFCC80' },
            };
          }

          addedRow.commit();
        }
      };

      // Process reportData and group by employee
      for (const row of reportData) {
        // Get employee key (use employeeCode or employeeName as fallback)
        const employeeKey = row.employeeCode || row.employeeName || '';

        // If this is a new employee (and not a total row), write previous employee's rows
        if (
          employeeKey &&
          employeeKey !== lastEmployeeKey &&
          !row.isTotal &&
          !row.isGrandTotal
        ) {
          // Write previous employee's rows
          if (currentEmployeeRows.length > 0) {
            writeEmployeeRows(currentEmployeeRows);
            // Add empty row between employees
            const emptyRow = worksheet.addRow({});
            emptyRow.commit();
          }
          currentEmployeeRows = [];
          lastEmployeeKey = employeeKey;
        }

        currentEmployeeRows.push(row);
      }

      // Write last employee's rows
      if (currentEmployeeRows.length > 0) {
        writeEmployeeRows(currentEmployeeRows);
      }
    }

    // Commit worksheet and workbook to file
    await worksheet.commit();
    await workbook.commit();

    // Send file to response and delete after sending
    res.download(tempFilePath, tempFileName, (err) => {
      // Delete the temp file after sending (whether success or error)
      fs.unlink(tempFilePath, (unlinkErr) => {
        if (unlinkErr) {
          console.error('Error deleting temp file:', unlinkErr);
        }
      });

      if (err) {
        console.error('Error sending file:', err);
      }
    });
  } catch (error) {
    next(error);
  }
};

function getDateChunks(fromDate, toDate, chunkDays = 10) {
  const result = [];

  const start = new Date(fromDate);
  const end = new Date(toDate);

  // Calculate total days between fromDate and toDate
  const totalDays = Math.floor((end - start) / (1000 * 60 * 60 * 24)) + 1;

  // If total days is less than or equal to chunkDays, return single chunk
  if (totalDays <= chunkDays) {
    result.push({
      fromDate: start.toISOString().slice(0, 10),
      toDate: end.toISOString().slice(0, 10),
    });
    return result;
  }

  // Otherwise, split into chunks
  let currentStart = new Date(start);

  while (currentStart <= end) {
    const chunkStart = new Date(currentStart);
    const chunkEnd = new Date(currentStart);

    chunkEnd.setDate(chunkEnd.getDate() + chunkDays - 1);

    if (chunkEnd > end) {
      chunkEnd.setTime(end.getTime());
    }

    result.push({
      fromDate: chunkStart.toISOString().slice(0, 10),
      toDate: chunkEnd.toISOString().slice(0, 10),
    });

    // Move to next chunk
    currentStart.setDate(currentStart.getDate() + chunkDays);
  }

  return result;
}

exports.expenseReportV2 = async (req, res, next) => {
  try {
    const {
      companyMasterID,
      userMasterID,
      expenseType,
      status,
      expenseStatus,
      page = 1,
      limit = 10,
      exportData,
      exportFileType,
      withAttachment,
      sortField,
    } = await req.body;

    let fromDate = req.body.fromDate;
    let toDate = req.body.toDate;

    const diffInMs = new Date(toDate) - new Date(fromDate);
    const diffInDays = diffInMs / (1000 * 60 * 60 * 24);

    if (diffInDays > 31) {
      return res.status(statusCodes.BAD_REQUEST).json({
        message: 'Date range cannot exceed 31 days',
      });
    }
    const userMasterId = userMasterID || [];

    if (!companyMasterID || !fromDate || !toDate || !expenseType)
      return res
        .status(statusCodes.BAD_REQUEST)
        .json({ message: message.errorMessage.INVALID_FILTER_FIELDS });

    const paginationQuery = {};
    if (!exportData) {
      paginationQuery.offset = (+page - 1) * +limit;
      paginationQuery.limit = +limit;
    }

    const expenseTypeCondition = {};
    if (expenseType === expenseTypes.VISIT) {
      expenseTypeCondition.visitID = { [Sequelize.Op.ne]: null };
    }
    if (expenseType === expenseTypes.TOUR) {
      expenseTypeCondition.ToursMasterID = { [Sequelize.Op.ne]: null };
    }
    if (expenseType === expenseTypes.PERSONAL) {
      expenseTypeCondition.visitID = null;
      expenseTypeCondition.ToursMasterID = null;
      expenseTypeCondition.projectID = null;
      expenseTypeCondition.serviceNumber = null;
    }
    if (expenseType === expenseTypes.PROJECT) {
      expenseTypeCondition.projectID = { [Sequelize.Op.ne]: null };
    }
    if (expenseType === expenseTypes.SERVICE) {
      expenseTypeCondition.serviceNumber = {
        [Sequelize.Op.ne]: null,
      };
    }
    const condition = { status: { [Sequelize.Op.ne]: 10 } };
    if (expenseStatus === expenseApprovalTypes.PAID) {
      condition.authorizationStatus = '3';
      condition[Sequelize.Op.or] = [
        { erpJvid: { [Sequelize.Op.ne]: null } },
        { payment_Id: { [Sequelize.Op.ne]: null } },
      ];
    } else if (expenseStatus === expenseApprovalTypes.APPROVED) {
      condition.authorizationStatus = '3';
      condition.erpJvid = { [Sequelize.Op.eq]: null };
      condition.payment_Id = { [Sequelize.Op.eq]: null };
    } else if (expenseStatus === expenseApprovalTypes.PENDING) {
      condition.authorizationStatus = { [Sequelize.Op.in]: ['0', '1', '2'] };
    } else if (expenseStatus === expenseApprovalTypes.REJECTED) {
      condition.authorizationStatus = '4';
    }

    const currentDate = asiaKolkataDateTime(new Date()).slice(0, 10);
    const userAccessCondition = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: !companyMasterID,
    });
    if (exportData && (exportFileType == 'xlsx' || exportFileType == 'PDF')) {
      const daysCount =
        companyMasterID == companyMasterIDENUM.MEHTA_HIGHTECH_INDUSTRIES
          ? 10
          : 31;
      const chunkDates = getDateChunks(fromDate, toDate, daysCount);
      const exportDir = path.join(
        __dirname,
        `../uploads/temp-Expense-report/${companyMasterID}/expense_${Date.now()}`,
      );
      fs.mkdirSync(exportDir, { recursive: true });
      const fileNamessArrary = [];

      for (let chunk of chunkDates) {
        fromDate = chunk.fromDate;
        toDate = chunk.toDate;

        console.log('🟢 Initial Memory:', formatMemoryToShow());

        let order = [];
        if (sortField === orderByEmployeeMasterFields.EMPLOYEECODE) {
          const employeeCodeSubquery = `(
    SELECT ejd."employeeCode"
    FROM "employeeJoiningDetails" ejd
    WHERE ejd."userMasterID" = (
      SELECT ue."userMasterID"
      FROM "userExpenses" ue
      WHERE ue."userExpenseID" = "userExpenseTransaction"."userExpenseID"
      LIMIT 1
    )
    LIMIT 1
  )`;

          order = [
            [
              Sequelize.literal(
                `CASE WHEN ${employeeCodeSubquery} IS NULL OR ${employeeCodeSubquery} = '' THEN 0 ELSE 1 END`,
              ),
              'ASC',
            ],
            [
              Sequelize.literal(
                `CASE WHEN ${employeeCodeSubquery} ~ '^[0-9]+$' THEN 0 ELSE 1 END`,
              ),
              'ASC',
            ],
            [
              Sequelize.literal(
                `CASE WHEN ${employeeCodeSubquery} ~ '^[0-9]+$' THEN (${employeeCodeSubquery})::int END`,
              ),
              'ASC',
            ],
            [
              Sequelize.literal(
                `substring(${employeeCodeSubquery} FROM '^[^0-9]+')`,
              ),
              'ASC',
            ],
            [
              Sequelize.literal(
                `CASE WHEN ${employeeCodeSubquery} ~ '[0-9]+' THEN substring(${employeeCodeSubquery} FROM '[0-9]+')::int END`,
              ),
              'ASC',
            ],
            [Sequelize.literal(employeeCodeSubquery), 'ASC'],
            [
              Sequelize.literal(`(
      SELECT um."displayName" FROM "userMasters" um
      WHERE um."userMasterID" = (
        SELECT ue."userMasterID" FROM "userExpenses" ue
        WHERE ue."userExpenseID" = "userExpenseTransaction"."userExpenseID"
        LIMIT 1
      )
      LIMIT 1
    )`),
              'ASC',
            ],
            [Sequelize.literal(`"userExpense.expense_date"`), 'DESC'],
            [Sequelize.literal(`"userExpense.userExpenseID"`), 'DESC'],
          ];
        } else if (sortField == orderByEmployeeMasterFields.EMPLOYEENAME) {
          order = [
            [
              Sequelize.literal(`(
      SELECT um."displayName" FROM "userMasters" um
      WHERE um."userMasterID" = (
        SELECT ue."userMasterID" FROM "userExpenses" ue
        WHERE ue."userExpenseID" = "userExpenseTransaction"."userExpenseID"
        LIMIT 1
      )
      LIMIT 1
    )`),
              'ASC',
            ],
            [Sequelize.literal(`"userExpense.expense_date"`), 'DESC'],
            [Sequelize.literal(`"userExpense.userExpenseID"`), 'DESC'],
          ];
        } else {
          order = [
            [Sequelize.literal(`"userExpense.expense_date"`), 'DESC'],
            [Sequelize.literal(`"userExpense.userExpenseID"`), 'DESC'],
            [
              Sequelize.literal(`(
      SELECT um."displayName" FROM "userMasters" um
      WHERE um."userMasterID" = (
        SELECT ue."userMasterID" FROM "userExpenses" ue
        WHERE ue."userExpenseID" = "userExpenseTransaction"."userExpenseID"
        LIMIT 1
      )
      LIMIT 1
    )`),
              'ASC',
            ],
          ];
        }
        const userExpenseData = await UserExpenseTransaction.findAll({
          // subQuery: false,
          distinct: true,
          where: condition,
          include: [
            {
              model: UserMaster,
              as: 'authorizer',
              attributes: ['displayName'],
            },
            {
              model: ExpenseAuthorizationRequest,
              as: 'Auth',
              include: [
                {
                  model: UserMaster,
                  as: 'authorizedPerson',
                  attributes: ['displayName', 'userMasterID', 'userNumber'],
                },
              ],
            },
            {
              model: AuthorizationCriteriaMaster,
              attributes: ['AuthorizationCriteria'],
            },
            {
              model: ExpenseHead,
              attributes: [
                'expenseHeadId',
                'expenseHead',
                'accountHeadID',
                'expenseCategoryId',
              ],
              include: [
                {
                  model: ExpenseCategory,
                  attributes: ['expenseCategoryId', 'expenseCategory'],
                },
              ],
            },
            {
              model: ExpensePurpose,
              as: 'ep',
              attributes: ['expensePurposeID', 'name'],
            },
            {
              model: UserExpense,
              as: 'userExpense',
              where: {
                userMasterID: [...userMasterId],
                expense_date: {
                  [Sequelize.Op.between]: [
                    new Date(fromDate),
                    new Date(toDate),
                  ],
                },
                ...expenseTypeCondition,
              },
              attributes: [
                'userExpenseID',
                'visitID',
                'userMasterID',
                'ToursMasterID',
                'expense_date',
                'projectID',
                'serviceNumber',
                'serviceDate',
              ],
              include: [
                {
                  model: UserMaster,
                  where: {
                    companyMasterId: companyMasterID,
                    status,
                    ...userAccessCondition.where,
                  },
                  required: true,
                  attributes: [
                    'displayName',
                    'userMasterID',
                    'userNumber',
                    'companyMasterId',
                  ],
                  include: [
                    ...userAccessCondition.includeModels,
                    {
                      model: EmployeeJoiningDetails,
                      as: 'emp_join',
                      attributes: [
                        'userMasterID',
                        'bankAccountNo',
                        'bankIFSC',
                        'bankMasterID',
                        'employeeCode',
                        'bankAccountStatus',
                      ],
                      include: [
                        { model: BankMaster, attributes: ['bankName'] },
                      ],
                    },
                    {
                      required: false,
                      model: EmployeeBranch,
                      as: 'emp_branch',
                      where: {
                        status: 1,
                        applicableDate: {
                          [Sequelize.Op.lte]: new Date(currentDate),
                        },
                        [Sequelize.Op.or]: [
                          {
                            endDate: {
                              [Sequelize.Op.gte]: new Date(currentDate),
                            },
                          },
                          { endDate: { [Sequelize.Op.eq]: null } },
                        ],
                      },
                      attributes: ['branchID'],
                      include: [
                        {
                          model: BranchMaster,
                          as: 'branchMaster',
                          attributes: ['branchName', 'branchAddress'],
                        },
                      ],
                    },
                    {
                      required: false,
                      model: EmployeeDepartment,
                      as: 'emp_dept',
                      attributes: ['departmentID'],
                      where: {
                        status: 1,
                        applicableDate: {
                          [Sequelize.Op.lte]: new Date(currentDate),
                        },
                        [Sequelize.Op.or]: [
                          {
                            endDate: {
                              [Sequelize.Op.gte]: new Date(currentDate),
                            },
                          },
                          { endDate: { [Sequelize.Op.eq]: null } },
                        ],
                      },
                      include: [
                        {
                          model: Department,
                          as: 'department',
                          attributes: ['departmentName'],
                        },
                      ],
                    },
                    {
                      required: false,
                      model: EmployeeDesignation,
                      as: 'emp_desig',
                      attributes: ['designationID'],
                      where: {
                        status: 1,
                        applicableDate: {
                          [Sequelize.Op.lte]: new Date(currentDate),
                        },
                        [Sequelize.Op.or]: [
                          {
                            endDate: {
                              [Sequelize.Op.gte]: new Date(currentDate),
                            },
                          },
                          { endDate: { [Sequelize.Op.eq]: null } },
                        ],
                      },
                      include: [
                        {
                          model: Designation,
                          as: 'designation',
                          attributes: ['designationName'],
                        },
                      ],
                    },
                    {
                      required: false,
                      model: EmployeeDivision,
                      as: 'emp_div',

                      where: {
                        status: 1,
                        startDate: { [Sequelize.Op.lte]: currentDate },
                        [Sequelize.Op.or]: [
                          { endDate: { [Sequelize.Op.gte]: currentDate } },
                          { endDate: { [Sequelize.Op.eq]: null } },
                        ],
                      },
                      attributes: ['divisionId', 'startDate'],
                      include: [
                        { model: Division, attributes: ['divisionName'] },
                      ],
                    },
                    {
                      required: false,
                      model: EmployeeWorkingArea,
                      as: 'emp_area',
                      where: {
                        status: 1,
                        startDate: { [Sequelize.Op.lte]: currentDate },
                        [Sequelize.Op.or]: [
                          { endDate: { [Sequelize.Op.gte]: currentDate } },
                          { endDate: { [Sequelize.Op.eq]: null } },
                        ],
                      },
                      attributes: ['workingAreaId', 'startDate'],
                      include: [
                        { model: WorkingArea, attributes: ['workingAreaName'] },
                      ],
                    },
                  ],
                },
                {
                  model: Visit,
                  attributes: ['visitID'],
                  include: [
                    {
                      model: Customer,
                      attributes: ['customerID', 'companyName', 'customerName'],
                    },
                  ],
                },
                {
                  model: toursMaster,
                  attributes: ['ToursMasterID', 'ToursName'],
                },
                { model: Project, attributes: ['projectID', 'projectName'] },
              ],
            },
            {
              model: CityMaster,
              as: 'cityMaster',
              required: false,
              attributes: [
                'cityMasterID',
                'cityName',
                'isMetro',
                'stateMasterID',
              ],
              include: [
                {
                  model: StateMaster,
                  required: false,
                  attributes: ['stateMasterID', 'stateName'],
                },
              ],
            },
          ],
          order,
        });

        if (userExpenseData.length == 0) {
          continue;
        }
        const objectForExcel = userExpenseData.map((element) => {
          const jsonData = element.toJSON();

          const userExpense = jsonData.userExpense;
          const userMaster = userExpense?.userMaster;
          const joining = userMaster?.emp_join?.[0];

          /** ---------------- Status ---------------- */
          let AuthsStatus = 'Pending';
          const authStatus = +jsonData.authorizationStatus;

          if (authStatus === 4) AuthsStatus = 'Rejected';
          else if (authStatus === 3) {
            AuthsStatus =
              jsonData.erpJvid || jsonData.payment_Id ? 'Paid' : 'Accepted';
          }

          /** ---------------- Bank Details ---------------- */
          if (joining?.bankAccountStatus === 1) {
            userMaster.accountNo ||= joining.bankAccountNo || '';
            userMaster.ifscCode ||= joining.bankIFSC || '';
            userMaster.bankName ||= joining.bankMaster?.bankName || '';
          }
          const empInfo = parseEmployeeInfoAlias(userMaster) || {};
          /** ---------------- Authorization Text ---------------- */
          const joinvalue = exportFileType == 'PDF' ? ', ' : '\n';
          const authorizationText =
            jsonData.Auth?.reduce((acc, el) => {
              if (+el.ReferenceID !== jsonData.userExpenseTransactionID)
                return acc;

              const statusMap = {
                1: 'Accepted',
                0: 'Rejected',
              };

              acc.push(
                `${el.authorizedPerson?.displayName || ''} - ${
                  statusMap[el.authstatus] || 'Pending'
                }`,
              );
              return acc;
            }, []).join(joinvalue) || '';
          let ExpenseType = '';
          if (userExpense.visitID) ExpenseType = expenseTypes.VISIT;
          else if (userExpense.ToursMasterID) ExpenseType = expenseTypes.TOUR;
          else if (userExpense.projectID) ExpenseType = expenseTypes.PROJECT;
          else if (userExpense.serviceNumber)
            ExpenseType = expenseTypes.SERVICE;
          else ExpenseType = expenseTypes.PERSONAL;
          const expenseData = {
            'Employee Code': empInfo.employeeCode || '',
            User: userMaster?.displayName || '',
            'User Number': userMaster?.userNumber || '',
            Branch: empInfo.branch || '',
            Department: empInfo.department || '',
            Designation: empInfo.designation || '',
            Division: empInfo.division || '',
            WorkingArea: empInfo.workingArea || '',
            'Expense Type': userExpense?.ToursMaster
              ? expenseTypes.TOUR
              : userExpense?.visit
                ? expenseTypes.VISIT
                : userExpense?.project
                  ? expenseTypes.PROJECT
                  : userExpense?.serviceNumber
                    ? expenseTypes.SERVICE
                    : expenseTypes.PERSONAL,
            'Expense Applied Date': moment(jsonData.createdAt).format(
              'DD-MM-YYYY HH:mm',
            ),
            'Expense Date': userExpense?.expense_date,
            'Expense Amount': jsonData.expenseAmount,
            'Expense Purpose': jsonData.ep?.name || '',
            'Expense Category':
              jsonData.expenseHead?.expenseCategory?.expenseCategory || '',
            'Expense Head': jsonData.expenseHead?.expenseHead || '',
            Status: AuthsStatus,
            'Final Authorized By': jsonData.authorizer?.displayName || '',
            'Final Authorized At': jsonData.authorizedAt
              ? moment(jsonData.authorizedAt).format('DD-MM-YYYY HH:mm')
              : '',
            'Final Authorized Remarks': jsonData.authorizerRemark || '',
            'Policy Type': '',
            City: '',
            State: '',
            'Check-in Date': '',
            'Check-out Date': '',
            'Total Days': '',
            Transportation: '',
            'Authorization Criteria':
              jsonData.AuthorizationCriteriaMaster?.AuthorizationCriteria || '',
            Authorization: authorizationText,

            'Visit To': userExpense?.visit
              ? `${userExpense.visit?.customer?.companyName}-${userExpense.visit?.customer?.customerName}`
              : '',
            Tour: userExpense?.ToursMaster?.ToursName || '',
            Project: userExpense?.project?.projectName || '',
          };

          // Add expense policy related fields with default empty values

          // Now populate the fields with actual data
          if (jsonData.policyType) {
            // Convert policy type to user-friendly format
            const policyTypeLabels = {
              accommodation: 'Accommodation',
              food: 'Food',
              localTransport: 'Local Transport',
              outstationTravel: 'Outstation Travel',
              ownVehicle: 'Own Vehicle',
            };
            expenseData['Policy Type'] =
              policyTypeLabels[jsonData.policyType] || jsonData.policyType;
          }
          if (jsonData.cityMaster) {
            expenseData['City'] = jsonData.cityMaster.cityName || '';

            if (jsonData.cityMaster.stateMaster) {
              expenseData['State'] =
                jsonData.cityMaster.stateMaster.stateName || '';
            }
          }
          // Accommodation fields
          if (jsonData.checkInDate) {
            expenseData['Check-in Date'] = moment(jsonData.checkInDate).format(
              'DD-MM-YYYY',
            );
          }
          if (jsonData.checkOutDate) {
            expenseData['Check-out Date'] = moment(
              jsonData.checkOutDate,
            ).format('DD-MM-YYYY');
          }
          if (jsonData.days) {
            expenseData['Total Days'] = jsonData.days;
          }

          // Consolidated Transportation column
          if (
            jsonData.policyType === 'localTransport' ||
            jsonData.policyType === 'outstationTravel' ||
            jsonData.policyType === 'ownVehicle'
          ) {
            let transportationValue = '';

            if (jsonData.policyType === 'ownVehicle') {
              // For own vehicle: show "Two Wheeler, 500 KM" format
              if (jsonData.vehicleType) {
                const vehicleTypeLabel =
                  jsonData.vehicleType === 'twoWheeler'
                    ? 'Two Wheeler'
                    : jsonData.vehicleType === 'fourWheeler'
                      ? 'Four Wheeler'
                      : jsonData.vehicleType;
                transportationValue = vehicleTypeLabel;

                if (
                  typeof jsonData.value !== 'undefined' &&
                  jsonData.value !== null
                ) {
                  transportationValue += `, ${jsonData.value} KM`;
                }
              } else if (
                typeof jsonData.value !== 'undefined' &&
                jsonData.value !== null
              ) {
                // If only distance is available
                transportationValue = `${jsonData.value} KM`;
              }
            } else {
              // For local transport or outstation travel: just show the transport name
              if (jsonData.vehicleType) {
                transportationValue = jsonData.vehicleType;
              }
            }

            expenseData['Transportation'] = transportationValue;
          }

          // 👇 INSERT HERE (after Project)
          if (
            companyMasterID == companyMasterIDENUM.MEHTA_HIGHTECH_INDUSTRIES &&
            showServiceLabel
          ) {
            expenseData.Service = userExpense?.serviceNumber || '';
            expenseData['Service Date'] = userExpense?.serviceDate
              ? moment(userExpense.serviceDate).format('DD-MM-YYYY')
              : '';
          }

          // 👇 continue remaining fields
          expenseData.Description = jsonData.description;
          expenseData.Version = jsonData.version;
          expenseData.ErpJvid = jsonData.erpJvid || '';
          expenseData['Bank Name'] = userMaster?.bankName || '';
          expenseData['Account Number'] = userMaster?.accountNo || '';
          expenseData['IFSC Code'] = userMaster?.ifscCode || '';

          /** ---------------- Attachments ---------------- */
          // Excel always gets attachment columns: thumbnails when
          // withAttachment is true, otherwise a "View" link to the frontend viewer
          if (withAttachment || exportFileType !== 'PDF') {
            expenseData['Attachment-1'] = {
              original: jsonData.attachFile,
              thumbnail: jsonData.attachThumb,
              s3UploadattachFile: jsonData.s3UploadattachFile,
            };
            expenseData['Attachment-2'] = {
              original: jsonData.attachFile2,
              thumbnail: jsonData.attach2Thumb,
              s3UploadattachFile: jsonData.s3UploadattachFile2,
            };
            expenseData['Attachment-3'] = {
              original: jsonData.attachFile3,
              thumbnail: jsonData.attach3Thumb,
              s3UploadattachFile: jsonData.s3UploadattachFile3,
            };
            expenseData['Attachment-4'] = {
              original: jsonData.attachFile4,
              thumbnail: jsonData.attach4Thumb,
              s3UploadattachFile: jsonData.s3UploadattachFile4,
            };
          }

          return expenseData;
        });
        if (exportFileType == 'PDF') {
          const companyDetails = await companyMaster.findOne({
            where: { companyMasterID: companyMasterID },
            raw: true,
          });

          const [result] = await UserExpenseTransaction.findAll({
            raw: true,
            subQuery: false,

            where: {
              status: { [Sequelize.Op.ne]: 10 },
            },

            attributes: [
              // Pending Amount
              [
                sequelize.literal(`
        COALESCE(
          SUM(
            CASE 
              WHEN "userExpenseTransaction"."authorizationStatus" IN (0,1,2)
              THEN "userExpenseTransaction"."expenseAmount"
              ELSE 0
            END
          ),
        0)
      `),
                'Pending',
              ],

              // Approved Amount
              [
                sequelize.literal(`
        COALESCE(
          SUM(
            CASE 
              WHEN "userExpenseTransaction"."authorizationStatus" = 3
               AND "userExpenseTransaction"."erpJvid" IS NULL
               AND "userExpenseTransaction"."payment_Id" IS NULL
              THEN "userExpenseTransaction"."expenseAmount"
              ELSE 0
            END
          ),
        0)
      `),
                'Approved',
              ],

              // Paid Amount
              [
                sequelize.literal(`
        COALESCE(
          SUM(
            CASE 
              WHEN "userExpenseTransaction"."authorizationStatus" = 3
               AND (
                 "userExpenseTransaction"."erpJvid" IS NOT NULL
                 OR "userExpenseTransaction"."payment_Id" IS NOT NULL
               )
              THEN "userExpenseTransaction"."expenseAmount"
              ELSE 0
            END
          ),
        0)
      `),
                'Paid',
              ],

              // Rejected Amount
              [
                sequelize.literal(`
        COALESCE(
          SUM(
            CASE 
              WHEN "userExpenseTransaction"."authorizationStatus" = 4
              THEN "userExpenseTransaction"."expenseAmount"
              ELSE 0
            END
          ),
        0)
      `),
                'Rejected',
              ],
            ],

            include: [
              {
                model: UserExpense,
                as: 'userExpense',
                attributes: [],
                required: true,

                where: {
                  userMasterID: [...userMasterId],

                  expense_date: {
                    [Sequelize.Op.between]: [
                      new Date(fromDate),
                      new Date(toDate),
                    ],
                  },

                  ...expenseTypeCondition,
                },

                include: [
                  {
                    model: UserMaster,
                    attributes: [],
                    required: true,

                    where: {
                      companyMasterId: companyMasterID,
                      status,
                      ...userAccessCondition.where,
                    },

                    include: [...userAccessCondition.includeModels],
                  },
                ],
              },
            ],
          });
          const totalExpenseData =
            (+result?.Pending || 0) +
            (+result?.Approved || 0) +
            (+result?.Paid || 0) +
            (+result?.Rejected || 0);
          const { companyName, companyAddress, companyLogo } = companyDetails;
          const headers = Object.keys(objectForExcel[0]);
          const pdfData = {
            datalength: headers.length,
            companyName,
            companyAddress,
            companyLogo,
            headers,
            MainData: objectForExcel,
            ApiURL: mainApiUrl,
            ExpensePending: +result?.Pending || 0,
            ExpenseApproved: +result?.Approved || 0,
            ExpensePaid: +result?.Paid || 0,
            ExpenseRejected: +result?.Rejected || 0,
            totalExpenseData,
          };

          const getTemplate1 = (type) => {
            const file = path.join(__dirname, `../html/${type}.html`);
            return file;
          };

          Handlebars.registerHelper({
            eq: (v1, v2) => v1 === v2,
            ne: (v1, v2) => v1 !== v2,
            lt: (v1, v2) => v1 < v2,
            gt: (v1, v2) => v1 > v2,
            lte: (v1, v2) => v1 <= v2,
            gte: (v1, v2) => v1 >= v2,
            and() {
              return Array.prototype.every.call(arguments, Boolean);
            },
            or() {
              return Array.prototype.slice.call(arguments, 0, -1).some(Boolean);
            },
          });

          const readFile = (name) => {
            return new Promise((resolve, reject) => {
              fs.readFile(name, 'utf-8', (err, result) => {
                if (err) {
                  reject(err);
                } else {
                  resolve(result);
                }
              });
            });
          };

          const filePath = await getTemplate1('expenseReportHtml');
          const file = await readFile(filePath);
          const template = Handlebars.compile(file);
          const html = template(pdfData);

          const browser = await puppeteer.launch({
            headless: 'new',
            args: ['--no-sandbox'],
          });
          const page = await browser.newPage();
          await page.setContent(html);
          const pdfBuffer = await page.pdf({
            format: 'A4',
            printBackground: true,
            landscape: true,
            timeout: 120000,
          });
          await browser.close();

          if (!objectForExcel.length) continue;

          // Save PDF to file instead of returning base64
          const fileName = `Expense_${fromDate}_to_${toDate}.pdf`;
          const pdfFilePath = path.join(exportDir, fileName);

          // Write PDF buffer to file
          fs.writeFileSync(pdfFilePath, pdfBuffer);

          // Add to array for zipping
          fileNamessArrary.push({ filePath: pdfFilePath, fileName });

          console.log('🟢 After PDF Save Memory:', formatMemoryToShow());
        } else {
          console.log('🟢 After Process Memory:', formatMemoryToShow());

          if (!objectForExcel.length) continue;

          const fileName = `Expense_${fromDate}_to_${toDate}.${exportFileType}`;
          const filePath = path.join(exportDir, fileName);
          console.log('Rows:', objectForExcel.length);
          console.log(
            'JSON Size MB:',
            (
              Buffer.byteLength(JSON.stringify(objectForExcel)) /
              1024 /
              1024
            ).toFixed(2),
          );

          await generateExcelForExpenseReport(
            objectForExcel,
            `Expense_${fromDate}_to_${toDate}`,
            'xlsx',
            res,
            {
              saveToFile: true,
              filePath,
              showThumbnail: Boolean(withAttachment),
              totalColumns: ['Expense Amount'],

              isWrapText: (cell, colNum) => {
                const header = cell._column?.key;

                return header === 'Authorization';
              },
            },
          );

          fileNamessArrary.push({ filePath, fileName });
        }
      }
      console.log('🟢 Before Zip Memory:', formatMemoryToShow());
      const zip = new JSZip();
      for (let fileData of fileNamessArrary) {
        const excelBuffer = fs.readFileSync(fileData.filePath);
        console.log('🟢 After Excel Buffer Memory:', formatMemoryToShow());
        // Add to zip
        zip.file(fileData.fileName, excelBuffer);
        console.log('🟢 After Add in Zip:', formatMemoryToShow());
        // Delete the individual file after adding to zip
        fs.unlinkSync(fileData.filePath);
        console.log('🟢 After Remove File Memory:', formatMemoryToShow());
      }
      // Generate zip file
      const zipBuffer = await zip.generateAsync({ type: 'nodebuffer' });
      const zipPath = path.join(exportDir, 'Expense_Report.zip');
      console.log('🟢 After Zip Buffer Memory:', formatMemoryToShow());

      // Write zip to file
      fs.writeFileSync(zipPath, zipBuffer);
      console.log('🟢 After Zip Write Memory:', formatMemoryToShow());

      // Send the zip file to user and cleanup after download
      res.download(zipPath, 'Expense_Report.zip', (err) => {
        // Cleanup: Remove the temporary directory after download
        if (fs.existsSync(exportDir)) {
          fs.rmSync(exportDir, { recursive: true, force: true });
        }

        if (err) {
          console.error('Error downloading zip:', err);
        }
      });

      return;
    }
    let order = [];
    if (sortField === orderByEmployeeMasterFields.EMPLOYEECODE) {
      const employeeCodeSubquery = `(
    SELECT ejd."employeeCode"
    FROM "employeeJoiningDetails" ejd
    WHERE ejd."userMasterID" = (
      SELECT ue."userMasterID"
      FROM "userExpenses" ue
      WHERE ue."userExpenseID" = "userExpenseTransaction"."userExpenseID"
      LIMIT 1
    )
    LIMIT 1
  )`;

      order = [
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} IS NULL OR ${employeeCodeSubquery} = '' THEN 0 ELSE 1 END`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} ~ '^[0-9]+$' THEN 0 ELSE 1 END`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} ~ '^[0-9]+$' THEN (${employeeCodeSubquery})::int END`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `substring(${employeeCodeSubquery} FROM '^[^0-9]+')`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} ~ '[0-9]+' THEN substring(${employeeCodeSubquery} FROM '[0-9]+')::int END`,
          ),
          'ASC',
        ],
        [Sequelize.literal(employeeCodeSubquery), 'ASC'],
        [
          Sequelize.literal(`(
      SELECT um."displayName" FROM "userMasters" um
      WHERE um."userMasterID" = (
        SELECT ue."userMasterID" FROM "userExpenses" ue
        WHERE ue."userExpenseID" = "userExpenseTransaction"."userExpenseID"
        LIMIT 1
      )
      LIMIT 1
    )`),
          'ASC',
        ],
        [Sequelize.literal(`"userExpense.expense_date"`), 'DESC'],
        [Sequelize.literal(`"userExpense.userExpenseID"`), 'DESC'],
      ];
    } else {
      order = [
        [
          Sequelize.literal(`(
      SELECT um."displayName" FROM "userMasters" um
      WHERE um."userMasterID" = (
        SELECT ue."userMasterID" FROM "userExpenses" ue
        WHERE ue."userExpenseID" = "userExpenseTransaction"."userExpenseID"
        LIMIT 1
      )
      LIMIT 1
    )`),
          'ASC',
        ],
        [Sequelize.literal(`"userExpense.expense_date"`), 'DESC'],
        [Sequelize.literal(`"userExpense.userExpenseID"`), 'DESC'],
      ];
    }
    const [userExpenseData, count] = await Promise.all([
      UserExpenseTransaction.findAll({
        // subQuery: false,
        distinct: true,
        where: { ...condition },
        ...paginationQuery,
        include: [
          {
            model: UserMaster,
            as: 'authorizer',
            attributes: ['displayName'],
          },
          {
            model: ExpenseAuthorizationRequest,
            as: 'Auth',
            include: [
              {
                model: UserMaster,
                as: 'authorizedPerson',
                attributes: ['displayName', 'userMasterID', 'userNumber'],
              },
            ],
          },
          {
            model: AuthorizationCriteriaMaster,
            attributes: ['AuthorizationCriteria'],
          },
          {
            model: ExpenseHead,
            attributes: [
              'expenseHeadId',
              'expenseHead',
              'accountHeadID',
              'expenseCategoryId',
            ],
            include: [
              {
                model: ExpenseCategory,
                attributes: ['expenseCategoryId', 'expenseCategory'],
              },
            ],
          },
          {
            model: ExpensePurpose,
            as: 'ep',
            attributes: ['expensePurposeID', 'name'],
          },
          {
            model: UserExpense,
            as: 'userExpense',
            where: {
              userMasterID: [...userMasterId],
              expense_date: {
                [Sequelize.Op.between]: [new Date(fromDate), new Date(toDate)],
              },
              ...expenseTypeCondition,
            },
            attributes: [
              'userExpenseID',
              'visitID',
              'userMasterID',
              'ToursMasterID',
              'expense_date',
              'projectID',
              'serviceNumber',
              'serviceDate',
            ],
            include: [
              {
                model: UserMaster,
                where: {
                  companyMasterId: companyMasterID,
                  status,
                  ...userAccessCondition.where,
                },
                required: true,
                attributes: ['displayName', 'userMasterID', 'userNumber'],
                include: [
                  ...userAccessCondition.includeModels,
                  {
                    model: EmployeeJoiningDetails,
                    as: 'emp_join',
                    attributes: [
                      'userMasterID',
                      'bankAccountNo',
                      'bankIFSC',
                      'bankMasterID',
                      'employeeCode',
                      'bankAccountStatus',
                    ],
                    include: [{ model: BankMaster, attributes: ['bankName'] }],
                  },
                  {
                    required: false,
                    model: EmployeeBranch,
                    as: 'emp_branch',
                    where: {
                      status: 1,
                      applicableDate: {
                        [Sequelize.Op.lte]: new Date(currentDate),
                      },
                      [Sequelize.Op.or]: [
                        {
                          endDate: {
                            [Sequelize.Op.gte]: new Date(currentDate),
                          },
                        },
                        { endDate: { [Sequelize.Op.eq]: null } },
                      ],
                    },
                    attributes: ['branchID'],
                    include: [
                      {
                        model: BranchMaster,
                        as: 'branchMaster',
                        attributes: ['branchName', 'branchAddress'],
                      },
                    ],
                  },
                  {
                    required: false,
                    model: EmployeeDepartment,
                    as: 'emp_dept',
                    attributes: ['departmentID'],
                    where: {
                      status: 1,
                      applicableDate: {
                        [Sequelize.Op.lte]: new Date(currentDate),
                      },
                      [Sequelize.Op.or]: [
                        {
                          endDate: {
                            [Sequelize.Op.gte]: new Date(currentDate),
                          },
                        },
                        { endDate: { [Sequelize.Op.eq]: null } },
                      ],
                    },
                    include: [
                      {
                        model: Department,
                        as: 'department',
                        attributes: ['departmentName'],
                      },
                    ],
                  },
                  {
                    required: false,
                    model: EmployeeDesignation,
                    as: 'emp_desig',
                    attributes: ['designationID'],
                    where: {
                      status: 1,
                      applicableDate: {
                        [Sequelize.Op.lte]: new Date(currentDate),
                      },
                      [Sequelize.Op.or]: [
                        {
                          endDate: {
                            [Sequelize.Op.gte]: new Date(currentDate),
                          },
                        },
                        { endDate: { [Sequelize.Op.eq]: null } },
                      ],
                    },
                    include: [
                      {
                        model: Designation,
                        as: 'designation',
                        attributes: ['designationName'],
                      },
                    ],
                  },
                  {
                    required: false,
                    model: EmployeeDivision,
                    as: 'emp_div',

                    where: {
                      status: 1,
                      startDate: { [Sequelize.Op.lte]: currentDate },
                      [Sequelize.Op.or]: [
                        { endDate: { [Sequelize.Op.gte]: currentDate } },
                        { endDate: { [Sequelize.Op.eq]: null } },
                      ],
                    },
                    attributes: ['divisionId', 'startDate'],
                    include: [
                      { model: Division, attributes: ['divisionName'] },
                    ],
                  },
                  {
                    required: false,
                    model: EmployeeWorkingArea,
                    as: 'emp_area',
                    where: {
                      status: 1,
                      startDate: { [Sequelize.Op.lte]: currentDate },
                      [Sequelize.Op.or]: [
                        { endDate: { [Sequelize.Op.gte]: currentDate } },
                        { endDate: { [Sequelize.Op.eq]: null } },
                      ],
                    },
                    attributes: ['workingAreaId', 'startDate'],
                    include: [
                      { model: WorkingArea, attributes: ['workingAreaName'] },
                    ],
                  },
                ],
              },
              {
                model: Visit,
                attributes: ['visitID'],
                include: [
                  {
                    model: Customer,
                    attributes: ['customerID', 'companyName', 'customerName'],
                  },
                ],
              },
              {
                model: toursMaster,
                attributes: ['ToursMasterID', 'ToursName'],
              },
              { model: Project, attributes: ['projectID', 'projectName'] },
            ],
          },
          {
            model: CityMaster,
            as: 'cityMaster',
            required: false,
            attributes: [
              'cityMasterID',
              'cityName',
              'isMetro',
              'stateMasterID',
            ],
            include: [
              {
                model: StateMaster,
                required: false,
                attributes: ['stateMasterID', 'stateName'],
              },
            ],
          },
        ],
        // order: [
        //   [{ model: UserExpense, as: 'userExpense' }, 'expense_date', 'ASC'],
        // ],
        order: order,
      }),
      UserExpenseTransaction.count({
        where: { ...condition },
        include: [
          {
            model: UserExpense,
            as: 'userExpense',
            where: {
              userMasterID: [...userMasterId],
              expense_date: {
                [Op.between]: [fromDate, toDate],
              },
            },
            required: true,
            include: [
              {
                model: UserMaster,
                where: {
                  companyMasterId: companyMasterID,
                  status,
                  ...userAccessCondition.where,
                },
                required: true,
                include: [...userAccessCondition.includeModels],
              },
            ],
          },
        ],
        distinct: true,
      }),
    ]);
    const responseData = userExpenseData.map((e) => {
      const jsonData = e.toJSON();

      const userMaster = jsonData.userExpense?.userMaster;
      const joiningDetails = userMaster?.emp_join?.[0];

      /* ---------- Bank Details ---------- */
      if (joiningDetails?.bankAccountStatus === 1) {
        if (joiningDetails.bankAccountNo) {
          userMaster.accountNo = joiningDetails.bankAccountNo;
        }

        if (joiningDetails.bankIFSC) {
          userMaster.ifscCode = joiningDetails.bankIFSC;
        }

        if (joiningDetails.bankMaster?.bankName) {
          userMaster.bankName = joiningDetails.bankMaster.bankName;
        }
      }

      /* ---------- Authorization ---------- */
      jsonData.Authorization =
        jsonData.Auth?.filter(
          (el) => +el.ReferenceID === e.userExpenseTransactionID,
        )
          .map((el) => {
            const status =
              el.authstatus === 1
                ? 'Approved'
                : el.authstatus === 0
                  ? 'Rejected'
                  : 'Pending';

            const displayName = el.authorizedPerson?.displayName || '';
            return `${displayName} - ${status}`;
          })
          .join(', ') || '';

      /* ---------- Authorization Criteria ---------- */
      jsonData['Authorization Criteria'] =
        jsonData.AuthorizationCriteriaMaster?.AuthorizationCriteria || '';

      return jsonData;
    });

    return res.status(200).json({
      data: responseData,
      totalcount: count,
    });
  } catch (err) {
    next(err);
  }
};

exports.expenseReportCount = async (req, res, next) => {
  try {
    const {
      companyMasterID,
      userMasterID,
      fromDate,
      toDate,
      expenseType,
      status,
    } = req.body;

    const companyId = companyMasterID;
    const userMasterId = userMasterID;

    if (!companyId || !fromDate || !toDate || !expenseType) {
      return res.status(statusCodes.BAD_REQUEST).json({
        message: message.errorMessage.INVALID_FILTER_FIELDS,
      });
    }

    const expenseTypeCondition = {};
    if (expenseType === expenseTypes.VISIT) {
      expenseTypeCondition.visitID = {
        [Sequelize.Op.ne]: null,
      };
    }
    if (expenseType === expenseTypes.TOUR) {
      expenseTypeCondition.ToursMasterID = {
        [Sequelize.Op.ne]: null,
      };
    }
    if (expenseType === expenseTypes.PERSONAL) {
      expenseTypeCondition.visitID = null;
      expenseTypeCondition.ToursMasterID = null;
      expenseTypeCondition.projectID = null;
      expenseTypeCondition.serviceNumber = null;
    }
    if (expenseType === expenseTypes.PROJECT) {
      expenseTypeCondition.projectID = {
        [Sequelize.Op.ne]: null,
      };
    }
    if (expenseType === expenseTypes.SERVICE) {
      expenseTypeCondition.serviceNumber = {
        [Sequelize.Op.ne]: null,
      };
    }

    const userAccessCondition = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: !companyMasterID,
    });

    const [result] = await UserExpenseTransaction.findAll({
      raw: true,
      subQuery: false,

      where: {
        status: {
          [Sequelize.Op.ne]: 10,
        },
      },

      attributes: [
        // Pending Amount
        [
          sequelize.literal(`
            COALESCE(
              SUM(
                CASE
                  WHEN "userExpenseTransaction"."authorizationStatus" IN (0,1,2)
                  THEN "userExpenseTransaction"."expenseAmount"
                  ELSE 0
                END
              ),
            0)
          `),
          'Pending',
        ],

        // Pending Count
        [
          sequelize.literal(`
            COUNT(
              CASE
                WHEN "userExpenseTransaction"."authorizationStatus" IN (0,1,2)
                THEN 1
              END
            )
          `),
          'PendingCount',
        ],

        // Approved Amount
        [
          sequelize.literal(`
            COALESCE(
              SUM(
                CASE
                  WHEN "userExpenseTransaction"."authorizationStatus" = 3
                   AND "userExpenseTransaction"."erpJvid" IS NULL
                   AND "userExpenseTransaction"."payment_Id" IS NULL
                  THEN "userExpenseTransaction"."expenseAmount"
                  ELSE 0
                END
              ),
            0)
          `),
          'Approved',
        ],

        // Approved Count
        [
          sequelize.literal(`
            COUNT(
              CASE
                WHEN "userExpenseTransaction"."authorizationStatus" = 3
                 AND "userExpenseTransaction"."erpJvid" IS NULL
                 AND "userExpenseTransaction"."payment_Id" IS NULL
                THEN 1
              END
            )
          `),
          'ApprovedCount',
        ],

        // Paid Amount
        [
          sequelize.literal(`
            COALESCE(
              SUM(
                CASE
                  WHEN "userExpenseTransaction"."authorizationStatus" = 3
                   AND (
                     "userExpenseTransaction"."erpJvid" IS NOT NULL
                     OR "userExpenseTransaction"."payment_Id" IS NOT NULL
                   )
                  THEN "userExpenseTransaction"."expenseAmount"
                  ELSE 0
                END
              ),
            0)
          `),
          'Paid',
        ],

        // Paid Count
        [
          sequelize.literal(`
            COUNT(
              CASE
                WHEN "userExpenseTransaction"."authorizationStatus" = 3
                 AND (
                   "userExpenseTransaction"."erpJvid" IS NOT NULL
                   OR "userExpenseTransaction"."payment_Id" IS NOT NULL
                 )
                THEN 1
              END
            )
          `),
          'PaidCount',
        ],

        // Rejected Amount
        [
          sequelize.literal(`
            COALESCE(
              SUM(
                CASE
                  WHEN "userExpenseTransaction"."authorizationStatus" = 4
                  THEN "userExpenseTransaction"."expenseAmount"
                  ELSE 0
                END
              ),
            0)
          `),
          'Rejected',
        ],

        // Rejected Count
        [
          sequelize.literal(`
            COUNT(
              CASE
                WHEN "userExpenseTransaction"."authorizationStatus" = 4
                THEN 1
              END
            )
          `),
          'RejectedCount',
        ],
      ],

      include: [
        {
          model: UserExpense,
          as: 'userExpense',
          attributes: [],
          required: true,

          where: {
            userMasterID: Array.isArray(userMasterId)
              ? userMasterId
              : [userMasterId],

            expense_date: {
              [Sequelize.Op.between]: [new Date(fromDate), new Date(toDate)],
            },

            ...expenseTypeCondition,
          },

          include: [
            {
              model: UserMaster,
              attributes: [],
              required: true,

              where: {
                companyMasterId: companyMasterID,
                status,
                ...userAccessCondition.where,
              },

              include: [...userAccessCondition.includeModels],
            },
          ],
        },
      ],
    });

    return res.status(200).json({
      status: 200,

      data: {
        Approved: +result?.Approved || 0,
        AcceptedCount: +result?.ApprovedCount || 0,
        Pending: +result?.Pending || 0,
        PendingCount: +result?.PendingCount || 0,
        Rejected: +result?.Rejected || 0,
        RejectedCount: +result?.RejectedCount || 0,
        Paid: +result?.Paid || 0,
        PaidCount: +result?.PaidCount || 0,
      },
    });
  } catch (err) {
    next(err);
  }
};

exports.visitMeetingReport = async (req, res, next) => {
  try {
    const { userMasterID, orderBy, fromDate, toDate, searchMeetingStatus } =
      req.body;

    const condition = {};
    condition.status = 1;
    const currentDate = asiaKolkataDateTime(new Date()).slice(0, 10);

    if (fromDate && toDate) {
      condition.meetingDate = {
        [Sequelize.Op.between]: [fromDate, toDate],
      };
    }

    if (searchMeetingStatus) {
      condition.meetingStatus = searchMeetingStatus;
    }

    if (userMasterID) {
      condition.userMasterID = userMasterID;
    }

    const order = [];

    if (orderBy == 'nameWise') {
      order.push(
        [{ model: UserMaster, as: 'user' }, 'displayName', 'ASC'], // First group by user
        ['meetingDate', 'ASC'], // Then by meeting date
        ['fromTime', 'ASC'], // Then by meeting time
      );
    } else {
      order.push(
        ['meetingDate', 'ASC'], // First group by date
        ['fromTime', 'ASC'], // Then by time
        [{ model: UserMaster, as: 'user' }, 'displayName', 'ASC'], // Optional: stable sorting
      );
    }

    const includes = [
      {
        model: UserMaster,
        as: 'user',
        attributes: ['displayName', 'userMasterID'],
        include: [
          {
            required: false,
            model: EmployeeDepartment,
            as: 'emp_dept',
            attributes: ['departmentID'],
            where: {
              status: 1,
              applicableDate: {
                [Sequelize.Op.lte]: new Date(currentDate),
              },
              [Sequelize.Op.or]: [
                {
                  endDate: {
                    [Sequelize.Op.gte]: new Date(currentDate),
                  },
                },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },
            include: [
              {
                model: Department,
                as: 'department',
                attributes: ['departmentName'],
              },
            ],
          },
          {
            required: false,
            model: EmployeeBranch,
            as: 'emp_branch',
            where: {
              status: 1,
              applicableDate: {
                [Sequelize.Op.lte]: new Date(currentDate),
              },
              [Sequelize.Op.or]: [
                {
                  endDate: {
                    [Sequelize.Op.gte]: new Date(currentDate),
                  },
                },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },
            attributes: ['branchID'],
            include: [
              {
                model: BranchMaster,
                as: 'branchMaster',
                attributes: ['branchName', 'branchAddress'],
              },
            ],
          },
          {
            required: false,
            model: EmployeeDesignation,
            as: 'emp_desig',
            attributes: ['designationID'],
            where: {
              status: 1,
              applicableDate: {
                [Sequelize.Op.lte]: new Date(currentDate),
              },
              [Sequelize.Op.or]: [
                {
                  endDate: {
                    [Sequelize.Op.gte]: new Date(currentDate),
                  },
                },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },
            include: [
              {
                model: Designation,
                as: 'designation',
                attributes: ['designationName'],
              },
            ],
          },
          {
            required: false,
            model: EmployeeDivision,
            as: 'emp_div',

            where: {
              status: 1,
              startDate: { [Sequelize.Op.lte]: currentDate },
              [Sequelize.Op.or]: [
                { endDate: { [Sequelize.Op.gte]: currentDate } },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },
            attributes: ['divisionId', 'startDate'],
            include: [{ model: Division, attributes: ['divisionName'] }],
          },
          {
            required: false,
            model: EmployeeWorkingArea,
            as: 'emp_area',
            where: {
              status: 1,
              startDate: { [Sequelize.Op.lte]: currentDate },
              [Sequelize.Op.or]: [
                { endDate: { [Sequelize.Op.gte]: currentDate } },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },
            attributes: ['workingAreaId', 'startDate'],
            include: [{ model: WorkingArea, attributes: ['workingAreaName'] }],
          },
        ],
      },
      {
        model: MeetingPurpose,
        attributes: ['meetingPurpose'],
      },
      {
        model: Customer,
        attributes: ['customerName'],
      },
      {
        model: MeetingCopeople,
        attributes: ['userMasterID'],
        include: [
          {
            model: UserMaster,
            as: 'coPeople',
            attributes: ['displayName'],
          },
        ],
      },
      {
        model: MeetingProduct,
        attributes: ['productID'],
        include: [
          {
            model: Product,
            as: 'product',
            attributes: ['productName'],
          },
        ],
      },
      {
        model: UserMaster,
        as: 'createBy',
        attributes: ['displayName'],
      },
      {
        model: UserMaster,
        as: 'updateBy',
        attributes: ['displayName'],
      },
    ];

    const visitList = await VisitMeetings.findAll({
      where: condition,
      distinct: true,
      order: order,
      include: includes,
    });

    if (visitList && visitList.length == 0) {
      return res.status(200).json({
        status: 400,
        message: 'No data found to export',
        data: [],
      });
    }
    const finaldata = [];

    let previousEmployee = null;

    visitList.forEach((e) => {
      const currentEmployee = e.user?.displayName || '-';

      // 👉 Insert Employee Header when employee changes
      if (currentEmployee !== previousEmployee) {
        finaldata.push({
          'Employee Name': '',
          Branch: '',
          Department: '',
          Designation: '',
          Division: '',
          'Working Area': '',
          'Customer Name': '',
          'Product Name': '',
          'Meeting Purpose': '',
          'Meeting Date': '',
          'Meeting From Time': '',
          'Meeting To Time': '',
          'Meeting Type': '',
          'Co Persons': '',
          'Meeting Status': '',
          Agenda: '',
          'Created By': '',
          'Created At': '',
          'Updated By': '',
          'Updated At': '',
          Remark: '',
        });

        previousEmployee = currentEmployee;
      }

      finaldata.push({
        'Employee Name': currentEmployee,
        Branch: e.user?.emp_branch?.[0]?.branchMaster?.branchName || '',
        Department: e.user?.emp_dept?.[0]?.department?.departmentName || '',
        Designation: e.user?.emp_desig?.[0]?.designation?.designationName || '',
        Division: e.user?.emp_div?.[0]?.Division?.divisionName || '',
        'Working Area':
          e.user?.emp_area?.[0]?.WorkingArea?.workingAreaName || '',
        'Customer Name': e.customer?.customerName || '',
        'Product Name':
          e.meetingProducts?.map((p) => p?.product?.productName).join(',') ||
          '',
        'Meeting Purpose': e.meetingPurpose?.meetingPurpose || '',
        'Meeting Date': e.meetingDate || '',
        'Meeting From Time': e.fromTime || '',
        'Meeting To Time': e.toTime || '',
        'Meeting Type': e.meetingType || '',
        'Co Persons':
          e.meetingCopeople?.map((c) => c?.coPeople?.displayName).join(',') ||
          '',
        'Meeting Status': e.meetingStatus || '',
        Agenda: stripHtml(e.agenda) || '',
        'Created By': e.createBy?.displayName || '',
        'Created At': moment(e.createdAt).format('DD-MM-YYYY HH:mm'),
        'Updated By': e.updateBy?.displayName || '',
        'Updated At': e.updateBy
          ? moment(e.updatedAt).format('DD-MM-YYYY HH:mm')
          : '',
        Remark: e.remark || '',
      });
    });

    return await generateExcel(finaldata, 'Meeting Purpose', 'xlsx', res);
  } catch (error) {
    next(error);
  }
};

function calculatePerDaySalary(
  salaryPolicy,
  salaryCalculationAct,
  attendancePolicy,
  salaryMaster,
  attendance,
  shiftHrs,
  totalWeekoff = 0,
  totalHoliday = 0,
  salaryMonth,
  weekoff = 0,
  holiday = 0,
  paidLeave = 0,
  iscurrentDate,
  start_Date,
  weekoffCountForHourly = 0,
) {
  const result = { salaryAmount: 0, otHrs: 0, otAmount: 0, perDayAmount: 0 };

  if (!salaryMaster) return result;

  const grossData = salaryMaster?.get(payheadMasterIdsMapping.GROSS);

  const grossAmount = grossData?.EmployeeSalaryAmount || 0;
  const baseOnCalculation = grossData?.baseOnCalculation || null;

  if (
    +grossAmount == 0 ||
    !salaryMonth ||
    (salaryPolicy?.salarycalculationBasedon == 'hourwise' &&
      !shiftHrs &&
      !salaryPolicy?.monthlyFixhours)
  )
    return result;

  const month = start_Date
    ? String(start_Date).slice(5, 7)
    : String(salaryMonth).slice(4, 6);
  const year = start_Date
    ? String(start_Date).slice(0, 4)
    : String(salaryMonth).slice(0, 4);
  let monthDays = daysInMonth(month, year);

  if (salaryPolicy?.MonthDaysType == 'fix') {
    monthDays = salaryPolicy.fixDays;
  }

  let otGross = grossAmount;

  if (
    [
      OTPayTypeEnum.BASIC_SALARY,
      OTPayTypeEnum.CTC_SALARY,
      OTPayTypeEnum.GROSS_SALARY,
    ].includes(attendancePolicy?.payType)
  ) {
    otGross =
      attendancePolicy.payType == OTPayTypeEnum.CTC_SALARY
        ? salaryMaster?.get(payheadMasterIdsMapping.CTC)
            ?.EmployeeSalaryAmount || 0
        : attendancePolicy.payType == OTPayTypeEnum.BASIC_SALARY
          ? salaryMaster?.get(payheadMasterIdsMapping.BASIC)
              ?.EmployeeSalaryAmount || 0
          : grossAmount;
  }

  const otData = attendance?.OverTimeCalculations?.[0] || null;

  const otMinutes = [3, 6].includes(+otData?.AuthorizationRequired)
    ? otData.UpdateOverTimeHourAndMin
    : otData?.OverTimeHourAndMin || 0;

  // Helper function to calculate adjusted month days based on salary calculation act
  const getAdjustedMonthDays = (days, act) => {
    if (act == 'F')
      return (
        days -
        (weekoffCountForHourly > 0 ? weekoffCountForHourly : totalWeekoff)
      );
    if (act == 'W') return days - totalWeekoff - totalHoliday;
    return days;
  };

  // Helper function to calculate per day/min salary based on calculation type
  const getPerUnitSalary = (
    monthlyDivisor,
    dailyDivisor,
    hourlyValue,
    amount,
  ) => {
    if (baseOnCalculation == SalaryStructureTypeEnum.MONTHLY)
      return +amount / +monthlyDivisor;
    if (baseOnCalculation == SalaryStructureTypeEnum.DAILY)
      return +amount / +dailyDivisor;
    return hourlyValue;
  };

  // Calculate paid days
  let paidDays = 0;
  let availDays = 1;

  if (paidLeave) {
    paidDays = paidLeave;
    availDays -= paidLeave;
  }

  if (
    (!salaryCalculationAct || salaryCalculationAct == 'S') &&
    weekoff > 0 &&
    availDays > 0
  ) {
    const days = Math.min(weekoff, availDays);
    paidDays += days;
    availDays -= days;
  }

  if (
    (!salaryCalculationAct || ['S', 'F'].includes(salaryCalculationAct)) &&
    holiday > 0 &&
    availDays > 0
  ) {
    const days = Math.min(holiday, availDays);
    paidDays += days;
    availDays -= days;
  }

  if (attendance && availDays > 0) {
    const days = Math.min(
      iscurrentDate && !attendance.OutDateTime ? 1 : +attendance.fulldayhalfday,
      availDays,
    );
    paidDays += days;
    availDays -= days;
  }

  // Calculate perMinuteSalaryForOT
  let perMinuteSalaryForOT = 0;
  const salaryPolicyType = salaryPolicy?.salarycalculationBasedon;

  if (attendancePolicy?.payType == 'fixedAmount') {
    perMinuteSalaryForOT = attendancePolicy.payAmount / 60;
  }

  if (
    salaryPolicyType != 'hourwise' &&
    attendancePolicy?.payType != 'fixedAmount'
  ) {
    const divideMonthlySalary =
      attendancePolicy?.monthDays ||
      (salaryPolicy?.salarycalculationBasedon == 'daywise'
        ? salaryPolicy.salaryCalculationDays
        : getAdjustedMonthDays(monthDays, salaryCalculationAct));
    const divideDailySalary =
      attendancePolicy?.overtimeHrs || shiftHrs * 60 || 480;
    perMinuteSalaryForOT = getPerUnitSalary(
      divideMonthlySalary * divideDailySalary,
      divideDailySalary,
      +otGross / 60,
      otGross,
    );
  }

  // Calculate salary amount
  let salaryAmount = 0;
  let perDay_amount = 0;

  if (salaryPolicy) {
    if (salaryPolicyType == 'hourwise') {
      // Hourwise calculation
      let monthlyShiftHrs, dailyShiftHrs;

      if (!salaryPolicy.monthlyFixhours) {
        monthDays = getAdjustedMonthDays(monthDays, salaryCalculationAct);
        dailyShiftHrs = salaryPolicy.dailyFixhours
          ? +salaryPolicy.dailyFixhours
          : +shiftHrs;
        monthlyShiftHrs = +dailyShiftHrs * +monthDays;
      } else {
        monthlyShiftHrs = salaryPolicy.monthlyFixhours;
        dailyShiftHrs = +salaryPolicy.monthlyFixhours / +monthDays;
      }

      const perMinSalary = getPerUnitSalary(
        monthlyShiftHrs * 60,
        dailyShiftHrs * 60,
        +grossAmount / 60,
        grossAmount,
      );

      perDay_amount =
        baseOnCalculation == SalaryStructureTypeEnum.DAILY
          ? grossAmount
          : baseOnCalculation == SalaryStructureTypeEnum.HOURLY
            ? roundOffLeaveBalance(grossAmount * dailyShiftHrs)
            : roundOffLeaveBalance(
                (grossAmount * dailyShiftHrs) / monthlyShiftHrs,
              );

      let paidHrs = 0;
      let availDaysHourwise = 1;

      if (salaryPolicy.leaveHours == 'Y' && paidLeave > 0) {
        paidHrs = +paidLeave * +dailyShiftHrs;
        availDaysHourwise -= paidLeave;
      }

      if (
        salaryPolicy.holidayHours == 'Y' &&
        holiday > 0 &&
        availDaysHourwise > 0
      ) {
        const days = Math.min(holiday, availDaysHourwise);
        paidHrs += days * +dailyShiftHrs;
        availDaysHourwise -= days;
      }

      if (
        salaryPolicy.weekoffHours == 'Y' &&
        weekoff > 0 &&
        availDaysHourwise > 0
      ) {
        const days = Math.min(weekoff, availDaysHourwise);
        paidHrs += days * +dailyShiftHrs;
        availDaysHourwise -= days;
      }

      if (attendance) {
        paidHrs =
          iscurrentDate && !attendance.OutDateTime
            ? dailyShiftHrs
            : salaryPolicy.overtimeAdded == overtimeAddedEnum.DAILY ||
                (salaryPolicy.overtimeAdded == overtimeAddedEnum.MONHTLY &&
                  salaryPolicy.monthly_ot_cal_type ==
                    monthlyOTCalcuationType.SHIFT_PLUS_OT)
              ? +attendance.withoutOtMinutes / 60
              : +attendance.roundOffMinutes / 60;
      }

      salaryAmount = Math.round(+perMinSalary * +paidHrs * 60);

      if (+perMinuteSalaryForOT == 0) {
        perMinuteSalaryForOT = +perMinSalary;
      }
    } else if (
      salaryPolicyType == 'daywise' &&
      salaryPolicy.salaryCalculationDays
    ) {
      // Daywise calculation
      const perDaySalary = getPerUnitSalary(
        +salaryPolicy.salaryCalculationDays,
        1,
        +grossAmount * +shiftHrs,
        +grossAmount,
      );

      perDay_amount = perDaySalary;

      salaryAmount = +paidDays * +perDaySalary;
    } else {
      monthDays = getAdjustedMonthDays(monthDays, salaryCalculationAct);
      const perDaySalary = getPerUnitSalary(
        monthDays,
        1,
        +grossAmount * +shiftHrs,
        +grossAmount,
      );

      perDay_amount = perDaySalary;
      salaryAmount = +paidDays * +perDaySalary;
    }
  } else {
    // No salary policy - default calculation
    monthDays = getAdjustedMonthDays(monthDays, salaryCalculationAct);
    const perDaySalary = getPerUnitSalary(
      monthDays,
      1,
      +grossAmount * +shiftHrs,
      +grossAmount,
    );
    perDay_amount = perDaySalary;
    salaryAmount = +paidDays * +perDaySalary;
  }

  const otAmount = Math.round(+otMinutes * +perMinuteSalaryForOT);

  result.salaryAmount = Math.round(+salaryAmount);
  result.otHrs = +otMinutes > 0 ? +otMinutes : 0;
  result.otAmount = +otAmount;
  result.perDayAmount = roundOffLeaveBalance(+perDay_amount);

  return result;
}

exports.perDaySalaryReport = async (req, res, next) => {
  const startMemory = process.memoryUsage();
  const startTime = Date.now();

  try {
    const {
      companyMasterId,
      userMasterID,
      startDate,
      endDate,
      sortField,
      reportFormat,
    } = req.body;

    if (
      !companyMasterId ||
      !Array.isArray(userMasterID) ||
      userMasterID.length === 0 ||
      !startDate ||
      !endDate ||
      !reportFormat
    ) {
      return res.status(statusCodes.OK).json({
        status: statusCodes.BAD_REQUEST,
        message: message.usermessage.ValidParameters,
      });
    }

    if (!Object.values(perDaySalaryReportFormatEnum).includes(reportFormat)) {
      return res.status(statusCodes.OK).json({
        status: statusCodes.BAD_REQUEST,
        message: `Invalid report format '${reportFormat}'. Allowed values are: ${Object.keys(perDaySalaryReportFormatEnum).join(', ')}.`,
      });
    }

    const currentdate = new Date();
    const currentDate = currentdate.toISOString().slice(0, 10);

    const start = new Date(startDate);
    const end = new Date(endDate);

    if (start > currentdate || end > currentdate) {
      return res.status(statusCodes.OK).json({
        status: statusCodes.BAD_REQUEST,
        message: 'Future date is not allowed.',
      });
    }

    const days = getDaysFromDates(start, end);

    if (days > 31) {
      return res.status(statusCodes.OK).json({
        status: statusCodes.BAD_REQUEST,
        message: 'Date range cannot exceed 31 days',
      });
    }

    const companyData = await companyMaster.findOne({
      where: {
        companyMasterID: companyMasterId,
      },
      attributes: ['companyName', 'companyAddress'],
    });

    const chunkSize = 300;

    const allChunkes = chunkArray(userMasterID, chunkSize);

    const allDates = getAllDatesBetween(startDate, endDate);

    const isFormat_2 = reportFormat == perDaySalaryReportFormatEnum.FORMAT_2;

    const userObj = isFormat_2
      ? {
          date: '',
          day: '',
          shiftTiming: '',
          InOut: '',
          shiftHrs: null,
          Status: 'A',
          workingHrs: null,
          'OT Hrs': null,
          perDaySlary: 0,
          Salary: 0,
          'OT Amount': 0,
          'Total Salary': 0,
        }
      : {};

    const dayMap = new Map();

    if (isFormat_2) {
      for (const date of allDates) {
        const key = date;
        const value = moment(date).format('dddd');
        dayMap.set(key, value);
      }
    }

    const { where, includeModels } = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: false,
    });

    const finalData = [];

    // Division summary - calculate while building finalData
    const divisionSummary = {};
    const orderByFields = getOrderByFields(sortField);
    for (const chunk of allChunkes) {
      const allData = await UserMaster.findAll({
        where: {
          ...where,
          userMasterID: {
            [Sequelize.Op.in]: chunk,
          },
          status: 1,
        },
        attributes: ['userMasterID', 'userNumber', 'displayName'],
        order: orderByFields,
        include: [
          ...includeModels,
          {
            required: true,
            model: EmployeeJoiningDetails,
            where: {
              joiningDate: {
                [Sequelize.Op.lte]: endDate,
              },
              [Sequelize.Op.or]: [
                {
                  leavingDate: {
                    [Sequelize.Op.gte]: startDate,
                  },
                },
                {
                  leavingDate: {
                    [Sequelize.Op.is]: null,
                  },
                },
              ],
            },
            attributes: [
              'employeeCode',
              'dob',
              'joiningDate',
              'leavingDate',
              'salaryCalculationAct',
            ],
          },
          {
            model: EmployeeDesignation,
            where: {
              status: 1,
              applicableDate: { [Sequelize.Op.lte]: endDate },
              [Sequelize.Op.or]: [
                { endDate: { [Sequelize.Op.gte]: endDate } },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },
            required: false,
            attributes: ['designationID'],
            include: [
              {
                model: Designation,
                as: 'designation',
                attributes: ['designationName'],
              },
            ],
          },
          {
            model: EmployeeDepartment,
            where: {
              status: 1,
              applicableDate: { [Sequelize.Op.lte]: endDate },
              [Sequelize.Op.or]: [
                { endDate: { [Sequelize.Op.gte]: endDate } },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },
            required: false,
            attributes: ['departmentID'],
            include: [
              {
                model: Department,
                as: 'department',
                attributes: ['departmentName'],
              },
            ],
          },
          {
            model: EmployeeBranch,
            where: {
              status: 1,
              applicableDate: { [Sequelize.Op.lte]: endDate },
              [Sequelize.Op.or]: [
                { endDate: { [Sequelize.Op.gte]: endDate } },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },
            required: false,
            attributes: ['branchID'],
            include: [
              {
                model: BranchMaster,
                as: 'branchMaster',
                attributes: ['branchName'],
              },
            ],
          },
          {
            model: EmployeeDivision,
            where: {
              status: 1,
              startDate: { [Sequelize.Op.lte]: endDate },
              [Sequelize.Op.or]: [
                { endDate: { [Sequelize.Op.gte]: endDate } },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },

            required: false,
            attributes: ['divisionId'],
            include: [
              {
                model: Division,
                attributes: ['divisionName'],
              },
            ],
          },
          {
            model: EmployeeWorkingArea,
            where: {
              status: 1,
              startDate: { [Sequelize.Op.lte]: endDate },
              [Sequelize.Op.or]: [
                { endDate: { [Sequelize.Op.gte]: endDate } },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },

            required: false,
            attributes: ['workingAreaId'],
            include: [
              {
                model: WorkingArea,
                attributes: ['workingAreaName'],
              },
            ],
          },
          // attendance policy
          {
            required: false,
            model: EmployeeAttendancePolicy,
            as: 'empAttPolicy',
            where: {
              status: 1,
              startDate: { [Sequelize.Op.lte]: endDate },
              [Sequelize.Op.or]: [
                { endDate: { [Sequelize.Op.gte]: endDate } },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },
            attributes: ['attendancePolicyID'],
            include: [
              {
                model: AttendancePolicy,
                as: 'attendancePolicy',
              },
            ],
          },
          // salary policy
          {
            required: false,
            model: EmployeeSalaryPolicy,
            as: 'empSalPolicy',
            where: {
              status: 1,
              startDate: { [Sequelize.Op.lte]: endDate },
              [Sequelize.Op.or]: [
                { endDate: { [Sequelize.Op.gte]: endDate } },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },

            attributes: ['salaryPolicyID'],
            include: [
              {
                model: SalaryPolicy,
                as: 'salaryPolicy',
              },
            ],
          },
          // attendance
          {
            required: false,
            model: attendanceTransaction,
            where: {
              AttendanceDate: {
                [Sequelize.Op.between]: [startDate, endDate],
              },
            },
            attributes: [
              'OutDateTime',
              'AttendanceDate',
              'fulldayhalfday',
              'AttendanceTransID',
              'Shifthrs',
              'roundOffMinutes',
              'withoutOtMinutes',
              'ShiftoutTime',
              'ShiftIntime',
              'InDatetime',
              'OutDateTime',
            ],
            include: [
              {
                required: false,
                separate: true,
                model: overTimeCalculation,
                where: {
                  AuthorizationRequired: { [Sequelize.Op.notIn]: [4, 5] },
                },
                attributes: [
                  'AuthorizationRequired',
                  'OverTimeHourAndMin',
                  'UpdateOverTimeHourAndMin',
                ],
              },
            ],
          },
          // leave
          {
            required: false,
            separate: true,
            model: UserLeave,
            where: {
              FromDate: {
                [Sequelize.Op.lte]: endDate,
              },
              ToDate: {
                [Sequelize.Op.gte]: startDate,
              },
              status: 1,
              authorizationStatus: 3,
            },
            attributes: ['UserLeaveApplicationID', 'DayType'],
            include: [
              {
                required: false,
                model: userLeaveTransaction,
                where: {
                  status: 1,
                  date: {
                    [Sequelize.Op.between]: [startDate, endDate],
                  },
                },
                attributes: ['LeaveTranId', 'days', 'date'],
                include: [
                  {
                    model: hrLeaveTypes,
                    attributes: ['LeaveID'],
                    include: [
                      {
                        model: HrLeaveMaster,
                        as: 'LeaveMaster',
                        attributes: ['LeaveName'],
                      },
                    ],
                  },
                ],
              },
            ],
          },
          // shift roaster
          {
            required: false,
            model: ShiftRoster,
            where: {
              shiftRosterDate: {
                [Sequelize.Op.between]: [startDate, endDate],
              },
              status: 1,
            },
            attributes: ['shiftRosterDate', 'shiftID', 'userMasterID'],
            include: [
              {
                model: Shift,
                attributes: ['shiftID'],
                include: [
                  {
                    model: ShiftTIme,
                    attributes: ['shiftID', 'day', 'totalhours'],
                  },
                ],
              },
            ],
          },
          // employee shift
          {
            required: false,
            model: EmployeeShift,
            where: {
              status: 1,
              startDate: { [Sequelize.Op.lte]: endDate },
              [Sequelize.Op.or]: [
                { endDate: { [Sequelize.Op.gte]: startDate } },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },
            attributes: ['shiftsID', 'userMasterID'],
          },
          // weekoff policy
          {
            required: false,
            model: EmployeeWeekOff,
            where: {
              status: 1,
              applicableDate: { [Sequelize.Op.lte]: endDate },
              [Sequelize.Op.or]: [
                { endDate: { [Sequelize.Op.gte]: startDate } },
                { endDate: { [Sequelize.Op.eq]: null } },
              ],
            },
            attributes: ['weekOffPolicyID'],
            include: [
              {
                model: weekOffPolicy,
                as: 'weekoff',
                attributes: ['weekoffType', 'monthlyFix', 'isNoWeekoffPolicy'],
              },
            ],
          },
        ],
      });

      const shiftIds = new Set();

      const userDataMap = new Map();
      for (const data of allData) {
        const joining = data.employeeJoiningDetails[0] || null;
        const attendancePolicy =
          data.empAttPolicy?.[0]?.attendancePolicy || null;
        const salaryPolicy = data.empSalPolicy?.[0]?.salaryPolicy || null;

        // for attendance
        const attendanceData = data.attendanceTransactions || [];
        const attendanceMap = new Map();

        for (let i = 0; i < attendanceData.length; i++) {
          const record = attendanceData[i];
          const dateKey = record.AttendanceDate;
          // last record
          attendanceMap.set(dateKey, record);
        }

        // for leave
        const leaveData = data.userLeaves || [];
        const leaveMap = new Map();

        for (let i = 0; i < leaveData.length; i++) {
          for (const tran of leaveData[i].userLeaveTransactions || []) {
            const record = {
              ...tran.dataValues,
              DayType: leaveData[i].DayType,
            };
            const dateKey = record.date;

            if (!leaveMap.has(dateKey)) {
              leaveMap.set(dateKey, []);
            }

            leaveMap.get(dateKey).push(record);
          }
        }

        // shift Roster
        const shiftRoster = data.shiftRosters || [];

        const shiftRosterMap = new Map();

        for (let i = 0; i < shiftRoster.length; i++) {
          const record = shiftRoster[i];
          const dateKey = record.shiftRosterDate;

          const dayMap = {};

          const shiftTimes = record.shift?.shiftTimes || [];

          for (let j = 0; j < shiftTimes.length; j++) {
            const st = shiftTimes[j];

            // assuming st.day = 'Monday', 'Tuesday', etc.
            dayMap[st.day] = st;
          }

          shiftRosterMap.set(dateKey, dayMap);
        }

        // for shift
        const shiftData = data.employeeShift || [];
        const employeeShiftIds = shiftData.flatMap((e) => e.shiftsID || []);
        for (const id of employeeShiftIds) {
          shiftIds.add(id);
        }

        // for shiftId map
        const shiftIdsMap = new Map();

        for (let i = 0; i < shiftData.length; i++) {
          const policy = shiftData[i];

          let current = new Date(policy.startDate);
          const end = policy.endDate
            ? new Date(policy.endDate)
            : new Date(endDate); // make sure endDate exists

          while (current && current <= end) {
            const dateKey = current.toISOString().split('T')[0];

            // Prevent overwrite (recommended)
            if (!shiftIdsMap.has(dateKey)) {
              shiftIdsMap.set(dateKey, policy.shiftsID || []);
            }

            // move to next day
            current.setDate(current.getDate() + 1);
          }
        }

        // weekoff policy map
        const weekoffPolicyData = data.employeeWeekOffs || [];
        const weekoffPolicyMap = new Map();

        for (let i = 0; i < weekoffPolicyData.length; i++) {
          const policy = weekoffPolicyData[i];

          let current = new Date(policy.startDate);
          const end = policy.endDate
            ? new Date(policy.endDate)
            : new Date(endDate); // make sure endDate exists

          while (current && current <= end) {
            const dateKey = current.toISOString().split('T')[0];

            // Prevent overwrite (recommended)
            if (!weekoffPolicyMap.has(dateKey)) {
              weekoffPolicyMap.set(dateKey, policy.weekoff || null);
            }

            // move to next day
            current.setDate(current.getDate() + 1);
          }
        }

        const result = getSalaryCyclesInRange(
          Boolean(salaryPolicy),
          salaryPolicy?.salaryCycleDate,
          salaryPolicy?.salaryCycleConsider,
          startDate,
          endDate,
        );

        const object = {
          joining,
          displayName: data.displayName,
          userNumber: data.userNumber,
          branch: data.employeeBranches?.[0]?.branchMaster?.branchName || '',
          department:
            data.employeeDepartments?.[0]?.department?.departmentName || '',
          designation:
            data.employeeDesignations?.[0]?.designation?.designationName || '',
          division: data.employeeDivisions?.[0]?.division?.divisionName || '',
          workingArea:
            data.employeeWorkingAreas?.[0]?.workingArea?.workingAreaName || '',
          attendancePolicy,
          salaryPolicy,
          attendanceData: attendanceMap,
          leaveData: leaveMap,
          salaryCycleMonth: result,
          shiftRoster: shiftRosterMap,
          weekoffPolicy: weekoffPolicyMap,
          priority:
            attendancePolicy?.WHPHPriority == 'PH' ? 'holiday' : 'weekoff',
          shiftIdsMapDateWise: shiftIdsMap,
        };

        userDataMap.set(data.userMasterID, object);
      }

      const allShifts = await Shift.findAll({
        where: {
          shiftID: {
            [Sequelize.Op.in]: [...shiftIds],
          },
        },
        include: [{ model: ShiftTIme }],
        attributes: ['shiftID'],
      });

      const shiftMasterMap = new Map();

      for (let i = 0; i < allShifts.length; i++) {
        const item = allShifts[i];

        const dayMap = {};

        const shiftTimes = item.shiftTimes || [];

        for (let j = 0; j < shiftTimes.length; j++) {
          const st = shiftTimes[j];

          // assuming st.day = 'Monday', 'Tuesday', etc.
          dayMap[st.day] = st;
        }

        shiftMasterMap.set(+item.shiftID, dayMap);
      }

      // Build employee-month pairs for raw query - FLATTENED
      const employeeMonthPairs = [];
      userDataMap.forEach((value, key) => {
        if (value.salaryCycleMonth?.length) {
          // Flatten: create one pair for each month
          value.salaryCycleMonth.forEach((monthObj) => {
            employeeMonthPairs.push({
              userMasterID: +key,
              salaryMonth: monthObj.yearmonth,
            });
          });
        }
      });

      // ------------------- get salary master map ----------------------
      const salaryMasterMap = await getSalaryMasterMap({
        employeeMonthPairs,
        payheadMasterIds: [
          payheadMasterIdsMapping.GROSS,
          payheadMasterIdsMapping.BASIC,
          payheadMasterIdsMapping.CTC,
        ],
      });

      // Step 1: Group employees by date range (start_Date_end_Date)
      const dateRangeGroups = new Map();
      userDataMap.forEach((value, uID) => {
        const start_Date = value.salaryCycleMonth?.[0]?.start_Date || null;
        const end_Date =
          value.salaryCycleMonth?.[value.salaryCycleMonth?.length - 1]
            ?.end_Date || null;

        if (start_Date && end_Date) {
          const key = `${start_Date}_${end_Date}`;
          if (!dateRangeGroups.has(key)) {
            dateRangeGroups.set(key, {
              startDate: start_Date,
              endDate: end_Date,
              userIds: [],
            });
          }
          dateRangeGroups.get(key).userIds.push(uID);
        }
      });

      // Step 2: Query each date range group
      const allWeekoffHolidayData = [];
      for (const [, group] of dateRangeGroups) {
        const data = await weekoffHolidayTran.findAll({
          raw: true,
          where: {
            userMasterID: { [Sequelize.Op.in]: group.userIds },
            date: { [Sequelize.Op.between]: [group.startDate, group.endDate] },
            [Sequelize.Op.or]: [
              { optionalHoliday: false },
              { optionalHoliday: { [Sequelize.Op.is]: null } },
            ],
          },
          attributes: [
            'userMasterID',
            'date',
            'value',
            'WHDayType',
            'tableName',
            'yearMonth',
          ],
        });
        allWeekoffHolidayData.push(...data);
      }

      // Step 3: Create Map (userMasterID → tableName → date → data)
      const weekoffHolidayMap = new Map();

      allWeekoffHolidayData.forEach((item) => {
        if (!weekoffHolidayMap.has(+item.userMasterID)) {
          weekoffHolidayMap.set(+item.userMasterID, {
            holiday: {},
            weekoff: {},
          });
        }
        const userMap = weekoffHolidayMap.get(+item.userMasterID);

        // Add to appropriate tableName (holiday or weekoff)
        if (item.tableName === 'holiday') {
          userMap.holiday[item.date] = item;
        } else if (item.tableName === 'weekoff') {
          userMap.weekoff[item.date] = item;
        }
      });

      // Helper function to get weekoff/holiday with priority for single date
      function getWeekoffHolidayWithPriority(
        uID,
        dateStr,
        priority = 'holiday',
      ) {
        const userMap = weekoffHolidayMap.get(+uID);
        if (!userMap) return null;

        if (priority === 'holiday') {
          return userMap.holiday[dateStr] || userMap.weekoff[dateStr] || null;
        } else {
          return userMap.weekoff[dateStr] || userMap.holiday[dateStr] || null;
        }
      }

      // Helper function to get all weekoff/holiday for employee date range with priority
      // Returns array of data for all dates, applying priority when same date has both
      function getAllWeekoffHolidayWithPriority(uID, priority = 'weekoff') {
        const userMap = weekoffHolidayMap.get(+uID);
        if (!userMap) return [];

        const result = [];
        const allDates = new Set([
          ...Object.keys(userMap.holiday),
          ...Object.keys(userMap.weekoff),
        ]);

        allDates.forEach((dateStr) => {
          let data;
          if (priority === 'holiday') {
            data = userMap.holiday[dateStr] || userMap.weekoff[dateStr];
          } else {
            data = userMap.weekoff[dateStr] || userMap.holiday[dateStr];
          }
          if (data) result.push(data);
        });

        // Sort by date
        result.sort((a, b) => new Date(a.date) - new Date(b.date));
        return result;
      }

      // -------------------------------------------------------

      for (const [key, value] of userDataMap) {
        const userMasterID = key;
        const joining = value.joining || null;
        const joiningDate = joining?.joiningDate || null;
        const leavingDate = joining?.leavingDate || null;
        const salaryPolicy = value.salaryPolicy || null;
        let typeCondition = value.priority;
        const attendancePolicy = value.attendancePolicy || null;
        const isAddlPaidDay = attendancePolicy?.isAddlPaidDay || false;

        const weekoff = weekoffHolidayMap?.get(+userMasterID)?.weekoff || {};

        const weekoffCountForHourly = Object.keys(weekoff).length;

        if (salaryPolicy?.salarycalculationBasedon != 'hourwise') {
          if (
            typeCondition == offDayCategoryEnum.HOLIDAY &&
            isAddlPaidDay &&
            joining?.salaryCalculationAct == 'F'
          ) {
            typeCondition = offDayCategoryEnum.WEEKOFF;
          }
        }

        // Get all weekoff/holiday for employee's date range with priority
        const allWeekoffHolidayForEmployee = getAllWeekoffHolidayWithPriority(
          +userMasterID,
          typeCondition,
        );

        const attendanceMap = value.attendanceData || null;
        const leaveMap = value.leaveData;
        // const priority = attendancePolicy?.WHPHPriority  == 'PH' ? 'holiday' : 'weekoff';
        const salaryCycleMonths = value.salaryCycleMonth || [];
        const salaryMaster = salaryMasterMap.get(+userMasterID);
        const shiftRosterMap = value.shiftRoster;
        const shiftIdMapDateWise = value.shiftIdsMapDateWise;
        const weekoffPolicy = value.weekoffPolicy || null;

        // Build gross salary string for all months (avoid duplicates by salaryMasterID)
        let grossSalaryDisplay = '0';

        if (salaryMaster && salaryCycleMonths.length > 0) {
          const seenSalaryMasterIDs = new Set();
          const grossSalaries = [];

          for (const monthObj of salaryCycleMonths) {
            const monthData = salaryMaster.get(+monthObj.yearmonth);
            const payheadData = monthData?.get(payheadMasterIdsMapping.GROSS);

            if (
              payheadData &&
              !seenSalaryMasterIDs.has(payheadData.salaryMasterID)
            ) {
              const amount = payheadData.EmployeeSalaryAmount || 0;
              const baseCalc = payheadData.baseOnCalculation || '';

              grossSalaries.push(amount > 0 ? `${amount}(${baseCalc})` : '0');
              seenSalaryMasterIDs.add(payheadData.salaryMasterID);
            }
          }

          if (grossSalaries.length > 0) {
            grossSalaryDisplay = grossSalaries.join(', ');
          }
        }

        const userWiseObject = {
          'Employee Code': joining?.employeeCode || '',
          'Employee Name': value.displayName,
          Number: value.userNumber,
          DOB: joining?.dob ? moment(joining?.dob).format('DD-MM-YYYY') : '',
          'Joining Date': joining?.joiningDate
            ? moment(joining?.joiningDate).format('DD-MM-YYYY')
            : '',
          Branch: value.branch,
          Department: value.department,
          Designation: value.designation,
          Division: value.division,
          WorkingArea: value.workingArea,
          'Gross Salary': grossSalaryDisplay,
          datesArray: [],
          userWiseTotalSalary: [],
        };

        const userWiseSalary = isFormat_2
          ? { ...userObj }
          : {
              date: 'Total',
              Salary: 0,
              'OT Amount': 0,
              'Total Salary': 0,
            };

        for (let dateIndex = 0; dateIndex < allDates.length; dateIndex++) {
          const date = allDates[dateIndex];

          const dateWiseObject = isFormat_2
            ? { ...userObj }
            : {
                date,
                Status: 'A',
                Salary: 0,
                'OT Hrs': '0',
                'OT Amount': 0,
                'Total Salary': 0,
              };

          if (
            new Date(joiningDate) > new Date(date) ||
            (leavingDate && new Date(leavingDate) < new Date(date))
          ) {
            userWiseObject.datesArray.push(dateWiseObject);
            continue;
          }

          // find weekoff
          const weekoffHolidayData = getWeekoffHolidayWithPriority(
            +userMasterID,
            date,
            typeCondition,
          );

          // leave
          const leaveData = leaveMap?.get(date) || [];
          const leaveSum = leaveData.reduce(
            (acc, obj) => acc + +(obj.days || 0),
            0,
          );

          // attendance
          const attendanceData = attendanceMap.get(date);
          // current date or not
          const iscurrentDate = currentDate == date;

          const day = new Date(date).toLocaleString('en-us', {
            weekday: 'long',
          });

          // shift roster
          const shiftRoster = shiftRosterMap?.get(date)?.[day];

          const title = [];

          let weekoffCount = 0;
          let holidayCount = 0;
          let paidLeaveCount = 0;

          if (leaveSum >= 1) {
            for (const tran of leaveData) {
              const leaveName = tran.hrLeaveType?.LeaveMaster?.LeaveName || '';
              const leaveId = tran.hrLeaveType?.LeaveID;

              if (tran.days == 1) title.push(leaveName);
              else if (tran.days == 0.5) {
                if (tran.DayType != 'Full Day')
                  title.push(
                    `${leaveName} (${tran.DayType == 'Second Half' ? 'SH' : 'FH'})`,
                  );
                else title.push(leaveName);
              }

              // if not absent or lwp leave
              if (leaveId && ![5, 18].includes(+leaveId))
                paidLeaveCount += tran.days;
            }
          } else if (leaveSum == 0.5) {
            for (const tran of leaveData) {
              const leaveName = tran.hrLeaveType?.LeaveMaster?.LeaveName || '';
              const leaveId = tran.hrLeaveType?.LeaveID;

              if (tran.days == 0.5) {
                if (tran.DayType != 'Full Day')
                  title.push(
                    `${leaveName} (${tran.DayType == 'Second Half' ? 'SH' : 'FH'})`,
                  );
                else title.push(leaveName);
              }

              if (leaveId && ![5, 18].includes(+leaveId))
                paidLeaveCount += tran.days;
            }

            if (weekoffHolidayData?.tableName == 'weekoff') {
              if (weekoffHolidayData.WHDayType == 'SH') {
                title.push('WH(SH)');

                if (
                  !leaveData?.length ||
                  leaveData?.[0]?.DayType != 'Second Half'
                ) {
                  weekoffCount = weekoffHolidayData.value;
                }
              }
            }

            if (attendanceData) {
              const status =
                iscurrentDate && !attendanceData.OutDateTime
                  ? 'P'
                  : attendanceData.fulldayhalfday == 1
                    ? 'P'
                    : attendanceData.fulldayhalfday == 0.5
                      ? 'HFD'
                      : '';
              title.push(status);
            }
          } else {
            if (attendanceData) {
              if (!attendanceData.OutDateTime) {
                const status = iscurrentDate ? 'P' : 'MP';
                title.push(status);
              } else {
                let status = 'A';

                // base status
                if (attendanceData.fulldayhalfday == 1) {
                  status = 'P';
                } else if (attendanceData.fulldayhalfday == 0.5) {
                  status = 'HFD';
                }

                // override if absent + weekoff/holiday
                if (status == 'A' && weekoffHolidayData) {
                  status = weekoffHolidayData.WHDayType === 'SH' ? 'A(FH)' : '';
                }

                title.push(status);
              }
            }

            if (weekoffHolidayData) {
              if (weekoffHolidayData.tableName == 'weekoff') {
                if (weekoffHolidayData.WHDayType == 'SH') {
                  title.push('WH(SH)');
                } else {
                  title.push('WH');
                }
                weekoffCount = +weekoffHolidayData.value;
              } else {
                title.push('HD');
                holidayCount = +weekoffHolidayData.value;
              }
            }
          }

          if (title.length > 0) {
            dateWiseObject.Status = title.filter(Boolean).join(',');
          }

          // date wise shift
          const shiftId = shiftIdMapDateWise?.get(date)?.[0];

          const shiftHrs =
            attendanceData?.Shifthrs ||
            shiftRoster?.totalhours ||
            shiftMasterMap?.get(shiftId)?.[day]?.totalhours ||
            (salaryPolicy?.salarycalculationBasedon == 'hourwise'
              ? salaryPolicy.dailyFixhours
              : 0);

          const currentCycle = salaryCycleMonths.find(
            (e) => e.start_Date <= date && e.end_Date >= date,
          );
          const start_Date = currentCycle?.start_Date || null;
          const end_Date = currentCycle?.end_Date || null;
          const salaryMonth = currentCycle?.yearmonth || null;
          const weekoffHoliday = allWeekoffHolidayForEmployee.filter(
            (e) =>
              new Date(e.date) >= new Date(start_Date) &&
              new Date(e.date) <= new Date(end_Date),
          );

          let totalWeekoff = 0;
          if (
            weekoffPolicy?.weekoffType == weekoffTypeEnum.MONTHLYFIX &&
            !weekoffPolicy.isNoWeekoffPolicy
          ) {
            totalWeekoff = +weekoffPolicy.monthlyFix;
          } else {
            totalWeekoff = weekoffHoliday
              .filter((e) => e.tableName == 'weekoff')
              ?.reduce((acc, obj) => acc + +obj.value, 0);
          }

          const totalHoliday = weekoffHoliday
            .filter((e) => e.tableName == 'holiday')
            ?.reduce((acc, obj) => acc + +obj.value, 0);

          const current_salaryMaster = salaryMaster?.get(+salaryMonth);

          const { salaryAmount, otHrs, otAmount, perDayAmount } =
            calculatePerDaySalary(
              salaryPolicy,
              joining?.salaryCalculationAct,
              attendancePolicy,
              current_salaryMaster,
              attendanceData,
              shiftHrs,
              totalWeekoff,
              totalHoliday,
              salaryMonth,
              weekoffCount,
              holidayCount,
              paidLeaveCount,
              iscurrentDate,
              start_Date,
              weekoffCountForHourly,
            );

          if (isFormat_2) {
            const shiftInTime = attendanceData?.ShiftIntime || '';
            const shiftOutTime = attendanceData?.ShiftoutTime || '';
            dateWiseObject.shiftTiming =
              shiftInTime && shiftOutTime
                ? `${shiftInTime} - ${shiftOutTime}`
                : '';
            const inTime = attendanceData?.InDatetime
              ? moment(attendanceData.InDatetime).format('DD-MM-YYYY hh:mm A')
              : '';
            const outTime = attendanceData?.OutDateTime
              ? moment(attendanceData.OutDateTime).format('DD-MM-YYYY hh:mm A')
              : '';
            dateWiseObject.InOut = `${inTime} - ${outTime}`;
            dateWiseObject.shiftHrs = attendanceData?.Shifthrs || '';
            dateWiseObject.workingHrs = minutesToHoursMinutes(
              Math.round(+attendanceData?.roundOffMinutes) || 0,
            );
            dateWiseObject.perDaySlary = perDayAmount;
            dateWiseObject.date = date;
            dateWiseObject.day = day;
            userWiseSalary.workingHrs += +attendanceData?.roundOffMinutes || 0;
            userWiseSalary['OT Hrs'] += +otHrs;
          }

          dateWiseObject.Salary = salaryAmount;
          dateWiseObject['OT Hrs'] = minutesToHoursMinutes(+otHrs);
          dateWiseObject['OT Amount'] = otAmount;
          dateWiseObject['Total Salary'] = +salaryAmount + +otAmount;

          userWiseObject.datesArray.push(dateWiseObject);

          userWiseSalary.Salary += salaryAmount;
          userWiseSalary['OT Amount'] += otAmount;
          userWiseSalary['Total Salary'] += +salaryAmount + +otAmount;
        }

        if (days > 1) {
          userWiseSalary.workingHrs = minutesToHoursMinutes(
            Math.round(+userWiseSalary.workingHrs),
          );
          userWiseSalary['OT Hrs'] = minutesToHoursMinutes(
            Math.round(+userWiseSalary['OT Hrs']),
          );
          userWiseObject.userWiseTotalSalary.push(userWiseSalary);
        }

        if (!isFormat_2) {
          // Update division summary
          const div = value.division || 'No Division';
          if (!divisionSummary[div]) {
            divisionSummary[div] = {
              count: 0,
              salary: 0,
              otAmount: 0,
              totalSalary: 0,
            };
          }
          divisionSummary[div].count += 1;
          divisionSummary[div].salary += +userWiseSalary.Salary || 0;
          divisionSummary[div].otAmount += +userWiseSalary['OT Amount'] || 0;
          divisionSummary[div].totalSalary +=
            userWiseSalary['Total Salary'] || 0;
        }

        finalData.push(userWiseObject);
      }
    }

    // Format date range
    const formattedStartDate = moment(startDate).format('DD-MM-YYYY');
    const formattedEndDate = moment(endDate).format('DD-MM-YYYY');

    // Set response headers FIRST (before any data)
    res.setHeader(
      'Content-Type',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    );
    res.setHeader(
      'Content-Disposition',
      `attachment; filename=PerDaySalaryReport_${formattedStartDate}_to_${formattedEndDate}.xlsx`,
    );

    // for format-2
    if (isFormat_2) {
      await generatePerDaySalaryFormat2(finalData, res);
    } else {
      // format-1
      await generatePerDaySalaryFormat1(
        finalData,
        res,
        companyData,
        divisionSummary,
        allDates,
        formattedStartDate,
        formattedEndDate,
      );
    }

    // ✅ Track memory at the end
    const endMemory = process.memoryUsage();
    const endTime = Date.now();

    // ✅ Calculate memory usage
    const memoryUsed = {
      heapUsed:
        ((endMemory.heapUsed - startMemory.heapUsed) / 1024 / 1024).toFixed(2) +
        ' MB',
      heapTotal:
        ((endMemory.heapTotal - startMemory.heapTotal) / 1024 / 1024).toFixed(
          2,
        ) + ' MB',
      rss: ((endMemory.rss - startMemory.rss) / 1024 / 1024).toFixed(2) + ' MB',
      external:
        ((endMemory.external - startMemory.external) / 1024 / 1024).toFixed(2) +
        ' MB',
      executionTime: ((endTime - startTime) / 1000).toFixed(2) + ' seconds',
    };

    // ✅ Log memory usage
    console.log('=== Per Day Salary Report Memory Usage (STREAMING) ===');
    console.log('Heap Used:', memoryUsed.heapUsed);
    console.log('Heap Total:', memoryUsed.heapTotal);
    console.log('RSS (Resident Set Size):', memoryUsed.rss);
    console.log('External:', memoryUsed.external);
    console.log('Execution Time:', memoryUsed.executionTime);
    console.log('Date Range:', `${startDate} to ${endDate}`);
    console.log('Total Employees:', userMasterID.length);
    console.log('Total Dates:', allDates.length);

    // ✅ No need to send buffer - already streamed!
    // Response is already sent via workbook.commit()
  } catch (error) {
    next(error);
  }
};

exports.form_C_bonus = async (req, res, next) => {
  try {
    const {
      companyMasterID,
      branchId,
      departmentId,
      designationId,
      divisionId,
      workingAreaId,
      status,
      userMasterID,
      reportType,
      reportTypeValue,
    } = req.body;

    if (
      !companyMasterID ||
      !reportType ||
      !reportTypeValue ||
      !Object.values(form_C_reportTypeEnum).includes(reportType)
    ) {
      return res.status(statusCodes.OK).json({
        status: statusCodes.BAD_REQUEST,
        message: message.usermessage.ValidParameters,
      });
    }

    let startMonth, endMonth;

    switch (reportType) {
      case form_C_reportTypeEnum.CALENDER_YEAR:
        const startYear = Number(reportTypeValue.split('-')[0]);
        startMonth = `${startYear}01`;
        endMonth = `${startYear}12`;
        break;

      case form_C_reportTypeEnum.FINANCIAL_YEAR: {
        const startYear = Number(reportTypeValue.split('-')[0]);
        startMonth = `${startYear}04`;
        endMonth = `${startYear + 1}03`;
        break;
      }

      default:
        startMonth = reportTypeValue;
        endMonth = reportTypeValue;
    }

    let currentDate = moment().format('YYYY-MM-DD');

    let currentMonth = currentDate.slice(0, 4) + '' + currentDate.slice(5, 7);

    const startYear = +String(startMonth).slice(0, 4);

    if (startYear < 2022) {
      return res.status(statusCodes.OK).json({
        status: statusCodes.BAD_REQUEST,
        message:
          'Report generation is only allowed for data from 2022 onwards.',
      });
    }

    if (endMonth && endMonth >= currentMonth) {
      return res.status(statusCodes.OK).json({
        status: statusCodes.BAD_REQUEST,
        message: 'Report cannot be generated for the current or future months.',
      });
    }

    let endDate = currentDate;

    if (endMonth) {
      const year = String(endMonth).slice(0, 4);
      const month = String(endMonth).slice(4, 6);
      endDate = year + '-' + month + '-' + daysInMonth(month, year);
    }

    const includeModels = [
      {
        required: true,
        model: EmployeeJoiningDetails,
        attributes: ['dob'],
      },
      {
        model: EmployeeDesignation,
        where: {
          status: 1,
          ...(checkValidArray(designationId) && {
            designationID: {
              [Sequelize.Op.in]: designationId,
            },
          }),
          applicableDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: checkValidArray(designationId),
        attributes: ['designationID'],
        include: [
          {
            model: Designation,
            as: 'designation',
            attributes: ['designationName'],
          },
        ],
      },
      {
        model: EmployeeDepartment,
        where: {
          status: 1,
          ...(checkValidArray(departmentId) && {
            departmentID: {
              [Sequelize.Op.in]: departmentId,
            },
          }),
          applicableDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: checkValidArray(departmentId),
        attributes: ['departmentID'],
      },
      {
        model: EmployeeBranch,
        where: {
          status: 1,
          ...(checkValidArray(branchId) && {
            branchID: {
              [Sequelize.Op.in]: branchId,
            },
          }),
          applicableDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: checkValidArray(branchId),
        attributes: ['branchID'],
      },
      {
        model: EmployeeDivision,
        where: {
          status: 1,
          ...(divisionId && { divisionId }),
          startDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        required: Boolean(divisionId),
        attributes: ['divisionId'],
      },
      {
        model: EmployeeWorkingArea,
        where: {
          status: 1,
          ...(workingAreaId && { workingAreaId }),
          startDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        required: Boolean(workingAreaId),
        attributes: ['workingAreaId'],
      },
      // bonus data
      {
        required: true,
        model: EmployeeBonus,
        where: {
          bonusYYYYMM: {
            [Sequelize.Op.between]: [+startMonth, +endMonth],
          },
          status: 1,
        },
        attributes: ['amount', 'bonusYYYYMM', 'payYYYYMM'],
      },
    ];

    const condition = { companyMasterId: companyMasterID };

    if (checkValidArray(userMasterID))
      condition.userMasterID = {
        [Sequelize.Op.in]: userMasterID,
      };

    if (status) condition.status = status;
    else condition.status = 1;

    const userAccessCondition = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: !companyMasterID,
    });
    const allUserData = await UserMaster.findAll({
      where: { ...condition, ...userAccessCondition.where },
      include: [...includeModels, ...userAccessCondition.includeModels],
      attributes: ['userMasterID', 'displayName', 'middleName'],
      order: [['displayName', 'ASC']],
    });

    const userIds = allUserData.map((e) => e.userMasterID);

    const [allSalaryData, companyData] = await Promise.all([
      HrSalaryTransaction.findAll({
        where: {
          userMasterID: {
            [Sequelize.Op.in]: userIds,
          },
          salaryYYYYMM: {
            [Sequelize.Op.between]: [+startMonth, +endMonth],
          },
        },
        attributes: [
          'userMasterID',
          'salaryYYYYMM',
          [
            Sequelize.fn('MAX', Sequelize.col('SalaryCalcOnDays')),
            'SalaryCalcOnDays',
          ], // OR SUM / MIN
        ],
        group: ['userMasterID', 'salaryYYYYMM'],
        raw: true,
      }),
      companyMaster.findOne({
        where: { companyMasterID },
        attributes: ['companyName'],
      }),
    ]);

    const userWiseTotal = allSalaryData.reduce((acc, row) => {
      const userId = +row.userMasterID;
      acc[userId] = (acc[userId] || 0) + (+row.SalaryCalcOnDays || 0);
      return acc;
    }, {});

    const employeeData = [];
    let totalNetAmountPayable = 0;
    let totalActualPaid = 0;

    for (const [index, user] of allUserData.entries()) {
      const userMasterID = +user.userMasterID;
      const designation =
        user.employeeDesignations?.[0]?.designation?.designationName || '';
      const dob = user.employeeJoiningDetails?.[0]?.dob || null;
      const toDate =
        String(startMonth).slice(0, 4) +
        '-' +
        String(startMonth).slice(4, 6) +
        '-' +
        '01';
      const age = dob ? calculateAge(dob, toDate) : 0;
      const paidDays = userWiseTotal[userMasterID];
      const bonusData = user.employeeBonus || [];

      const result = bonusData.reduce(
        (acc, b) => {
          const amount = +b.amount || 0;

          // total payable
          acc.bonusPayable += amount;

          if (b.payYYYYMM) {
            // total paid
            acc.paidBonus += amount;

            // latest paid month
            if (!acc.latestPaidMonth || b.payYYYYMM > acc.latestPaidMonth) {
              acc.latestPaidMonth = b.payYYYYMM;
            }
          }

          return acc;
        },
        {
          bonusPayable: 0,
          paidBonus: 0,
          latestPaidMonth: null,
        },
      );

      totalNetAmountPayable += +result.bonusPayable;
      totalActualPaid += +result.paidBonus;

      const obj = {
        srNo: index + 1,
        employeeName: user.displayName,
        fatherName: user.middleName,
        age_15_years: age > 15 ? 'YES' : 'NO',
        designation,
        paidDays,
        totalSalary: '',
        bonusPayable: result.bonusPayable,
        netAmountPayable: result.bonusPayable,
        paidBonus: result.paidBonus,
        paidMonth: result.latestPaidMonth
          ? month_dict[String(result.latestPaidMonth).slice(4, 6)] +
            '-' +
            String(result.latestPaidMonth).slice(0, 4)
          : '',
      };

      employeeData.push(obj);
    }

    if (employeeData.length == 0) {
      return res.status(statusCodes.OK).json({
        status: statusCodes.NOT_FOUND,
        message: 'Bonus data is not available.',
      });
    }

    // push total row
    employeeData.push({
      srNo: '',
      employeeName: 'Grand Total',
      fatherName: '',
      age_15_years: '',
      designation: '',
      paidDays: '',
      totalSalary: '',
      bonusPayable: '',
      netAmountPayable: totalNetAmountPayable,
      paidBonus: totalActualPaid,
      paidMonth: '',
    });

    const pdfData = {
      employeeData,
      isMonthly: reportType == form_C_reportTypeEnum.MONTHLY,
      companyName: companyData?.companyName,
      reportHeading:
        reportType == form_C_reportTypeEnum.MONTHLY
          ? 'BONUS PAID TO EMPLOYEES FOR THE MONTH ENDING ON'
          : 'BONUS PAID TO EMPLOYEES FOR THE ACCOUNTING YEAR ENDING ON',
      reportYear:
        reportType == form_C_reportTypeEnum.MONTHLY
          ? month_dict[String(endMonth).slice(4, 6)] +
            '-' +
            String(endMonth).slice(0, 4)
          : reportTypeValue,
    };

    const filePath = getHTMLTemplate('form-c-bonus', 'html');
    const file = await readHTMLFile(filePath);
    const template = Handlebars.compile(file);
    const html = template(pdfData);

    const browser = await puppeteer.launch({
      headless: 'new',
      args: ['--no-sandbox'],
    });
    const page = await browser.newPage();

    // Set the HTML content of the page
    await page.setContent(html);

    // Generate PDF
    const pdfBuffer = await page.pdf({
      format: 'A4', // Page format (A4 in this case)
      landscape: true,
      printBackground: true, // print background
      margin: { top: '20px', bottom: '20px' },
    });
    await browser.close();

    let base64path = Buffer.from(pdfBuffer).toString('base64');

    return res.status(200).json({
      status: 200,
      data: base64path,
    });
  } catch (error) {
    next(error);
  }
};

exports.contractor_wise_salary_summary = async (req, res, next) => {
  try {
    const { companyMasterID, YYYYMM, contractorId, Export } = req.body;

    if (!companyMasterID || !YYYYMM) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: message.usermessage.passValidValidParameter(
          'companyMasterID and YYYYMM',
        ),
      });
    }

    let contactorCondition = { companyMasterID, status: 1 };
    if (Array.isArray(contractorId) && contractorId.length)
      contactorCondition.contractorId = {
        [Sequelize.Op.in]: contractorId,
      };

    const contractorData = await Contractor.findAll({
      where: contactorCondition,
      include: [{ model: companyMaster, attributes: ['companyName'] }],
      attributes: ['contractorId', 'contractorName', 'companyMasterID'],
      order: [['contractorName', 'ASC']],
    });

    if (!contractorData.length)
      return res.status(statusCodes.OK).json({
        status: statusCodes.NOT_FOUND,
        message: message.usermessage.notFoundMessage('Contarctor Data'),
      });

    const contractorIds = contractorData.map((e) => e.contractorId);

    // Get company name from first contractor
    const companyName = contractorData[0]?.companyMaster?.companyName || '';

    const { where, includeModels } = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: false,
    });

    const allUsers = await UserMaster.findAll({
      where: {
        ...where,
        companyMasterId: companyMasterID,
      },
      include: [
        ...includeModels,
        {
          model: EmployeeJoiningDetails,
          where: {
            contractorId: {
              [Sequelize.Op.in]: contractorIds,
            },
          },
          attributes: ['contractorId'],
        },
      ],
      attributes: ['userMasterID'],
    });

    const allUserIds = allUsers.map((e) => e.userMasterID);

    const result = await getSalary_SalaryMaster_DataMap(
      allUserIds,
      YYYYMM,
      true,
    );

    const salaryTransactionMap = result.salaryTransactionMap;

    // Helper function to format amount - show max 2 decimals only if decimal exists
    const formatAmount = (amount) => {
      const num = parseFloat(amount) || 0;
      return num % 1 === 0 ? num.toString() : num.toFixed(2);
    };

    // Track which payheads actually exist in the data
    const usedPayheads = new Set();
    const contractorWiseData = new Map();

    // Initialize contractor data structure
    for (const contractor of contractorData) {
      contractorWiseData.set(contractor.contractorId, {
        contractorName: contractor.contractorName,
        employeeCount: 0,
        payableDays: 0,
        otMinutes: 0, // Store as minutes, convert to hours:minutes later
        earnings: {},
        deductions: {},
        extraEarnings: {},
        gross: 0,
        totalDeduction: 0,
        netSalary: 0,
      });
    }

    // Process users in single pass
    for (const user of allUsers) {
      const contractorId = +user.employeeJoiningDetails?.[0]?.contractorId;
      if (!contractorId) continue;

      const contractorInfo = contractorWiseData.get(contractorId);
      if (!contractorInfo) continue;

      const userSalaryData = salaryTransactionMap.get(user.userMasterID);
      if (!userSalaryData) continue;

      // count increase if only salary is calculated
      contractorInfo.employeeCount++;

      // Add payable days
      const payableDays = parseFloat(userSalaryData.salaryCalculationDays) || 0;
      contractorInfo.payableDays += payableDays;

      // Add OT minutes (sum all minutes, convert to hours:minutes later)
      const otMinutes = parseFloat(userSalaryData.otMinutes) || 0;
      contractorInfo.otMinutes += otMinutes;

      // Use existing gross from salary data (already calculated)
      const grossArray = userSalaryData.gross || [];
      if (grossArray.length > 0) {
        const grossAmount = parseFloat(grossArray[0].EmployeeSalaryAmount) || 0;
        contractorInfo.gross += grossAmount;
      }

      // Use existing net pay from salary data (already calculated)
      const netPayArray = userSalaryData.netPay || [];
      if (netPayArray.length > 0) {
        const netAmount = parseFloat(netPayArray[0].EmployeeSalaryAmount) || 0;
        contractorInfo.netSalary += netAmount;
      }

      // Process earnings array (for individual payhead breakdown)
      const earnings = userSalaryData.earning || [];
      for (const item of earnings) {
        const payheadName = item.payheadName;
        const amount = parseFloat(item.EmployeeSalaryAmount) || 0;

        if (amount > 0) {
          usedPayheads.add(`E_${payheadName}`);
          contractorInfo.earnings[payheadName] =
            (contractorInfo.earnings[payheadName] || 0) + amount;
        }
      }

      // Process deductions array (for individual payhead breakdown)
      const deductions = userSalaryData.employeeDeduction || [];
      for (const item of deductions) {
        const payheadName = item.payheadName;
        const amount = parseFloat(item.EmployeeSalaryAmount) || 0;

        if (amount > 0) {
          usedPayheads.add(`D_${payheadName}`);
          contractorInfo.deductions[payheadName] =
            (contractorInfo.deductions[payheadName] || 0) + amount;
          contractorInfo.totalDeduction += amount;
        }
      }

      // Process extra earnings array (for individual payhead breakdown)
      const extraEarnings = userSalaryData.extraEarning || [];
      for (const item of extraEarnings) {
        const payheadName = item.payheadName;
        const amount = parseFloat(item.EmployeeSalaryAmount) || 0;

        if (amount > 0) {
          usedPayheads.add(`X_${payheadName}`);
          contractorInfo.extraEarnings[payheadName] =
            (contractorInfo.extraEarnings[payheadName] || 0) + amount;
        }
      }
    }

    // Extract only used payheads (memory optimization - only include what exists)
    const earningPayheads = [];
    const deductionPayheads = [];
    const extraEarningPayheads = [];

    // Get unique payhead names from used set
    for (const key of usedPayheads) {
      const [type, ...nameParts] = key.split('_');
      const name = nameParts.join('_');

      if (type === 'E') {
        earningPayheads.push({ name });
      } else if (type === 'D') {
        deductionPayheads.push({ name });
      } else if (type === 'X') {
        extraEarningPayheads.push({ name });
      }
    }

    // Sort payheads alphabetically for consistent display
    earningPayheads.sort((a, b) => a.name.localeCompare(b.name));
    deductionPayheads.sort((a, b) => a.name.localeCompare(b.name));
    extraEarningPayheads.sort((a, b) => a.name.localeCompare(b.name));

    // Prepare data for response/PDF (memory efficient)
    const reportData = [];
    let totalEmployees = 0;
    let totalPayableDays = 0;
    let totalOtMinutes = 0; // Sum minutes first
    let totalGross = 0;
    let totalDeductions = 0;
    let totalNet = 0;
    const grandTotalEarnings = {};
    const grandTotalDeductions = {};
    const grandTotalExtraEarnings = {};

    for (const [contractorId, contractorInfo] of contractorWiseData) {
      const rowData = {
        contractorName: contractorInfo.contractorName,
        employeeCount: contractorInfo.employeeCount,
        payableDays: formatAmount(contractorInfo.payableDays),
        otHours: minutesToHoursMinutes(contractorInfo.otMinutes), // Convert minutes to HH:MM format
        earnings: {},
        deductions: {},
        extraEarnings: {},
        gross: formatAmount(contractorInfo.gross),
        totalDeduction: formatAmount(contractorInfo.totalDeduction),
        netSalary: formatAmount(contractorInfo.netSalary),
      };

      // Add earning amounts (only for used payheads)
      for (const payhead of earningPayheads) {
        const amount = contractorInfo.earnings[payhead.name] || 0;
        rowData.earnings[payhead.name] = formatAmount(amount);
        grandTotalEarnings[payhead.name] =
          (grandTotalEarnings[payhead.name] || 0) + amount;
      }

      // Add deduction amounts (only for used payheads)
      for (const payhead of deductionPayheads) {
        const amount = contractorInfo.deductions[payhead.name] || 0;
        rowData.deductions[payhead.name] = formatAmount(amount);
        grandTotalDeductions[payhead.name] =
          (grandTotalDeductions[payhead.name] || 0) + amount;
      }

      // Add extra earning amounts (only for used payheads)
      for (const payhead of extraEarningPayheads) {
        const amount = contractorInfo.extraEarnings[payhead.name] || 0;
        rowData.extraEarnings[payhead.name] = formatAmount(amount);
        grandTotalExtraEarnings[payhead.name] =
          (grandTotalExtraEarnings[payhead.name] || 0) + amount;
      }

      totalEmployees += contractorInfo.employeeCount;
      totalPayableDays += contractorInfo.payableDays;
      totalOtMinutes += contractorInfo.otMinutes; // Sum minutes
      totalGross += contractorInfo.gross;
      totalDeductions += contractorInfo.totalDeduction;
      totalNet += contractorInfo.netSalary;

      reportData.push(rowData);
    }

    // Add grand total row
    const grandTotal = {
      contractorName: 'Total',
      employeeCount: totalEmployees,
      payableDays: formatAmount(totalPayableDays),
      otHours: minutesToHoursMinutes(totalOtMinutes), // Convert total minutes to HH:MM format
      earnings: {},
      deductions: {},
      extraEarnings: {},
      gross: formatAmount(totalGross),
      totalDeduction: formatAmount(totalDeductions),
      netSalary: formatAmount(totalNet),
    };

    // Format grand totals
    for (const payhead of earningPayheads) {
      grandTotal.earnings[payhead.name] = formatAmount(
        grandTotalEarnings[payhead.name] || 0,
      );
    }
    for (const payhead of deductionPayheads) {
      grandTotal.deductions[payhead.name] = formatAmount(
        grandTotalDeductions[payhead.name] || 0,
      );
    }
    for (const payhead of extraEarningPayheads) {
      grandTotal.extraEarnings[payhead.name] = formatAmount(
        grandTotalExtraEarnings[payhead.name] || 0,
      );
    }

    reportData.push(grandTotal);

    // Format month/year for display
    const year = YYYYMM.toString().substring(0, 4);
    const monthIndex = parseInt(YYYYMM.toString().substring(4, 6));
    const monthName = month_dict[monthIndex.toString().padStart(2, '0')] || '';
    const reportPeriod = `${monthName} ${year}`;

    if (Export === 'pdf') {
      return await generateContractorWiseSalarySummaryPDF(
        reportData,
        earningPayheads,
        deductionPayheads,
        extraEarningPayheads,
        reportPeriod,
        companyName,
        res,
      );
    }

    return res.status(statusCodes.OK).json({
      status: statusCodes.OK,
      data: reportData,
      earningPayheads,
      deductionPayheads,
      extraEarningPayheads,
      reportPeriod,
      companyName,
    });
  } catch (error) {
    next(error);
  }
};

// Helper function to generate PDF for contractor-wise salary summary
async function generateContractorWiseSalarySummaryPDF(
  reportData,
  earningPayheads,
  deductionPayheads,
  extraEarningPayheads,
  reportPeriod,
  companyName,
  res,
) {
  try {
    const getTemplate = () => {
      const file = path.join(
        __dirname,
        '../html/contractor-wise-salary-summary.html',
      );
      return file;
    };

    const readFile = (name) => {
      return new Promise((resolve, reject) => {
        fs.readFile(name, 'utf-8', (err, result) => {
          if (err) {
            reject(err);
          } else {
            resolve(result);
          }
        });
      });
    };

    const filePath = await getTemplate();
    const file = await readFile(filePath);
    const template = Handlebars.compile(file);

    const html = template({
      reportData,
      earningPayheads,
      deductionPayheads,
      extraEarningPayheads,
      reportPeriod,
      companyName,
    });

    const browser = await puppeteer.launch({
      headless: 'new',
      args: ['--no-sandbox', '--disable-setuid-sandbox'],
    });
    const page = await browser.newPage();

    await page.setContent(html, { waitUntil: 'networkidle0' });

    const pdfBuffer = await page.pdf({
      format: 'A4',
      printBackground: true,
      margin: { top: '10px', bottom: '10px', left: '10px', right: '10px' },
      landscape: true,
    });

    await browser.close();

    const base64path = Buffer.from(pdfBuffer).toString('base64');

    return res.status(200).json({
      status: 200,
      data: base64path,
    });
  } catch (error) {
    throw new Error(error);
  }
}

/**
 * Determines which leave types have non-zero values across all employees
 * @param {Array<number>} userMasterIDs - Array of employee IDs
 * @param {number} fromMonth - Start month in YYYYMM format
 * @param {number} toMonth - End month in YYYYMM format
 * @param {Array<number>} notIncludeLeaveIds - Array of leave IDs to exclude
 * @returns {Promise<Array<{LeaveID: number, LeaveName: string}>>} Array of leave type objects
 */
const determineLeaveTypes = async (
  userMasterIDs,
  fromMonth,
  toMonth,
  notIncludeLeaveIds,
) => {
  try {
    // Query hrLeaveMonthlyTrans with aggregation to find leave types with non-zero values
    const leaveTypesData = await hrLeaveMonthlyTrans.findAll({
      where: {
        userMasterID: {
          [Sequelize.Op.in]: userMasterIDs,
        },
        AttnYearMon: {
          [Sequelize.Op.between]: [fromMonth, toMonth],
        },
        verified: 1,
      },
      attributes: [
        [Sequelize.col('hrLeaveType.LeaveID'), 'LeaveID'],
        [Sequelize.col('hrLeaveType.LeaveMaster.LeaveName'), 'LeaveName'],
        [Sequelize.fn('SUM', Sequelize.col('AttnVal')), 'totalAttnVal'],
      ],
      include: [
        {
          model: hrLeaveTypes,
          attributes: [],
          where: {
            LeaveID: {
              [Sequelize.Op.notIn]: notIncludeLeaveIds,
            },
          },
          include: [
            {
              model: HrLeaveMaster,
              as: 'LeaveMaster',
              attributes: [],
            },
          ],
        },
      ],
      group: ['hrLeaveType.LeaveID', 'hrLeaveType->LeaveMaster.LeaveName'],
      having: Sequelize.where(Sequelize.fn('SUM', Sequelize.col('AttnVal')), {
        [Sequelize.Op.gt]: 0,
      }),
      order: [[Sequelize.col('hrLeaveType.LeaveID'), 'ASC']],
      raw: true,
    });

    // Transform the result to return only LeaveID and LeaveName
    return leaveTypesData.map((item) => ({
      LeaveID: item.LeaveID,
      LeaveName: item.LeaveName || '',
    }));
  } catch (error) {
    console.error('Error in determineLeaveTypes:', error);
    throw error;
  }
};

/**
 * Calculates payable days for an employee based on leave data and salary calculation rules
 * @param {Object} employee - Employee object with employeeJoiningDetail
 * @param {Map<number, number>} monthLeaveData - Map of LeaveID to AttnVal for the month
 * @returns {number} Payable days
 */
const calculatePayableDays = (employee, monthLeaveData) => {
  try {
    // Get salary calculation act from employee
    const salaryAct =
      employee.employeeJoiningDetails?.[0]?.salaryCalculationAct;

    // Define exclusion rules based on salary calculation act
    let excludeLeaveIds = [];

    if (salaryAct === 'F') {
      // Act F: Exclude WEEKOFF(7), ABSENT(5), LWP(18), ABSENT_DUE_TO_SANDWICH(28)
      excludeLeaveIds = [
        HrLeaveTypesIds.WEEKOFF,
        HrLeaveTypesIds.ABSENT,
        HrLeaveTypesIds.LWP,
        HrLeaveTypesIds.ABSENT_DUE_TO_SANDWICH,
      ];
    } else if (salaryAct === 'W') {
      // Act W: Exclude WEEKOFF(7), HOLIDAY(9), ABSENT(5), LWP(18), ABSENT_DUE_TO_SANDWICH(28)
      excludeLeaveIds = [
        HrLeaveTypesIds.WEEKOFF,
        HrLeaveTypesIds.HOLIDAY,
        HrLeaveTypesIds.ABSENT,
        HrLeaveTypesIds.LWP,
        HrLeaveTypesIds.ABSENT_DUE_TO_SANDWICH,
      ];
    } else {
      // Default: Exclude ABSENT(5), LWP(18), ABSENT_DUE_TO_SANDWICH(28)
      excludeLeaveIds = [
        HrLeaveTypesIds.ABSENT,
        HrLeaveTypesIds.LWP,
        HrLeaveTypesIds.ABSENT_DUE_TO_SANDWICH,
      ];
    }

    // Convert to Set for faster lookup
    const excludeSet = new Set(excludeLeaveIds);

    // Calculate payable days by summing non-excluded leave types
    let payableDays = 0;

    if (monthLeaveData && typeof monthLeaveData === 'object') {
      for (const [leaveId, attnVal] of Object.entries(monthLeaveData)) {
        // If LeaveID is not in exclusion list, add to payable days
        if (!excludeSet.has(parseInt(leaveId))) {
          payableDays += parseFloat(attnVal) || 0;
        }
      }
    }

    return payableDays;
  } catch (error) {
    console.error('Error in calculatePayableDays:', error);
    return 0;
  }
};

/**
 * Fetches a chunk of employees with all required associations
 * @param {Array<number>} chunkUserMasterIDs - Array of employee IDs for this chunk
 * @param {string} endDate - End date for filtering applicable records (YYYY-MM-DD format)
 * @param {Object} accessControlWhere - Access control where clause from accessibleRoleWiseUsers
 * @param {number} companyMasterID - Company identifier
 * @param {Array} sortField - Sort field array for ordering
 * @returns {Promise<Array>} Array of employee objects with eager-loaded associations
 */
const fetchEmployeeChunk = async (
  chunkUserMasterIDs,
  endDate,
  accessControlWhere,
  companyMasterID,
  sortField,
) => {
  try {
    const orderByFields = getOrderByFields(sortField);

    const employees = await UserMaster.findAll({
      where: {
        ...accessControlWhere,
        companyMasterId: companyMasterID,
        userMasterID: {
          [Sequelize.Op.in]: chunkUserMasterIDs,
        },
        status: [0, 1],
      },
      attributes: ['userMasterID', 'displayName', 'userNumber'],
      include: [
        {
          required: true,
          model: EmployeeJoiningDetails,
          attributes: ['employeeCode', 'salaryCalculationAct'],
        },
        {
          model: EmployeeDesignation,
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: endDate },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: endDate } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['designationID'],
          include: [
            {
              model: Designation,
              as: 'designation',
              attributes: ['designationName'],
            },
          ],
        },
        {
          model: EmployeeDepartment,
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: endDate },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: endDate } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['departmentID'],
          include: [
            {
              model: Department,
              as: 'department',
              attributes: ['departmentName'],
            },
          ],
        },
        {
          model: EmployeeBranch,
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: endDate },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: endDate } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['branchID'],
          include: [
            {
              model: BranchMaster,
              as: 'branchMaster',
              attributes: ['branchName'],
            },
          ],
        },
        {
          model: EmployeeDivision,
          where: {
            status: 1,
            startDate: { [Sequelize.Op.lte]: endDate },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: endDate } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['divisionId'],
          include: [
            {
              model: Division,
              attributes: ['divisionName'],
            },
          ],
        },
        {
          model: EmployeeWorkingArea,
          where: {
            status: 1,
            startDate: { [Sequelize.Op.lte]: endDate },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: endDate } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['workingAreaId'],
          include: [
            {
              model: WorkingArea,
              attributes: ['workingAreaName'],
            },
          ],
        },
      ],
      order: orderByFields,
    });

    return employees;
  } catch (error) {
    console.error('Error in fetchEmployeeChunk:', error);
    throw error;
  }
};

/**
 * Fetches leave data for a chunk of employees
 * @param {Array<number>} chunkUserMasterIDs - Array of employee IDs for this chunk
 * @param {number} fromMonth - Start month in YYYYMM format
 * @param {number} toMonth - End month in YYYYMM format
 * @param {Array<number>} notIncludeLeaveIds - Array of leave IDs to exclude
 * @returns {Promise<{leaveDataMap: Object, leaveTranIdToLeaveIdMap: Map}>} Object containing:
 *   - leaveDataMap: Nested object structure userMasterID → month → LeaveTranId → AttnVal
 *   - leaveTranIdToLeaveIdMap: Map of LeaveTranId → LeaveID for use in calculatePayableDays
 */
const fetchLeaveDataForChunk = async (
  chunkUserMasterIDs,
  fromMonth,
  toMonth,
  notIncludeLeaveIds,
) => {
  try {
    // Query hrLeaveMonthlyTrans with joins to hrLeaveTypes and HrLeaveMaster
    const leaveData = await hrLeaveMonthlyTrans.findAll({
      where: {
        userMasterID: {
          [Sequelize.Op.in]: chunkUserMasterIDs,
        },
        AttnYearMon: {
          [Sequelize.Op.between]: [fromMonth, toMonth],
        },
      },
      attributes: ['userMasterID', 'AttnYearMon', 'LeaveTranId', 'AttnVal'],
      include: [
        {
          model: hrLeaveTypes,
          where: {
            LeaveID: {
              [Sequelize.Op.notIn]: notIncludeLeaveIds,
            },
          },
          required: false,
          attributes: ['LeaveID'],
          include: [
            {
              model: HrLeaveMaster,
              as: 'LeaveMaster',
              attributes: ['LeaveName'],
            },
          ],
        },
      ],
      raw: false,
    });

    // Transform data into nested Map structure: userMasterID → month → LeaveTranId → AttnVal
    const leaveDataMap = {};
    const leaveTranIdToLeaveIdMap = new Map();

    for (const record of leaveData) {
      const userMasterID = record.userMasterID;
      const month = record.AttnYearMon;
      const leaveTranId = record.LeaveTranId;
      const attnVal = record.AttnVal;
      const leaveId = record.hrLeaveType?.LeaveID;

      // Build the nested structure
      if (!leaveDataMap[userMasterID]) {
        leaveDataMap[userMasterID] = {};
      }
      if (!leaveDataMap[userMasterID][month]) {
        leaveDataMap[userMasterID][month] = {};
      }
      leaveDataMap[userMasterID][month][leaveTranId] = attnVal;

      // Map LeaveTranId to LeaveID for calculatePayableDays
      if (leaveId !== undefined && leaveId !== null) {
        leaveTranIdToLeaveIdMap.set(leaveTranId, leaveId);
      }
    }

    return {
      leaveDataMap,
      leaveTranIdToLeaveIdMap,
    };
  } catch (error) {
    console.error('Error in fetchLeaveDataForChunk:', error);
    throw error;
  }
};

/**
 * Fetches overtime data for a chunk of employees
 * @param {Array<number>} chunkUserMasterIDs - Array of employee IDs for this chunk
 * @param {number} fromMonth - Start month in YYYYMM format
 * @param {number} toMonth - End month in YYYYMM format
 * @returns {Promise<Object>} Nested object structure userMasterID → month → overtimehrs
 */
const fetchOvertimeDataForChunk = async (
  chunkUserMasterIDs,
  fromMonth,
  toMonth,
) => {
  try {
    // Query overTimeCalculationMain with WHERE IN clause for chunk userMasterIDs
    const overtimeData = await overTimeCalculationMain.findAll({
      where: {
        userMasterID: {
          [Sequelize.Op.in]: chunkUserMasterIDs,
        },
        yyyymm: {
          [Sequelize.Op.between]: [fromMonth, toMonth],
        },
      },
      attributes: ['userMasterID', 'yyyymm', 'overtimehrs'],
      raw: true,
    });

    // Transform data into nested Map structure: userMasterID → month → overtimehrs
    const overtimeDataMap = {};

    for (const record of overtimeData) {
      const userMasterID = record.userMasterID;
      const month = record.yyyymm;
      const overtimehrs = record.overtimehrs;

      // Build the nested structure
      if (!overtimeDataMap[userMasterID]) {
        overtimeDataMap[userMasterID] = {};
      }
      overtimeDataMap[userMasterID][month] = overtimehrs;
    }

    return overtimeDataMap;
  } catch (error) {
    console.error('Error in fetchOvertimeDataForChunk:', error);
    throw error;
  }
};

/**
 * Processes a chunk of employees for Detailed Report
 * @param {Array} employeeChunk - Array of employee objects with eager-loaded associations
 * @param {Object} leaveDataMap - Nested object structure userMasterID → month → LeaveTranId → AttnVal
 * @param {Object} overtimeDataMap - Nested object structure userMasterID → month → overtimehrs
 * @param {Array<{LeaveTranId: number, LeaveName: string}>} leaveTypes - Array of leave type objects
 * @param {number} fromMonth - Start month in YYYYMM format
 * @param {number} toMonth - End month in YYYYMM format
 * @param {Map<number, number>} leaveTranIdToLeaveIdMap - Map of LeaveTranId to LeaveID
 * @returns {Array<Object>} Array of row objects ready for Excel writing
 */
const processEmployeeChunkDetailed = (
  employeeChunk,
  leaveDataMap,
  overtimeDataMap,
  leaveTypes,
  fromMonth,
  toMonth,
) => {
  try {
    const rows = [];
    const monthRange = getMonthRange(+fromMonth, +toMonth);

    for (const employee of employeeChunk) {
      const userMasterID = employee.userMasterID;

      // Initialize employee totals
      const employeeTotals = {
        leaveTypeTotals: {},
        payableDaysTotal: 0,
        overtimeTotal: 0,
      };

      // Initialize leave type totals
      for (const leaveType of leaveTypes) {
        employeeTotals.leaveTypeTotals[leaveType.LeaveID] = 0;
      }

      // Process each month for this employee
      for (const month of monthRange) {
        // Extract employee details handling Sequelize alias variations
        const employeeCode =
          employee.employeeJoiningDetails?.[0]?.employeeCode || '';
        const displayName = employee.displayName || '';
        const number = employee.userNumber || '';

        // Handle branch with alias variations
        const branch =
          employee.employeeBranches?.[0]?.branchMaster?.branchName || '';

        // Handle department with alias variations
        const department =
          employee.employeeDepartments?.[0]?.department?.departmentName || '';

        // Handle designation with alias variations
        const designation =
          employee.employeeDesignations?.[0]?.designation?.designationName ||
          '';

        // Handle division with alias variations
        const division =
          employee.employeeDivisions?.[0]?.division?.divisionName || '';

        // Handle working area with alias variations
        const workingArea =
          employee.employeeWorkingAreas?.[0]?.workingArea?.workingAreaName ||
          '';

        const skillCategory = employee.emp_skill?.[0]?.skillCategory || '';

        // Build row object with fixed columns
        const row = {
          employeeCode,
          employeeName: displayName,
          number,
          branch,
          department,
          designation,
          division,
          workingArea,
          skillCategory,
          month: formatMonth(month),
        };

        // Get leave data for this employee and month
        const monthLeaveData = leaveDataMap[userMasterID]?.[month] || {};

        // Add leave type columns
        for (const leaveType of leaveTypes) {
          const attnVal = monthLeaveData[leaveType.LeaveID] || 0;
          row[leaveType.LeaveName] = attnVal;

          // Accumulate for employee total
          employeeTotals.leaveTypeTotals[leaveType.LeaveID] +=
            parseFloat(attnVal) || 0;
        }

        // Calculate and add payable days
        const payableDays = calculatePayableDays(employee, monthLeaveData);
        row.payableDays = payableDays;
        employeeTotals.payableDaysTotal += payableDays;

        // Add overtime minutes
        const overtimeMinutes = overtimeDataMap[userMasterID]?.[month] || 0;
        row.overtimeMinutes = minutesToHoursMinutes(overtimeMinutes);
        employeeTotals.overtimeTotal += parseFloat(overtimeMinutes) || 0;

        rows.push(row);
      }

      // Add employee total row
      const totalRow = {
        employeeCode: 'Total',
        employeeName: '',
        number: '',
        branch: '',
        department: '',
        designation: '',
        division: '',
        workingArea: '',
        skillCategory: '',
        month: '',
      };

      // Add leave type totals
      for (const leaveType of leaveTypes) {
        totalRow[leaveType.LeaveName] =
          employeeTotals.leaveTypeTotals[leaveType.LeaveID];
      }

      totalRow.payableDays = employeeTotals.payableDaysTotal;
      totalRow.overtimeMinutes = minutesToHoursMinutes(
        employeeTotals.overtimeTotal,
      );

      rows.push(totalRow);
    }

    return rows;
  } catch (error) {
    console.error('Error in processEmployeeChunkDetailed:', error);
    throw error;
  }
};

/**
 * Processes a chunk of employees for Summary Report
 * @param {Array} employeeChunk - Array of employee objects with eager-loaded associations
 * @param {Object} leaveDataMap - Nested object structure userMasterID → month → LeaveTranId → AttnVal
 * @param {Object} overtimeDataMap - Nested object structure userMasterID → month → overtimehrs
 * @param {Array<{LeaveTranId: number, LeaveName: string}>} leaveTypes - Array of leave type objects
 * @param {number} fromMonth - Start month in YYYYMM format
 * @param {number} toMonth - End month in YYYYMM format
 * @param {Map<number, number>} leaveTranIdToLeaveIdMap - Map of LeaveTranId to LeaveID
 * @returns {Array<Object>} Array of row objects ready for Excel writing
 */
const processEmployeeChunkSummary = (
  employeeChunk,
  leaveDataMap,
  overtimeDataMap,
  leaveTypes,
  fromMonth,
  toMonth,
) => {
  try {
    const rows = [];
    const monthRange = getMonthRange(fromMonth, toMonth);

    for (const employee of employeeChunk) {
      const userMasterID = employee.userMasterID;

      // Extract employee details handling Sequelize alias variations
      const employeeCode =
        employee.employeeJoiningDetails?.[0]?.employeeCode || '';
      const displayName = employee.displayName || '';
      const number = employee.userNumber || '';

      // Handle branch with alias variations
      const branch =
        employee.employeeBranches?.[0]?.branchMaster?.branchName || '';

      // Handle department with alias variations
      const department =
        employee.employeeDepartments?.[0]?.department?.departmentName || '';

      // Handle designation with alias variations
      const designation =
        employee.employeeDesignations?.[0]?.designation?.designationName || '';

      // Handle division with alias variations
      const division =
        employee.employeeDivisions?.[0]?.division?.divisionName || '';

      // Handle working area with alias variations
      const workingArea =
        employee.employeeWorkingAreas?.[0]?.workingArea?.workingAreaName || '';

      const skillCategory = employee.emp_skill?.[0]?.skillCategory || '';

      // Build row object with fixed columns (no month column for summary)
      const row = {
        employeeCode,
        employeeName: displayName,
        number,
        branch,
        department,
        designation,
        division,
        workingArea,
        skillCategory,
      };

      // Initialize leave type sums
      const leaveTypeSums = {};
      for (const leaveType of leaveTypes) {
        leaveTypeSums[leaveType.LeaveID] = 0;
      }

      // Initialize payable days and overtime totals
      let payableDaysTotal = 0;
      let overtimeTotal = 0;

      // Aggregate across all months
      for (const month of monthRange) {
        // Get leave data for this employee and month
        const monthLeaveData = leaveDataMap[userMasterID]?.[month] || {};

        // Sum leave type values across all months
        for (const leaveType of leaveTypes) {
          const attnVal = monthLeaveData[leaveType.LeaveID] || 0;
          leaveTypeSums[leaveType.LeaveID] += parseFloat(attnVal) || 0;
        }

        // Sum payable days across all months
        const payableDays = calculatePayableDays(employee, monthLeaveData);
        payableDaysTotal += payableDays;

        // Sum overtime minutes across all months
        const overtimeMinutes = overtimeDataMap[userMasterID]?.[month] || 0;
        overtimeTotal += parseFloat(overtimeMinutes) || 0;
      }

      // Add aggregated leave type columns
      for (const leaveType of leaveTypes) {
        row[leaveType.LeaveName] = leaveTypeSums[leaveType.LeaveID];
      }

      // Add aggregated payable days and overtime
      row.payableDays = payableDaysTotal;
      row.overtimeMinutes = minutesToHoursMinutes(overtimeTotal);

      rows.push(row);
    }

    return rows;
  } catch (error) {
    console.error('Error in processEmployeeChunkSummary:', error);
    throw error;
  }
};

/**
 * @param {ExcelJS.Worksheet} worksheet - ExcelJS worksheet object
 *
 * */

const writeCompanyHeader = (worksheet, companyName, fromMonth, toMonth) => {
  let currentRow = 1;

  // Company Name Row
  if (companyName) {
    const companyRow = worksheet.addRow([companyName]);

    worksheet.mergeCells(`A${currentRow}:T${currentRow}`);

    const companyCell = worksheet.getCell(`A${currentRow}`);

    companyCell.font = {
      bold: true,
      size: 16,
    };

    companyCell.alignment = {
      horizontal: 'center',
      vertical: 'middle',
    };

    companyRow.commit();

    currentRow++;
  }

  // Month Range Row
  const monthName = `For the Period Of ${
    month_dict[String(fromMonth).slice(4, 6)]
  } - ${String(fromMonth).slice(0, 4)} To ${
    month_dict[String(toMonth).slice(4, 6)]
  } - ${String(toMonth).slice(0, 4)}`;

  const monthRow = worksheet.addRow([monthName]);

  worksheet.mergeCells(`A${currentRow}:T${currentRow}`);

  const monthCell = worksheet.getCell(`A${currentRow}`);

  monthCell.font = {
    bold: true,
    size: 13,
  };

  monthCell.alignment = {
    horizontal: 'center',
    vertical: 'middle',
  };

  monthRow.commit();
};

/**
 * Writes the Excel header row with styling
 * @param {ExcelJS.Worksheet} worksheet - ExcelJS worksheet object
 * @param {Array} leaveTypes - Array of leave type objects with LeaveName property
 * @param {string} reportType - Type of report ("Detailed" or "Summary")
 */

const writeExcelHeader = (worksheet, leaveTypes, reportType) => {
  try {
    // Build header array
    const headers = [
      'Employee Code',
      'Employee Name',
      'Number',
      'Branch',
      'Department',
      'Designation',
      'Division',
      'WorkingArea',
      'SkillCategory',
    ];

    if (reportType === mandaysReportTypeEnum.DETAILED_REPORT) {
      headers.push('Month');
    }

    for (const leaveType of leaveTypes) {
      headers.push(leaveType.LeaveName);
    }

    headers.push('Payable Days');
    headers.push('OT in Hrs');

    // Add header row manually
    const headerRow = worksheet.addRow(headers);

    // Apply styles
    headerRow.eachCell((cell) => {
      cell.font = {
        bold: true,
      };

      cell.alignment = {
        horizontal: 'center',
        vertical: 'middle',
      };

      // Light blue background
      cell.fill = {
        type: 'pattern',
        pattern: 'solid',
        fgColor: { argb: 'D9EAF7' },
      };

      cell.border = {
        top: { style: 'thin' },
        left: { style: 'thin' },
        bottom: { style: 'thin' },
        right: { style: 'thin' },
      };
    });

    // Commit row
    headerRow.commit();
  } catch (error) {
    console.error('Error in writeExcelHeader:', error);
    throw error;
  }
};

/**
 * Writes Excel rows to the worksheet with streaming
 * @param {ExcelJS.Worksheet} worksheet - ExcelJS worksheet object
 * @param {Array<Object>} rows - Array of row objects from processEmployeeChunkDetailed or processEmployeeChunkSummary
 * @param {Array} leaveTypes - Array of leave type objects with LeaveName property
 * @param {string} reportType - Type of report ("Detailed" or "Summary")
 */
const writeExcelRows = (worksheet, rows, leaveTypes, reportType) => {
  try {
    // Process each row
    for (const rowObj of rows) {
      // Build row array matching header column order
      const rowArray = [
        rowObj.employeeCode || '',
        rowObj.employeeName || '',
        rowObj.number || '',
        rowObj.branch || '',
        rowObj.department || '',
        rowObj.designation || '',
        rowObj.division || '',
        rowObj.workingArea || '',
        rowObj.skillCategory || '',
      ];

      // Add month column if reportType is "Detailed"
      if (reportType === mandaysReportTypeEnum.DETAILED_REPORT) {
        rowArray.push(rowObj.month || '');
      }

      const mergeCellLenth = rowArray.length;

      // Add leave type columns in the same order as header
      for (const leaveType of leaveTypes) {
        rowArray.push(rowObj[leaveType.LeaveName] || 0);
      }

      // Add payable days and overtime minutes
      rowArray.push(rowObj.payableDays || 0);
      rowArray.push(rowObj.overtimeMinutes || 0);

      const excelRow = worksheet.addRow(rowArray);

      if (
        reportType === mandaysReportTypeEnum.DETAILED_REPORT &&
        rowObj.employeeCode === 'Total'
      ) {
        // Make all cells bold
        excelRow.eachCell((cell) => {
          cell.font = {
            bold: true,
          };

          cell.fill = {
            type: 'pattern',
            pattern: 'solid',
            fgColor: { argb: 'D3D3D3' },
          };
        });

        // Merge all columns
        worksheet.mergeCells(
          excelRow.number,
          1,
          excelRow.number,
          mergeCellLenth,
        );

        // Set alignment
        const cell = worksheet.getCell(excelRow.number, 1);

        cell.value = rowObj.employeeCode;

        cell.alignment = {
          horizontal: 'right',
          vertical: 'middle',
        };
      }

      excelRow.commit();
    }
  } catch (error) {
    console.error('Error in writeExcelRows:', error);
    throw error;
  }
};

/**
 * Writes the grand total row to the worksheet
 * @param {ExcelJS.Worksheet} worksheet - ExcelJS worksheet object
 * @param {Object} allEmployeeData - Accumulated totals from all chunks
 *   Structure: { leaveTypeTotals: {LeaveTranId: sum}, payableDaysTotal: sum, overtimeTotal: sum }
 * @param {Array} leaveTypes - Array of leave type objects with LeaveTranId and LeaveName properties
 * @param {string} reportType - Type of report ("Detailed" or "Summary")
 */
const writeGrandTotal = (
  worksheet,
  allEmployeeData,
  leaveTypes,
  reportType,
) => {
  try {
    // Build grand total row array matching header column order

    const grandTotalRow = [
      'Grand Total', // Employee Code - empty
      '', // Employee Name - "Grand Total"
      '', // Number - empty
      '', // Branch - empty
      '', // Department - empty
      '', // Designation - empty
      '', // Division - empty
      '',
      '', // WorkingArea - empty
    ];

    // Add empty month column if reportType is "Detailed"
    if (reportType === mandaysReportTypeEnum.DETAILED_REPORT) {
      grandTotalRow.push('');
    }

    const mergeCell_length = grandTotalRow.length;

    // Add leave type totals in the same order as header
    for (const leaveType of leaveTypes) {
      const total = allEmployeeData.leaveTypeTotals[leaveType.LeaveID] || 0;
      grandTotalRow.push(total);
    }

    // Add payable days total and overtime total
    grandTotalRow.push(allEmployeeData.payableDaysTotal || 0);
    grandTotalRow.push(
      minutesToHoursMinutes(allEmployeeData.overtimeTotal || 0),
    );

    // Write grand total row to worksheet
    const excelRow = worksheet.addRow(grandTotalRow);

    // Make all cells bold
    excelRow.eachCell((cell) => {
      cell.font = {
        bold: true,
      };

      cell.fill = {
        type: 'pattern',
        pattern: 'solid',
        fgColor: { argb: 'A9A9A9' },
      };
    });

    // Merge all columns
    worksheet.mergeCells(excelRow.number, 1, excelRow.number, mergeCell_length);

    // Set alignment
    const cell = worksheet.getCell(excelRow.number, 1);

    cell.value = 'Grand Total';

    cell.alignment = {
      horizontal: 'right',
      vertical: 'middle',
    };

    // Commit row to stream immediately
    excelRow.commit();
  } catch (error) {
    console.error('Error in writeGrandTotal:', error);
    throw error;
  }
};

exports.yearlyMandaysReport = async (req, res, next) => {
  try {
    const {
      companyMasterID,
      userMasterID,
      fromMonth,
      toMonth,
      reportType,
      sortField,
    } = req.body;

    if (
      !companyMasterID ||
      !userMasterID ||
      (Array.isArray(userMasterID) && userMasterID.length == 0) ||
      !fromMonth ||
      !toMonth ||
      !reportType
    ) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: message.usermessage.passValidValidParameter(
          'companyMasterID, userMasterID , fromMonth,toMonth and reportType',
        ),
      });
    }

    // Validate reportType
    if (
      reportType !== mandaysReportTypeEnum.DETAILED_REPORT &&
      reportType !== mandaysReportTypeEnum.SUMMARY_REPORT
    ) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: `reportType must be either ${mandaysReportTypeEnum.DETAILED_REPORT} or ${mandaysReportTypeEnum.SUMMARY_REPORT}`,
      });
    }

    const currentMonth = moment().format('YYYYMM');

    if (+fromMonth > +currentMonth || +toMonth > +currentMonth) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: 'Future months are not allowed.',
      });
    }

    if (+fromMonth > +toMonth) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: 'From Month cannot be greater than To Month.',
      });
    }

    const monthRange = getMonthRange(+fromMonth, +toMonth);

    if (monthRange.length > 12) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: 'You cannot download the report for more than 12 months.',
      });
    }

    const companyData = await companyMaster.findOne({
      where: {
        companyMasterID,
      },
      attributes: ['companyName'],
    });

    const month = String(toMonth).slice(4, 6);
    const year = String(toMonth).slice(0, 4);

    const endDate = year + '-' + month + '-' + daysInMonth(month, year);

    const { where, includeModels } = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: false,
    });

    const notIncludeLeaveIds = [
      HrLeaveTypesIds.ACTUAL_HOLIDAY,
      HrLeaveTypesIds.ACTUAL_WEEKOFF,
      HrLeaveTypesIds.ATTENDANCE_BONUS,
      HrLeaveTypesIds.ATTENDANCE_PENALTY,
      HrLeaveTypesIds.LEAVE_BEHALF_ON_SANDWICH,
      HrLeaveTypesIds.LEAVE_HRS,
      HrLeaveTypesIds.OT_HRS,
      HrLeaveTypesIds.PH_HRS,
      HrLeaveTypesIds.WORKING_HRS,
    ];

    const includeModel = [
      ...includeModels,
      {
        required: true,
        model: EmployeeJoiningDetails,
        attributes: ['employeeCode', 'salaryCalculationAct'],
      },
      {
        model: EmployeeDesignation,
        where: {
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: false,
        attributes: ['designationID'],
        include: [
          {
            model: Designation,
            as: 'designation',
            attributes: ['designationName'],
          },
        ],
      },
      {
        model: EmployeeDepartment,
        where: {
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: false,
        attributes: ['departmentID'],
        include: [
          {
            model: Department,
            as: 'department',
            attributes: ['departmentName'],
          },
        ],
      },
      {
        model: EmployeeBranch,
        where: {
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: false,
        attributes: ['branchID'],
        include: [
          {
            model: BranchMaster,
            as: 'branchMaster',
            attributes: ['branchName'],
          },
        ],
      },
      {
        model: EmployeeDivision,
        where: {
          status: 1,
          startDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        required: false,
        attributes: ['divisionId'],
        include: [
          {
            model: Division,
            attributes: ['divisionName'],
          },
        ],
      },
      {
        model: EmployeeWorkingArea,
        where: {
          status: 1,
          startDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        required: false,
        attributes: ['workingAreaId'],
        include: [
          {
            model: WorkingArea,
            attributes: ['workingAreaName'],
          },
        ],
      },
      //skill category
      {
        required: false,
        model: EmployeeSkillCategory,
        as: 'emp_skill',
        where: {
          status: 1,
          applicableYYYYMM: { [Sequelize.Op.lte]: toMonth },
          [Sequelize.Op.or]: [
            { endYYYYMM: { [Sequelize.Op.gte]: toMonth } },
            { endYYYYMM: { [Sequelize.Op.eq]: null } },
          ],
        },
        attributes: ['skillCategory'],
      },
      {
        required: false,
        model: hrLeaveMonthlyTrans,
        where: {
          AttnYearMon: {
            [Sequelize.Op.between]: [fromMonth, toMonth],
          },
          AttnVal: {
            [Sequelize.Op.gt]: 0,
          },
          verified: 1,
        },
        include: [
          {
            required: false,
            model: hrLeaveTypes,
            where: {
              LeaveID: {
                [Sequelize.Op.notIn]: notIncludeLeaveIds,
              },
            },
            attributes: ['LeaveID'],
            include: [
              {
                model: HrLeaveMaster,
                as: 'LeaveMaster',
                attributes: ['LeaveName'],
              },
            ],
          },
        ],
        attributes: ['LeaveTranId', 'AttnYearMon', 'AttnVal'],
      },
      {
        required: false,
        model: overTimeCalculationMain,
        where: {
          yyyymm: {
            [Sequelize.Op.between]: [fromMonth, toMonth],
          },
        },
        attributes: ['overtimehrs', 'yyyymm'],
      },
    ];

    const orderByFields = getOrderByFields(sortField);

    // Step 1: Determine which leave types to include in the report
    const leaveTypes = await determineLeaveTypes(
      userMasterID,
      fromMonth,
      toMonth,
      notIncludeLeaveIds,
    );

    // Step 2: Initialize Excel stream and write header
    const fileName = `Yearly_Mandays_${reportType}_Report`;

    const columnWidthArray = [];

    // FIRST set widths
    const totalColumns = 20;

    for (let i = 1; i <= totalColumns; i++) {
      if (i > 8) {
        columnWidthArray.push({ width: 15 });
      } else {
        columnWidthArray.push({ width: 25 });
      }
    }

    const sheets = [
      {
        name: 'Mandays_Report',
        freeze: {
          state: 'frozen',
          ySplit: 4,
          xSplit: 3,
        },
        columns: columnWidthArray,
      },
    ];
    const { workbook, worksheets } = initializeExcelStream({
      res,
      fileName,
      sheets,
      useStyles: true,
      useSharedStrings: true,
    });

    const worksheet = worksheets['Mandays_Report'];

    writeCompanyHeader(
      worksheet,
      companyData?.companyName || '',
      fromMonth,
      toMonth,
    );

    worksheet.addRow([]);

    writeExcelHeader(worksheet, leaveTypes, reportType);

    // Step 3: Initialize grand total accumulator
    const grandTotal = {
      leaveTypeTotals: {},
      payableDaysTotal: 0,
      overtimeTotal: 0,
    };

    // Initialize leave type totals (using LeaveID as key)
    for (const leaveType of leaveTypes) {
      grandTotal.leaveTypeTotals[leaveType.LeaveID] = 0;
    }

    // Step 4: Process employees in chunks of 300 using LIMIT/OFFSET
    const chunkSize = 300;
    let offset = 0;
    let hasMoreData = true;

    while (hasMoreData) {
      // Fetch employee chunk with LIMIT/OFFSET
      const employeeChunk = await UserMaster.findAll({
        where: {
          ...where,
          companyMasterId: companyMasterID,
          userMasterID: {
            [Sequelize.Op.in]: userMasterID,
          },
          status: [0, 1],
        },
        attributes: ['userMasterID', 'displayName', 'userNumber'],
        include: includeModel,
        order: orderByFields,
        limit: chunkSize,
        offset: offset,
      });

      // Check if we have more data
      if (employeeChunk.length === 0) {
        hasMoreData = false;
        break;
      }

      // Extract leave and overtime data from the included models
      const leaveDataMap = {};
      const overtimeDataMap = {};

      for (const employee of employeeChunk) {
        const userMasterID = employee.userMasterID;

        // Extract leave data from hrLeaveMonthlyTrans include
        leaveDataMap[userMasterID] = {};
        if (
          employee.hrLeaveMonthlyTrans &&
          Array.isArray(employee.hrLeaveMonthlyTrans)
        ) {
          for (const leaveTrans of employee.hrLeaveMonthlyTrans) {
            const month = +leaveTrans.AttnYearMon;
            const leaveId = leaveTrans.hrLeaveType?.LeaveID;
            const attnVal = leaveTrans.AttnVal;

            if (leaveId) {
              if (!leaveDataMap[userMasterID][month]) {
                leaveDataMap[userMasterID][month] = {};
              }
              leaveDataMap[userMasterID][month][leaveId] = attnVal;
            }
          }
        }

        // Extract overtime data from overTimeCalculationMain include
        overtimeDataMap[userMasterID] = {};
        if (
          employee.OverTimeCalculationMains &&
          Array.isArray(employee.OverTimeCalculationMains)
        ) {
          for (const otRecord of employee.OverTimeCalculationMains) {
            const month = +otRecord.yyyymm;
            const overtimehrs = otRecord.overtimehrs;
            overtimeDataMap[userMasterID][month] = overtimehrs;
          }
        }
      }

      // Process chunk based on report type
      let rows;
      if (reportType === mandaysReportTypeEnum.DETAILED_REPORT) {
        rows = processEmployeeChunkDetailed(
          employeeChunk,
          leaveDataMap,
          overtimeDataMap,
          leaveTypes,
          fromMonth,
          toMonth,
        );
      } else {
        rows = processEmployeeChunkSummary(
          employeeChunk,
          leaveDataMap,
          overtimeDataMap,
          leaveTypes,
          fromMonth,
          toMonth,
        );
      }

      // Write rows to Excel
      writeExcelRows(worksheet, rows, leaveTypes, reportType);

      // Accumulate grand totals
      for (const row of rows) {
        // Skip employee total rows (they have empty employeeCode)
        if (
          row.employeeCode !== 'Total' &&
          reportType == mandaysReportTypeEnum.DETAILED_REPORT
        ) {
          continue;
        }

        // Accumulate leave type totals (using LeaveID as key)
        for (const leaveType of leaveTypes) {
          grandTotal.leaveTypeTotals[leaveType.LeaveID] +=
            parseFloat(row[leaveType.LeaveName]) || 0;
        }

        // Accumulate payable days and overtime
        grandTotal.payableDaysTotal += parseFloat(row.payableDays) || 0;
        grandTotal.overtimeTotal += convertHoursAndMinutesToMinutes(
          row.overtimeMinutes || 0,
        );
      }

      // Move to next chunk
      offset += chunkSize;

      // If we got less than chunkSize records, we're done
      if (employeeChunk.length < chunkSize) {
        hasMoreData = false;
      }
    }

    // Step 5: Write grand total row
    writeGrandTotal(worksheet, grandTotal, leaveTypes, reportType);

    // Step 6: Commit workbook and end response
    await workbook.commit();
  } catch (error) {
    next(error);
  }
};

const getTotalMandays = (
  joiningDate,
  leavingDate,
  startDate,
  endDate,
  whMap, // date => tableName => value
  priority, // ['holiday', 'weekoff'] OR ['weekoff', 'holiday']
) => {
  let totalMandays = 0;

  if (!joiningDate) return totalMandays;

  // Invalid employment range
  if (moment(joiningDate).isAfter(endDate)) {
    return totalMandays;
  }

  if (leavingDate && moment(leavingDate).isBefore(startDate)) {
    return totalMandays;
  }

  // Final effective range
  let effectiveStartDate = moment.max(moment(joiningDate), moment(startDate));
  let effectiveEndDate = leavingDate
    ? moment.min(moment(leavingDate), moment(endDate))
    : moment(endDate);

  let weekoffHolidaysCount = 0;

  // Clone for iteration to preserve original dates
  let currentDate = effectiveStartDate.clone();

  // Loop dates
  while (currentDate.isSameOrBefore(effectiveEndDate, 'day')) {
    const dateStr = currentDate.format('YYYY-MM-DD');

    // Get date map
    const dateMap = whMap?.get(dateStr);

    // Priority based calculation
    if (dateMap) {
      const value =
        priority === 'holiday'
          ? dateMap.get('holiday') || dateMap.get('weekoff')
          : dateMap.get('weekoff') || dateMap.get('holiday');

      if (value != null) {
        weekoffHolidaysCount += Number(value) || 0;
      }
    }

    currentDate.add(1, 'day');
  }

  // Use the original effective dates, not the mutated currentDate
  const monthDays = getDaysFromDates(
    effectiveStartDate.format('YYYY-MM-DD'),
    effectiveEndDate.format('YYYY-MM-DD'),
  );

  totalMandays = Math.max(monthDays - weekoffHolidaysCount, 0);

  return totalMandays;
};

const getLossPercentage = (actualDays, lossDays) => {
  return actualDays <= 0 ? 0 : Math.round((lossDays * 100) / actualDays);
};

const employeeWiseChunkProcess = (
  employeeData,
  weekoffHolidayMap,
  startDate,
  endDate,
  totalObject = {},
  worksheet,
) => {
  try {
    for (const employee of employeeData) {
      const userMasterID = +employee.userMasterID;

      const joining = employee.employeeJoiningDetails?.[0] || null;

      // Extract employee details handling Sequelize alias variations
      const employeeCode = joining?.employeeCode || '';
      const displayName = employee.displayName || '';
      const number = employee.userNumber || '';

      // Handle branch with alias variations
      const branch =
        employee.employeeBranches?.[0]?.branchMaster?.branchName || '';

      // Handle department with alias variations
      const department =
        employee.employeeDepartments?.[0]?.department?.departmentName || '';

      // Handle designation with alias variations
      const designation =
        employee.employeeDesignations?.[0]?.designation?.designationName || '';

      // Handle division with alias variations
      const division =
        employee.employeeDivisions?.[0]?.division?.divisionName || '';

      // Handle working area with alias variations
      const workingArea =
        employee.employeeWorkingAreas?.[0]?.workingArea?.workingAreaName || '';

      const skillCategory = employee.emp_skill?.[0]?.skillCategory || '';

      const attnCalData = employee.hrLeaveMonthlyTrans?.[0] || null;

      let totalMandays = attnCalData?.MonWorkDays || 0;
      if (!attnCalData) {
        const priority =
          employee.empAttPolicy?.[0]?.attendancePolicy?.WHPHPriority == 'PH'
            ? 'holiday'
            : 'weekoff';
        const joiningDate = joining.joiningDate;
        const leavingDate = joining.leavingDate;

        const whMap = weekoffHolidayMap?.get(userMasterID);

        totalMandays = getTotalMandays(
          joiningDate,
          leavingDate,
          startDate,
          endDate,
          whMap,
          priority,
        );
      }

      const actualWorked = attnCalData?.AttnVal || 0;
      const loss_Mandays = totalMandays - actualWorked;
      const percentageLossDays = getLossPercentage(totalMandays, loss_Mandays);

      totalObject.totalMandays += +totalMandays;
      totalObject.actualWorked += +actualWorked;
      totalObject.loss_Mandays += +loss_Mandays;

      // Build row object with fixed columns
      const row = [
        employeeCode,
        displayName,
        number,
        branch,
        department,
        designation,
        division,
        workingArea,
        skillCategory,
        totalMandays,
        actualWorked,
        loss_Mandays,
        percentageLossDays,
      ];

      const currentRow = worksheet.addRow(row);

      currentRow.commit();
    }

    return totalObject;
  } catch (error) {
    console.error('Error in employeeWiseChunkProcess:', error);
    throw error;
  }
};

const contractorWiseChunkPrcess = (
  employeeData,
  weekoffHolidayMap,
  startDate,
  endDate,
  contractorWiseMap,
) => {
  for (const employee of employeeData) {
    const userMasterID = +employee.userMasterID;

    const joining = employee.employeeJoiningDetails?.[0] || null;

    const contractorId = joining?.contractorId || null;

    if (!contractorId) continue;

    const getUserWiseContractor = contractorWiseMap?.get(contractorId);

    if (!getUserWiseContractor) continue;

    const attnCalData = employee.hrLeaveMonthlyTrans?.[0] || null;

    let totalMandays = attnCalData?.MonWorkDays || 0;
    if (!attnCalData) {
      const priority =
        employee.empAttPolicy?.[0]?.attendancePolicy?.WHPHPriority == 'PH'
          ? 'holiday'
          : 'weekoff';
      const joiningDate = joining.joiningDate;
      const leavingDate = joining.leavingDate;

      const whMap = weekoffHolidayMap?.get(userMasterID);

      totalMandays = getTotalMandays(
        joiningDate,
        leavingDate,
        startDate,
        endDate,
        whMap,
        priority,
      );

      if (totalMandays == 0) continue;
    }

    const actualWorked = attnCalData?.AttnVal || 0;
    const loss_Mandays = totalMandays - actualWorked;
    const percentageLossDays = getLossPercentage(totalMandays, loss_Mandays);

    getUserWiseContractor.employee += 1;
    getUserWiseContractor.mandays += +totalMandays;
    getUserWiseContractor.actualWorked += +actualWorked;
    getUserWiseContractor.lossMandays += +loss_Mandays;
  }

  return contractorWiseMap;
};

exports.absenteeismReport = async (req, res, next) => {
  try {
    const {
      companyMasterID,
      userMasterID,
      month,
      reportType,
      contractorId,
      sortField,
    } = req.body;

    if (!companyMasterID || !month || !reportType) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: message.usermessage.passValidValidParameter(
          'companyMasterID, month and reportType',
        ),
      });
    }

    if (
      (!userMasterID ||
        (Array.isArray(userMasterID) && userMasterID.length == 0)) &&
      reportType == absenteeismReportTypeEnum.EMPLOYEE_WISE
    ) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: message.usermessage.passValidValidParameter('userMasterID'),
      });
    }

    // Validate reportType
    if (
      reportType !== absenteeismReportTypeEnum.EMPLOYEE_WISE &&
      reportType !== absenteeismReportTypeEnum.CONTRACTOR_WISE
    ) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: `reportType must be either ${absenteeismReportTypeEnum.EMPLOYEE_WISE} or ${absenteeismReportTypeEnum.CONTRACTOR_WISE}`,
      });
    }

    const currentMonth = moment().format('YYYYMM');

    if (+month > +currentMonth) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: 'Future month is not allowed.',
      });
    }

    const companyData = await companyMaster.findOne({
      where: {
        companyMasterID,
      },
      attributes: ['companyName'],
    });

    let contractorWiseMap = new Map();

    if (reportType == absenteeismReportTypeEnum.CONTRACTOR_WISE) {
      const contractorCondition = { companyMasterID, status: 1 };

      if (contractorId && contractorId.length) {
        contractorCondition.contractorId = contractorId;
      }

      const contractorData = await Contractor.findAll({
        where: contractorCondition,
        order: [['contractorName', 'ASC']],
      });

      for (const contractor of contractorData) {
        const object = {
          name: '',
          employee: 0,
          mandays: 0,
          actualWorked: 0,
          lossMandays: 0,
          lossPercent: 0,
          avg: 0,
        };

        object.name = contractor.contractorName;
        const key = +contractor.contractorId;
        contractorWiseMap.set(key, object);
      }
    }

    const Month = String(month).slice(4, 6);
    const year = String(month).slice(0, 4);

    const startDate = year + '-' + Month + '-' + '01';
    const endDate = year + '-' + Month + '-' + daysInMonth(Month, year);

    const { where, includeModels } = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: false,
    });

    const joiningCondition = {};

    if (
      contractorId &&
      contractorId.length &&
      reportType == absenteeismReportTypeEnum.CONTRACTOR_WISE
    ) {
      joiningCondition.contractorId = contractorId;
    }

    const includeModel = [
      ...includeModels,
      {
        required: true,
        model: EmployeeJoiningDetails,
        where: joiningCondition,
        attributes: [
          'employeeCode',
          'contractorId',
          'joiningDate',
          'leavingDate',
        ],
      },
      {
        model: EmployeeDesignation,
        where: {
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: false,
        attributes: ['designationID'],
        include: [
          {
            model: Designation,
            as: 'designation',
            attributes: ['designationName'],
          },
        ],
      },
      {
        model: EmployeeDepartment,
        where: {
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: false,
        attributes: ['departmentID'],
        include: [
          {
            model: Department,
            as: 'department',
            attributes: ['departmentName'],
          },
        ],
      },
      {
        model: EmployeeBranch,
        where: {
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: false,
        attributes: ['branchID'],
        include: [
          {
            model: BranchMaster,
            as: 'branchMaster',
            attributes: ['branchName'],
          },
        ],
      },
      {
        model: EmployeeDivision,
        where: {
          status: 1,
          startDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        required: false,
        attributes: ['divisionId'],
        include: [
          {
            model: Division,
            attributes: ['divisionName'],
          },
        ],
      },
      {
        model: EmployeeWorkingArea,
        where: {
          status: 1,
          startDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        required: false,
        attributes: ['workingAreaId'],
        include: [
          {
            model: WorkingArea,
            attributes: ['workingAreaName'],
          },
        ],
      },
      //skill category
      {
        required: false,
        model: EmployeeSkillCategory,
        as: 'emp_skill',
        where: {
          status: 1,
          applicableYYYYMM: { [Sequelize.Op.lte]: month },
          [Sequelize.Op.or]: [
            { endYYYYMM: { [Sequelize.Op.gte]: month } },
            { endYYYYMM: { [Sequelize.Op.eq]: null } },
          ],
        },
        attributes: ['skillCategory'],
      },
      {
        required: false,
        separate: true,
        model: hrLeaveMonthlyTrans,
        where: {
          AttnYearMon: month,
          verified: 1,
        },
        include: [
          {
            required: true,
            model: hrLeaveTypes,
            where: {
              LeaveID: HrLeaveTypesIds.PRESENT,
            },
            attributes: ['LeaveID'],
          },
        ],
        attributes: ['MonWorkDays', 'AttnVal', 'LeaveTranId'],
      },
      {
        model: EmployeeAttendancePolicy,
        as: 'empAttPolicy',
        where: {
          status: 1,
          startDate: { [Sequelize.Op.lte]: endDate },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: endDate } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: false,
        attributes: ['attendancePolicyID'],
        include: [
          {
            model: AttendancePolicy,
            as: 'attendancePolicy',
            attributes: ['WHPHPriority'],
          },
        ],
      },
    ];

    const orderByFields = getOrderByFields(sortField);

    const fileName = `Absenteeism_${reportType}_Report`;

    const isEmployeeWise =
      reportType === absenteeismReportTypeEnum.EMPLOYEE_WISE;

    const columnWidthArray = Array.from(
      { length: isEmployeeWise ? 12 : 7 },
      (_, i) => ({
        width: (isEmployeeWise ? i > 8 : i > 1) ? 20 : 25,
      }),
    );

    const sheets = [
      {
        name: 'Absenteeism_Report',
        freeze: {
          state: 'frozen',
          ySplit: 3,
          xSplit: 3,
        },
        columns: columnWidthArray,
      },
    ];
    const { workbook, worksheets } = initializeExcelStream({
      res,
      fileName,
      sheets,
      useStyles: true,
      useSharedStrings: true,
    });

    const worksheet = worksheets['Absenteeism_Report'];

    // add company name and month -----------------

    const monthName = month_dict[Month] + '-' + year;

    const companyHeader = `Absenteeism Report for the ${companyData?.companyName || ''} (${monthName})`;

    const companyRow = worksheet.addRow([companyHeader]);

    worksheet.mergeCells(`A1:T1`);

    const companyCell = worksheet.getCell(`A1`);

    companyCell.font = {
      bold: true,
      size: 16,
    };

    companyCell.alignment = {
      horizontal: 'center',
      vertical: 'middle',
    };

    companyRow.commit();

    // --------------------------------------------------------

    // ----add empty row ------------------
    worksheet.addRow([]);

    // Add header row manually ---------------------------

    const headerColumns =
      reportType == absenteeismReportTypeEnum.EMPLOYEE_WISE
        ? [
            'Employee Code',
            'Employee Name',
            'Number',
            'Branch',
            'Department',
            'Designation',
            'Division',
            'WorkingArea',
            'SkillCategory',
            'Total Mandays',
            'Actual Mandays Worked',
            'Loss Mandays',
            '% of Lost Mandays',
          ]
        : [
            'Contractor Name',
            'No of Employee',
            'Total Mandays',
            'Actual Mandays Worked',
            'Loss Mandays',
            '% of Lost Mandays',
            'Total Avg Manpower Perday',
          ];

    const headerRow = worksheet.addRow(headerColumns);

    // Apply styles
    headerRow.eachCell((cell) => {
      cell.font = {
        bold: true,
      };

      cell.alignment = {
        horizontal: 'center',
        vertical: 'middle',
      };

      // Light blue background
      cell.fill = {
        type: 'pattern',
        pattern: 'solid',
        fgColor: { argb: 'D9EAF7' },
      };

      cell.border = {
        top: { style: 'thin' },
        left: { style: 'thin' },
        bottom: { style: 'thin' },
        right: { style: 'thin' },
      };
    });

    // Commit row
    headerRow.commit();

    // ---------------------------------------------------------------------

    // Step 4: Process employees in chunks of 300 using LIMIT/OFFSET
    const chunkSize = 300;
    let offset = 0;
    let hasMoreData = true;

    let totalObject = { actualWorked: 0, loss_Mandays: 0, totalMandays: 0 };

    const condition = {
      ...where,
      companyMasterId: companyMasterID,
      status: [0, 1],
    };

    if (reportType == absenteeismReportTypeEnum.EMPLOYEE_WISE) {
      condition.userMasterID = {
        [Sequelize.Op.in]: userMasterID,
      };
    }

    while (hasMoreData) {
      // Fetch employee chunk with LIMIT/OFFSET
      const employeeChunk = await UserMaster.findAll({
        where: condition,
        attributes: ['userMasterID', 'displayName', 'userNumber'],
        include: includeModel,
        order: orderByFields,
        limit: chunkSize,
        offset: offset,
      });

      // Check if we have more data
      if (employeeChunk.length === 0) {
        hasMoreData = false;
        break;
      }

      // unverified ids
      const unVerifiedUserIds = employeeChunk
        .filter(
          ({ hrLeaveMonthlyTrans = [] }) => hrLeaveMonthlyTrans.length === 0,
        )
        .map(({ userMasterID }) => userMasterID);

      const weekoffHolidayMap = new Map();

      if (unVerifiedUserIds.length) {
        const allWhData = await weekoffHolidayTran.findAll({
          raw: true,
          where: {
            userMasterID: { [Sequelize.Op.in]: unVerifiedUserIds },
            date: { [Sequelize.Op.between]: [startDate, endDate] },
            [Sequelize.Op.or]: [
              { optionalHoliday: false },
              { optionalHoliday: { [Sequelize.Op.is]: null } },
            ],
          },
          attributes: [
            'userMasterID',
            'date',
            'value',
            'WHDayType',
            'tableName',
            'yearMonth',
          ],
        });

        for (const wh of allWhData) {
          const userKey = +wh.userMasterID;
          const dateKey = wh.date;

          if (!weekoffHolidayMap.has(userKey)) {
            weekoffHolidayMap.set(userKey, new Map());
          }

          const dateMap = weekoffHolidayMap.get(userKey);

          if (!dateMap.has(dateKey)) {
            dateMap.set(dateKey, new Map());
          }

          const tableMap = dateMap.get(dateKey);

          tableMap.set(wh.tableName, wh.value);
        }
      }

      if (reportType == absenteeismReportTypeEnum.EMPLOYEE_WISE) {
        totalObject = employeeWiseChunkProcess(
          employeeChunk,
          weekoffHolidayMap,
          startDate,
          endDate,
          totalObject,
          worksheet,
        );
      } else {
        contractorWiseMap = contractorWiseChunkPrcess(
          employeeChunk,
          weekoffHolidayMap,
          startDate,
          endDate,
          contractorWiseMap,
        );
      }

      // Move to next chunk
      offset += chunkSize;

      // If we got less than chunkSize records, we're done
      if (employeeChunk.length < chunkSize) {
        hasMoreData = false;
      }
    }

    if (reportType == absenteeismReportTypeEnum.EMPLOYEE_WISE) {
      const percentage = getLossPercentage(
        totalObject.totalMandays || 0,
        totalObject.loss_Mandays || 0,
      );

      const row = [
        'Total',
        '',
        '',
        '',
        '',
        '',
        '',
        '',
        '',
        totalObject.totalMandays || 0,
        totalObject.actualWorked || 0,
        totalObject.loss_Mandays || 0,
        percentage,
      ];

      addFinalRow(worksheet, row, 9, 'Total');
    } else {
      const finalObject = {
        name: 'Total',
        employee: 0,
        mandays: 0,
        actualWorked: 0,
        lossMandays: 0,
        lossPercent: 0,
        avg: 0,
      };

      for (const [key, obj] of contractorWiseMap.entries()) {
        finalObject.employee += obj.employee || 0;
        finalObject.mandays += obj.mandays || 0;
        finalObject.actualWorked += obj.actualWorked || 0;
        finalObject.lossMandays += obj.lossMandays || 0;
        obj.lossPercent = getLossPercentage(obj.mandays, obj.lossMandays);
        finalObject.avg = 0;

        const row = Object.values(obj);
        const currentRow = worksheet.addRow(row);
        currentRow.commit();
      }

      const percentage = getLossPercentage(
        finalObject.mandays,
        finalObject.lossMandays,
      );
      finalObject.lossPercent = percentage;

      const row = Object.values(finalObject);

      addFinalRow(worksheet, row, 1, 'Total');
    }

    // Commit workbook and end response
    await workbook.commit();
  } catch (error) {
    next(error);
  }
};

exports.manpowerRequisitionRequestReport = async (req, res, next) => {
  try {
    const {
      limit,
      page,
      search,
      companyMasterID,
      departmentID,
      designationID,
      devisionID,
      workingAreaID,
      branchID,
      isExport,
      status,
      sortField,
    } = req.body;

    const condition = {
      status: [0, 1],
      companyMasterID: companyMasterID,
    };

    if (search) {
      condition[Sequelize.Op.or] = [
        {
          jobTitle: {
            [Sequelize.Op.iLike]: `%${search}%`,
          },
        },
      ];
    }

    if (departmentID) condition.departmentID = departmentID;
    if (branchID) condition.branchID = branchID;
    if (designationID) condition.designationID = designationID;
    if (devisionID) condition.devisionID = devisionID;
    if (workingAreaID) condition.workingAreaID = workingAreaID;
    if (status == 3 || status == 4) {
      condition.authorizationStatus = status;
    } else {
      condition.authorizationStatus = [0, 1, 2];
    }

    const paginationQuery = {};
    if (!isExport && page && limit) {
      paginationQuery.offset = (page - 1) * limit;
      paginationQuery.limit = limit;
    }

    let order = [];

    if (sortField === orderByEmployeeMasterFields.EMPLOYEECODE) {
      const employeeCodeSubquery = `(
    SELECT ejd."employeeCode"
    FROM "employeeJoiningDetails" ejd
    WHERE ejd."userMasterID" = "manPowerRequisitionRequest"."userMasterID"
    LIMIT 1
  )`;

      order = [
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} IS NULL OR ${employeeCodeSubquery} = '' THEN 0 ELSE 1 END`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} ~ '^[0-9]+$' THEN 0 ELSE 1 END`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} ~ '^[0-9]+$' THEN (${employeeCodeSubquery})::int END`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `substring(${employeeCodeSubquery} FROM '^[^0-9]+')`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} ~ '[0-9]+' THEN substring(${employeeCodeSubquery} FROM '[0-9]+')::int END`,
          ),
          'ASC',
        ],
        [Sequelize.literal(employeeCodeSubquery), 'ASC'],
        [
          Sequelize.literal(
            `(SELECT um."displayName" FROM "userMasters" um WHERE um."userMasterID" = "manPowerRequisitionRequest"."userMasterID" LIMIT 1)`,
          ),
          'ASC',
        ],
        ['createdAt', 'DESC'],
      ];
    } else if (sortField == orderByEmployeeMasterFields.EMPLOYEENAME) {
      order = [
        [
          Sequelize.literal(
            `(SELECT um."displayName" FROM "userMasters" um WHERE um."userMasterID" = "manPowerRequisitionRequest"."userMasterID" LIMIT 1)`,
          ),
          'ASC',
        ],
        ['createdAt', 'DESC'],
      ];
    } else {
      order = [
        ['createdAt', 'DESC'],
        [
          Sequelize.literal(
            `(SELECT um."displayName" FROM "userMasters" um WHERE um."userMasterID" = "manPowerRequisitionRequest"."userMasterID" LIMIT 1)`,
          ),
          'ASC',
        ],
      ];
    }

    const { rows: manPowerRequisitionRequestData, count } =
      await ManPowerRequisitionRequest.findAndCountAll({
        where: condition,
        distinct: true,
        ...paginationQuery,
        order: order,
        include: [
          {
            model: UserMaster,
            as: 'createdBy',
            attributes: ['displayName'],
          },
          {
            model: UserMaster,
            as: 'updatedBy',
            attributes: ['displayName'],
          },
          {
            model: companyMaster,
            attributes: ['companyName'],
          },
          {
            model: Department,
            attributes: ['departmentName'],
          },
          {
            model: Designation,
            attributes: ['designationName'],
          },
          { model: BranchMaster, attributes: ['branchName'] },
          {
            model: Division,
            attributes: ['divisionName'],
          },
          {
            model: WorkingArea,
            attributes: ['workingAreaName'],
          },
          {
            model: ManPowerRequisitionAuthorization,
            as: 'manPowerAuth',
            attributes: ['authStatus'],
            include: [
              {
                model: UserMaster,
                attributes: ['displayName'],
              },
            ],
          },
          {
            model: StateMaster,
            attributes: ['stateName'],
          },
          {
            model: UserMaster,
            as: 'reportToEmp',
            attributes: ['displayName'],
          },
          {
            model: UserMaster,
            as: 'replacedEmp',
            attributes: ['displayName'],
          },
          {
            model: UserMaster,
            as: 'requestedBy',
            attributes: ['displayName'],
          },
          {
            model: AuthorizationCriteriaMaster,
            attributes: ['AuthorizationCriteria'],
          },
        ],
      });

    if (isExport) {
      // ── 1. Fetch city names ──────────────────────────────────────────────
      const cityIds = [
        ...new Set(
          manPowerRequisitionRequestData.flatMap(
            (item) => item.workingCity || [],
          ),
        ),
      ];
      const cities = await CityMaster.findAll({
        where: { cityMasterID: cityIds },
        attributes: ['cityMasterID', 'cityName'],
      });
      const cityMap = {};
      cities.forEach((city) => {
        cityMap[city.cityMasterID] = city.cityName;
      });

      // ── 2. Build ExcelJS workbook ────────────────────────────────────────
      const ExcelJS = require('exceljs');
      const workbook = new ExcelJS.Workbook();
      const worksheet = workbook.addWorksheet('ManPowerRequisitionRequest');

      // ── 3. Column definitions ────────────────────────────────────────────
      const columns = [
        { header: 'Company Name', key: 'companyName', width: 25 },
        {
          header: 'Authorization Status',
          key: 'authorizationStatus',
          width: 20,
        },
        { header: 'Job Title', key: 'jobTitle', width: 25 },
        { header: 'Branch Name', key: 'branchName', width: 20 },
        { header: 'Department Name', key: 'departmentName', width: 20 },
        { header: 'Designation Name', key: 'designationName', width: 20 },
        { header: 'Division Name', key: 'divisionName', width: 20 },
        { header: 'Working Area', key: 'workingArea', width: 20 },
        { header: 'Working State', key: 'workingState', width: 20 },
        { header: 'Working Cities', key: 'workingCities', width: 25 },
        { header: 'Type Of Requirement', key: 'typeOfRequirement', width: 20 },
        { header: 'Previous Employee', key: 'previousEmployee', width: 20 },
        {
          header: 'Previous Employee CTC',
          key: 'previousEmployeeCTC',
          width: 20,
        },
        { header: 'Employment Type', key: 'employmentType', width: 18 },
        { header: 'Travel Required', key: 'travelRequired', width: 15 },
        { header: 'CTC From', key: 'ctcFrom', width: 12 },
        { header: 'CTC To', key: 'ctcTo', width: 12 },
        { header: 'Experience From', key: 'experienceFrom', width: 15 },
        { header: 'Experience To', key: 'experienceTo', width: 15 },
        { header: 'Report To', key: 'reportTo', width: 20 },
        { header: 'Requested By', key: 'requestedBy', width: 20 },
        { header: 'Auth Criteria', key: 'authCriteria', width: 25 },
        { header: 'Authorizer', key: 'authorizer', width: 25 }, // multi-row column
        { header: 'Auth Status', key: 'authStatus', width: 15 }, // per authorizer
        { header: 'Grade', key: 'grade', width: 12 },
        { header: 'Remarks', key: 'remarks', width: 25 },
        { header: 'Created By', key: 'createdBy', width: 20 },
        { header: 'Created At', key: 'createdAt', width: 18 },
      ];

      worksheet.columns = columns;

      // ── 4. Style header row ──────────────────────────────────────────────
      const headerRow = worksheet.getRow(1);
      headerRow.eachCell((cell) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = {
          type: 'pattern',
          pattern: 'solid',
          fgColor: { argb: 'FF4472C4' },
        };
        cell.alignment = {
          vertical: 'middle',
          horizontal: 'center',
          wrapText: true,
        };
        cell.border = {
          top: { style: 'thin' },
          left: { style: 'thin' },
          bottom: { style: 'thin' },
          right: { style: 'thin' },
        };
      });
      headerRow.height = 30;

      // ── 5. Write data rows ───────────────────────────────────────────────
      let currentRowIndex = 2; // rows are 1-based; row 1 is header

      for (const e of manPowerRequisitionRequestData) {
        // Authorizers list — each authorizer becomes its own Excel row
        const authorizers = (e.manPowerAuth || []).map((auth) => ({
          name: auth.userMaster?.displayName || '',
          status:
            auth.authStatus == 0
              ? 'Rejected'
              : auth.authStatus == 2
                ? 'Pending'
                : 'Approved',
        }));

        // At least one row per record even if no authorizers
        const rowCount = Math.max(authorizers.length, 1);

        // Auth criteria from requestedBy's authorizationDetails
        const authCriteria =
          e.AuthorizationCriteriaMaster?.AuthorizationCriteria || '';

        // Common fields shared across all merged rows for this record
        const commonFields = {
          companyName: e.companyMaster?.companyName || '',
          authorizationStatus:
            e.authorizationStatus == 3
              ? 'Approved'
              : e.authorizationStatus == 4
                ? 'Rejected'
                : 'Pending',
          jobTitle: e.jobTitle || '',
          branchName: e.branchMaster?.branchName || '',
          departmentName: e.department?.departmentName || '',
          designationName: e.designation?.designationName || '',
          divisionName: e.division?.divisionName || '',
          workingArea: e.workingArea?.workingAreaName || '',
          workingState: e.stateMaster?.stateName || '',
          workingCities: (e.workingCity || [])
            .map((id) => cityMap[id])
            .filter(Boolean)
            .join(', '),
          typeOfRequirement:
            e.typeOfRequirement == 'replacement' ? 'Replacement' : 'New Hire',
          previousEmployee: e.replacedEmp?.displayName || '',
          previousEmployeeCTC: e.previousEmpCTC || '',
          employmentType: e.employmentType || '',
          travelRequired: e.isTravelRequired ? 'Yes' : 'No',
          ctcFrom: e.ctcFrom || '',
          ctcTo: e.ctcTo || '',
          experienceFrom: e.expFrom || '',
          experienceTo: e.expTo || '',
          reportTo: e.reportToEmp?.displayName || '',
          requestedBy: e.requestedBy?.displayName || '',
          authCriteria: authCriteria,
          grade: e.Grade || '',
          remarks: e.remarks || '',
          createdBy: e.createdBy?.displayName || '',
          createdAt: e.createdAt
            ? moment(e.createdAt).format('DD-MM-YYYY')
            : '',
        };

        // Write one Excel row per authorizer (or one blank-authorizer row)
        for (let i = 0; i < rowCount; i++) {
          const auth = authorizers[i] || { name: '', status: '' };
          const rowData = {
            ...commonFields,
            authorizer: auth.name,
            authStatus: auth.status,
          };
          const excelRow = worksheet.addRow(rowData);
          excelRow.height = 20;

          // Border + alignment for every cell in this row
          excelRow.eachCell({ includeEmpty: true }, (cell) => {
            cell.border = {
              top: { style: 'thin' },
              left: { style: 'thin' },
              bottom: { style: 'thin' },
              right: { style: 'thin' },
            };
            cell.alignment = { vertical: 'middle', wrapText: true };
          });
        }

        // ── 6. Merge common-field cells across the authorizer rows ─────────
        if (rowCount > 1) {
          const mergeStart = currentRowIndex;
          const mergeEnd = currentRowIndex + rowCount - 1;

          // All columns except 'authorizer' (col 23) and 'authStatus' (col 24)
          const columnsToMerge = [
            1, // companyName
            2, // authorizationStatus
            3, // jobTitle
            4, // branchName
            5, // departmentName
            6, // designationName
            7, // divisionName
            8, // workingArea
            9, // workingState
            10, // workingCities
            11, // typeOfRequirement
            12, // previousEmployee
            13, // previousEmployeeCTC
            14, // employmentType
            15, // travelRequired
            16, // ctcFrom
            17, // ctcTo
            18, // experienceFrom
            19, // experienceTo
            20, // reportTo
            21, // requestedBy
            22, // authCriteria
            25, // grade
            26, // remarks
            27, // createdBy
            28, // createdAt
          ];

          for (const colNum of columnsToMerge) {
            worksheet.mergeCells(mergeStart, colNum, mergeEnd, colNum);
            // Re-apply alignment on the merged cell (top-left cell of merge)
            const mergedCell = worksheet.getCell(mergeStart, colNum);
            mergedCell.alignment = {
              vertical: 'middle',
              horizontal: 'left',
              wrapText: true,
            };
          }
        }

        currentRowIndex += rowCount;
      }

      // ── 7. Stream response ───────────────────────────────────────────────
      res.setHeader(
        'Content-Type',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      );
      res.setHeader(
        'Content-Disposition',
        'attachment; filename="ManPowerRequisitionRequest.xlsx"',
      );

      await workbook.xlsx.write(res);
      return res.end();
    }

    return res.status(200).json({
      status: 200,
      data: manPowerRequisitionRequestData,
      totalcount: count,
    });
  } catch (error) {
    next(error);
  }
};

exports.loanOutstandingReport = async (req, res, next) => {
  try {
    const {
      companyMasterID,
      date,
      branchMasterID,
      userMasterID,
      limit,
      page,
      exportData,
      sortField,
    } = req.body;

    if (!companyMasterID || !userMasterID || !date) {
      return res.status(200).json({
        status: 400,
        message: 'Company, User and Outstanding Date are required!',
      });
    }

    if (new Date(date) > new Date()) {
      return res.status(200).json({
        status: 400,
        message: 'Date can not be greater than today date!',
      });
    }

    const paginationQuery = {};
    const condition = {
      status: 1,
      loanstatus: 1,
      givenDate: {
        [Sequelize.Op.lte]: date,
      },
    };

    condition.companyMasterID = companyMasterID;

    if (!exportData && page && limit) {
      paginationQuery.offset = (page - 1) * limit;
      paginationQuery.limit = +limit;
    }

    if (userMasterID && userMasterID.length > 0) {
      condition.userMasterID = {
        [Sequelize.Op.in]: userMasterID,
      };
    }

    const filterDate = asiaKolkataDateTime(new Date()).slice(0, 10);
    const userAccessCondition = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: !companyMasterID,
    });
    let order = [];

    if (sortField === orderByEmployeeMasterFields.EMPLOYEECODE) {
      const employeeCodeSubquery = `(
    SELECT ejd."employeeCode"
    FROM "employeeJoiningDetails" ejd
    WHERE ejd."userMasterID" = "loanMaster"."userMasterID"
    LIMIT 1
  )`;

      order = [
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} IS NULL OR ${employeeCodeSubquery} = '' THEN 0 ELSE 1 END`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} ~ '^[0-9]+$' THEN 0 ELSE 1 END`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} ~ '^[0-9]+$' THEN (${employeeCodeSubquery})::int END`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `substring(${employeeCodeSubquery} FROM '^[^0-9]+')`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} ~ '[0-9]+' THEN substring(${employeeCodeSubquery} FROM '[0-9]+')::int END`,
          ),
          'ASC',
        ],
        [Sequelize.literal(employeeCodeSubquery), 'ASC'],
        [
          Sequelize.literal(
            `(SELECT um."displayName" FROM "userMasters" um WHERE um."userMasterID" = "loanMaster"."userMasterID" LIMIT 1)`,
          ),
          'ASC',
        ],
        ['createdAt', 'DESC'],
      ];
    } else {
      // Default: sort by employee name, then date
      order = [
        [
          Sequelize.literal(
            `(SELECT um."displayName" FROM "userMasters" um WHERE um."userMasterID" = "loanMaster"."userMasterID" LIMIT 1)`,
          ),
          'ASC',
        ],
        ['startMonth', 'DESC'],
      ];
    }

    // Pre-filter loans where remaining amount on specified date > 0
    const remainingAmountAsOnDate = Sequelize.literal(`
(
  "loanMaster"."LoanAmount"

  - COALESCE(
      (
        SELECT SUM(lt."EMIAmount")
        FROM "loanTransactions" lt
        INNER JOIN "hrSalaryTrasactions" hst
          ON hst."userSalaryTranID" = lt."RefrenceId"
        WHERE lt."LoanID" = "loanMaster"."LoanID"
          AND DATE(hst."createdAt") <= '${date}'
      ),
      0
    )

  - COALESCE(
      (
        SELECT SUM(la."Amount")
        FROM "loanAdvances" la
        WHERE la."LoanID" = "loanMaster"."LoanID"
          AND DATE(la."givenDate") <= '${date}'
      ),
      0
    )
)
`);

    const whereCondition = {
      ...condition,
      [Sequelize.Op.and]: [
        Sequelize.where(remainingAmountAsOnDate, Sequelize.Op.gt, 0),
      ],
    };

    const { rows: data, count } = await LoanMaster.findAndCountAll({
      where: whereCondition,
      attributes: {
        include: [[remainingAmountAsOnDate, 'remainingAmountAsOnDate']],
      },
      ...paginationQuery,
      distinct: true,
      order,
      include: [
        {
          model: LoanTransaction,
          include: [{ model: HrSalaryTransaction }],
        },
        {
          model: LoanAdvance,
        },
        {
          required: true,
          model: UserMaster,
          where: {
            status: 1,
            companyMasterId: companyMasterID,
            ...userAccessCondition.where,
          },
          attributes: ['displayName', 'userNumber'],
          include: [
            ...userAccessCondition.includeModels,
            {
              required: false,
              model: EmployeeDesignation,
              where: {
                status: 1,
                applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },

              attributes: ['designationID'],
              include: [
                {
                  model: Designation,
                  as: 'designation',
                  attributes: ['designationName'],
                },
              ],
            },
            {
              required: false,
              model: EmployeeDepartment,
              where: {
                status: 1,
                applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },

              attributes: ['departmentID'],
              include: [
                {
                  model: Department,
                  as: 'department',
                  attributes: ['departmentName'],
                },
              ],
            },
            {
              required: false,
              model: EmployeeBranch,
              where: {
                status: 1,
                applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },
              attributes: ['branchID'],
              include: [
                {
                  model: BranchMaster,
                  as: 'branchMaster',
                  attributes: ['branchName'],
                },
              ],
            },
            {
              model: EmployeeJoiningDetails,
              attributes: ['employeeCode'],
            },
            {
              required: false,
              model: EmployeeDivision,
              where: {
                status: 1,
                startDate: { [Sequelize.Op.lte]: filterDate },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: filterDate } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },

              attributes: ['divisionId', 'startDate'],
              include: [
                {
                  model: Division,
                  attributes: ['divisionName'],
                },
              ],
            },
            {
              required: false,
              model: EmployeeWorkingArea,
              where: {
                status: 1,
                startDate: { [Sequelize.Op.lte]: filterDate },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: filterDate } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },
              attributes: ['workingAreaId', 'startDate'],
              include: [
                {
                  model: WorkingArea,
                  attributes: ['workingAreaName'],
                },
              ],
            },
          ],
        },
      ],
    });

    const formattedDate = moment(date).format('DD-MM-YYYY');

    const finalData = data.map((e) => {
      let remainingAmount = Number(e.LoanAmount || 0);
      let paidAmount = 0;
      let paidEmi = 0;

      let remainingAmount_asOnDate = Number(e.LoanAmount || 0);
      let paidAmount_asOnDate = 0;
      let paidEmi_asOnDate = 0;

      const loanAdvances = e.loanAdvances || [];
      const loanTransactions = e.loanTransactions || [];

      const advance = loanAdvances.reduce(
        (acc, obj) => acc + Number(obj.Amount || 0),
        0,
      );

      const advance_asOnDate = loanAdvances
        .filter((advance) =>
          moment(advance.givenDate).isSameOrBefore(date, 'day'),
        )
        .reduce((acc, obj) => acc + Number(obj.Amount || 0), 0);

      loanTransactions.forEach((transaction) => {
        if (transaction.RefrenceId) {
          const emiAmount = Number(transaction.EMIAmount || 0);

          remainingAmount -= emiAmount;
          paidAmount += emiAmount;
          paidEmi++;

          const salaryCalculatedDate = transaction.hrSalaryTrasaction?.createdAt
            ? moment(transaction.hrSalaryTrasaction.createdAt).format(
                'YYYY-MM-DD',
              )
            : null;

          if (
            salaryCalculatedDate &&
            moment(date).isSameOrAfter(salaryCalculatedDate, 'day')
          ) {
            remainingAmount_asOnDate -= emiAmount;
            paidAmount_asOnDate += emiAmount;
            paidEmi_asOnDate++;
          }
        }
      });

      const employeeInfo = parseEmployeeInfo(e.userMaster);

      return {
        'Employee Code': employeeInfo?.employeeCode || '',
        Name: e.userMaster?.displayName || '',
        Number: e.userMaster?.userNumber || '',
        Branch: employeeInfo?.branch || '',
        Department: employeeInfo?.department || '',
        Designation: employeeInfo?.designation || '',
        Division: employeeInfo?.division || '',
        'Working Area': employeeInfo?.workingArea || '',

        'Loan Amount': Number(e.LoanAmount || 0),

        'Loan Advance': advance,

        'Remaining Amount': remainingAmount - advance,

        'Paid Amount': paidAmount + advance,

        'Paid EMI': paidEmi,

        [`Remaining Amount (${formattedDate})`]:
          remainingAmount_asOnDate - advance_asOnDate,

        [`Paid Amount (${formattedDate})`]:
          paidAmount_asOnDate + advance_asOnDate,

        [`Paid EMI (${formattedDate})`]: paidEmi_asOnDate,

        'Loan Remarks': e.LoanRemark || '',

        'Emi Months': e.EMIMonths || '',

        'Start Month': e.startMonth
          ? `${
              month_dict[String(e.startMonth).slice(4, 6)]
            } - ${String(e.startMonth).slice(0, 4)}`
          : '',
      };
    });

    if (exportData) {
      return await generateExcel(
        finalData,
        'loan-Outstanding-Report',
        'xlsx',
        res,
      );
    }

    return res.status(200).json({
      status: 200,
      data: finalData,
      totalcount: count,
    });
  } catch (err) {
    next(err);
  }
};

exports.leaveEncashmentReport = async (req, res, next) => {
  try {
    const { userMasterID, isExport, sortField, month, limit, page } = req.body;

    if (userMasterID?.length == 0 || !month) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: 'UserMasterID and Month are required!',
      });
    }

    const filterDate = asiaKolkataDateTime(new Date()).slice(0, 10);

    const userAccessCondition = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: false,
    });
    let order = [];

    const paginationQuery = {};
    if (!isExport && page && limit) {
      paginationQuery.offset = (page - 1) * limit;
      paginationQuery.limit = +limit;
    }

    if (sortField === orderByEmployeeMasterFields.EMPLOYEECODE) {
      const employeeCodeSubquery = `(
    SELECT ejd."employeeCode"
    FROM "employeeJoiningDetails" ejd
    WHERE ejd."userMasterID" = "hrSalaryTrasaction"."userMasterID"
    LIMIT 1
  )`;

      order = [
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} IS NULL OR ${employeeCodeSubquery} = '' THEN 0 ELSE 1 END`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} ~ '^[0-9]+$' THEN 0 ELSE 1 END`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} ~ '^[0-9]+$' THEN (${employeeCodeSubquery})::int END`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `substring(${employeeCodeSubquery} FROM '^[^0-9]+')`,
          ),
          'ASC',
        ],
        [
          Sequelize.literal(
            `CASE WHEN ${employeeCodeSubquery} ~ '[0-9]+' THEN substring(${employeeCodeSubquery} FROM '[0-9]+')::int END`,
          ),
          'ASC',
        ],
        [Sequelize.literal(employeeCodeSubquery), 'ASC'],
        [
          Sequelize.literal(
            `(SELECT um."displayName" FROM "userMasters" um WHERE um."userMasterID" = "hrSalaryTrasaction"."userMasterID" LIMIT 1)`,
          ),
          'ASC',
        ],
        ['createdAt', 'DESC'],
      ];
    } else {
      // Default: sort by employee name, then date
      order = [
        [
          Sequelize.literal(
            `(SELECT um."displayName" FROM "userMasters" um WHERE um."userMasterID" = "hrSalaryTrasaction"."userMasterID" LIMIT 1)`,
          ),
          'ASC',
        ],
      ];
    }

    const monthForDB = month.split('-').join('');

    const salaryData = await HrSalaryTransaction.findAndCountAll({
      distinct: true,
      order,
      ...paginationQuery,
      where: {
        userMasterID: userMasterID,
        EmployeeSalaryAmount: {
          [Sequelize.Op.gt]: 0,
        },
        salaryYYYYMM: monthForDB,
      },
      attributes: [
        'EmployeeSalaryAmount',
        'salaryMasterID',
        'salaryYYYYMM',
        'userMasterID',
      ],
      include: [
        {
          model: HrSalaryMaster,
          required: true,
          as: 'HSM',
          attributes: ['salaryMasterID', 'gradeSalaryStructureID'],
          include: [
            {
              required: true,
              model: GradeSalaryStructure,
              as: 'GSS',
              attributes: ['salaryFieldID', 'gradeSalaryStructureID'],
              include: [
                {
                  required: true,
                  model: HRSalaryFields,
                  as: 'HSF',
                  where: {
                    payheadMasterId: 67,
                  },
                  attributes: ['payheadMasterId'],
                },
              ],
            },
          ],
        },
        {
          required: true,
          model: UserMaster,
          where: {
            status: [0, 1],
          },
          attributes: ['displayName', 'userNumber', 'companyMasterId'],
          include: [
            ...userAccessCondition.includeModels,
            {
              required: false,
              model: EmployeeDesignation,
              where: {
                status: 1,
                applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },

              attributes: ['designationID'],
              include: [
                {
                  model: Designation,
                  as: 'designation',
                  attributes: ['designationName'],
                },
              ],
            },
            {
              model: companyMaster,
              attributes: ['companyName'],
            },
            {
              required: false,
              model: EmployeeDepartment,
              where: {
                status: 1,
                applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },

              attributes: ['departmentID'],
              include: [
                {
                  model: Department,
                  as: 'department',
                  attributes: ['departmentName'],
                },
              ],
            },
            {
              required: false,
              model: EmployeeBranch,
              where: {
                status: 1,
                applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },
              attributes: ['branchID'],
              include: [
                {
                  model: BranchMaster,
                  as: 'branchMaster',
                  attributes: ['branchName'],
                },
              ],
            },
            {
              model: EmployeeJoiningDetails,
              attributes: ['employeeCode'],
            },
            {
              required: false,
              model: EmployeeDivision,
              where: {
                status: 1,
                startDate: { [Sequelize.Op.lte]: filterDate },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: filterDate } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },

              attributes: ['divisionId', 'startDate'],
              include: [
                {
                  model: Division,
                  attributes: ['divisionName'],
                },
              ],
            },
            {
              required: false,
              model: EmployeeWorkingArea,
              where: {
                status: 1,
                startDate: { [Sequelize.Op.lte]: filterDate },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: filterDate } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },
              attributes: ['workingAreaId', 'startDate'],
              include: [
                {
                  model: WorkingArea,
                  attributes: ['workingAreaName'],
                },
              ],
            },
          ],
        },
        {
          model: LeaveEncashment,
          attributes: ['days'],
        },
      ],
    });
    const finalData = salaryData?.rows?.map((e) => {
      const employeeInfo = parseEmployeeInfo(e.userMaster);

      let totalLeave = 0;
      for (const leave of e.leaveEncashments) {
        totalLeave += leave?.days;
      }
      const monthindex = month.split('-')[1];
      const monthName = norMonths[Number(monthindex) - 1];
      return {
        Company: e.userMaster?.companyMaster?.companyName,
        'Employee Code': employeeInfo?.employeeCode || '',
        Name: e.userMaster?.displayName || '',
        Number: e.userMaster?.userNumber || '',
        Branch: employeeInfo?.branch || '',
        Department: employeeInfo?.department || '',
        Designation: employeeInfo?.designation || '',
        Division: employeeInfo?.division || '',
        'Working Area': employeeInfo?.workingArea || '',
        Month: monthName || '',
        'Encashment Amount': e.EmployeeSalaryAmount || '',
        'Encashed Leave': totalLeave,
      };
    });

    if (isExport) {
      return await generateExcel(
        finalData,
        'leave-encashment -Report',
        'xlsx',
        res,
      );
    }

    return res.status(200).json({
      status: 200,
      data: finalData || [],
      totalcount: salaryData.count,
    });
  } catch (error) {
    next(error);
  }
};

exports.genderWiseSalarySummary = async (req, res, next) => {
  try {
    const {
      companyMasterID,
      branchMasterID,
      departmentID,
      designationID,
      divisionID,
      workingAreaID,
      date,
      month,
    } = req.body;

    if (!companyMasterID || !month) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: message.usermessage.requiredMessage(
          'companyMasterID and month',
        ),
      });
    }

    const currentMonth = moment().format('YYYYMM');

    if (+month > +currentMonth) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: 'You cannot retrieve salary data for a future month.',
      });
    }

    const userAccessCondition = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: false,
    });

    const filterDate = moment().format('YYYY-MM-DD');

    const includeModels = [
      {
        required: true,
        model: HrSalaryTransaction,
        where: {
          salaryYYYYMM: month,
        },
        attributes: ['EmployeeSalaryAmount'],
        include: [
          {
            required: true,
            model: HrSalaryMaster,
            required: true,
            as: 'HSM',
            attributes: ['gradeSalaryStructureID'],
            include: [
              {
                required: true,
                model: GradeSalaryStructure,
                as: 'GSS',
                attributes: ['gradeSalaryStructureID'],
                include: [
                  {
                    required: true,
                    model: HRSalaryFields,
                    as: 'HSF',
                    attributes: ['payheadMasterId'],
                  },
                ],
              },
            ],
          },
        ],
      },
      {
        required: true,
        model: hrLeaveMonthlyTrans,
        where: {
          AttnYearMon: month,
        },
        include: [
          {
            model: HrLeaveTypes,
            where: {
              LeaveID: HrLeaveTypesIds.PRESENT,
            },
            attributes: [],
          },
        ],
        attributes: ['AttnVal'],
      },
    ];

    if (Array.isArray(branchMasterID) && branchMasterID.length) {
      includeModels.push({
        required: true,
        model: EmployeeBranch,
        where: {
          branchID: {
            [Sequelize.Op.in]: branchMasterID,
          },
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        attributes: [],
      });
    }

    if (Array.isArray(departmentID) && departmentID.length) {
      includeModels.push({
        required: true,
        model: EmployeeDepartment,
        where: {
          departmentID: {
            [Sequelize.Op.in]: departmentID,
          },
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        attributes: [],
      });
    }

    if (Array.isArray(designationID) && designationID.length) {
      includeModels.push({
        required: true,
        model: EmployeeDesignation,
        where: {
          designationID: {
            [Sequelize.Op.in]: designationID,
          },
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        attributes: [],
      });
    }

    if (divisionID) {
      includeModels.push({
        required: true,
        model: EmployeeDivision,
        where: {
          divisionId: divisionID,
          status: 1,
          startDate: { [Sequelize.Op.lte]: new Date(filterDate) },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        attributes: [],
      });
    }

    if (workingAreaID) {
      includeModels.push({
        required: true,
        model: EmployeeWorkingArea,
        where: {
          workingAreaId: workingAreaID,
          status: 1,
          startDate: { [Sequelize.Op.lte]: new Date(filterDate) },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        attributes: [],
      });
    }

    const userData = await UserMaster.findAll({
      where: {
        companyMasterId: companyMasterID,
        ...userAccessCondition.where,
      },
      attributes: ['userMasterID', 'gender'],
      include: [...userAccessCondition.includeModels, ...includeModels],
    });

    const finalMap = {
      male: {
        totalWorker: 0,
        presentDays: 0,
        basicWages: 0,
        grossWages: 0,
      },
      female: {
        totalWorker: 0,
        presentDays: 0,
        basicWages: 0,
        grossWages: 0,
      },
      total: {
        totalWorker: 0,
        presentDays: 0,
        basicWages: 0,
        grossWages: 0,
      },
      pfCount: 0,
      esicCount: 0,
      date: date ? moment(date).format('DD-MM-YYYY') : '',
      monthName: moment(month, 'YYYYMM').format('MMMM-YYYY').toUpperCase(),
    };

    const includePayhead = [
      payheadMasterIdsMapping.GROSS,
      payheadMasterIdsMapping.BASIC,
      payheadMasterIdsMapping.PF,
      payheadMasterIdsMapping.EMPLOYEE_ESIC,
    ];

    for (const user of userData) {
      const salaryData = user.hrSalaryTrasactions || [];

      // Create Payhead -> Salary Transaction map
      const salaryMap = new Map();

      for (const salary of salaryData) {
        const payheadId = salary.HSM?.GSS?.HSF?.payheadMasterId;

        if (payheadId && includePayhead.includes(+payheadId)) {
          salaryMap.set(+payheadId, salary);
        }
      }

      const gender =
        user.gender?.toLowerCase() === 'female' ? 'female' : 'male';

      const presentDays = +user.hrLeaveMonthlyTrans?.[0]?.AttnVal || 0;

      const basicSalary =
        +salaryMap.get(payheadMasterIdsMapping.BASIC)?.EmployeeSalaryAmount ||
        0;

      const grossSalary =
        +salaryMap.get(payheadMasterIdsMapping.GROSS)?.EmployeeSalaryAmount ||
        0;

      // Gender wise
      finalMap[gender].totalWorker++;
      finalMap[gender].presentDays += presentDays;
      finalMap[gender].basicWages += basicSalary;
      finalMap[gender].grossWages += grossSalary;

      // Total
      finalMap.total.totalWorker++;
      finalMap.total.presentDays += presentDays;
      finalMap.total.basicWages += basicSalary;
      finalMap.total.grossWages += grossSalary;

      // PF Count
      if (salaryMap.has(payheadMasterIdsMapping.PF)) {
        finalMap.pfCount++;
      }

      // ESIC Count
      if (salaryMap.has(payheadMasterIdsMapping.EMPLOYEE_ESIC)) {
        finalMap.esicCount++;
      }
    }

    const companyData = await companyMaster.findOne({
      where: {
        companyMasterID,
      },
    });

    finalMap.companyName = companyData?.companyName || '';

    console.log(finalMap);

    const filePath = getHTMLTemplate('genderWiseSalarySummary', 'html');
    const file = await readHTMLFile(filePath);
    const template = Handlebars.compile(file);
    const html = template(finalMap);

    const browser = await puppeteer.launch({
      headless: 'new',
      args: ['--no-sandbox'],
    });
    const page = await browser.newPage();

    // Set the HTML content of the page
    await page.setContent(html);

    // Generate PDF
    const pdfBuffer = await page.pdf({
      format: 'A4', // Page format (A4 in this case)
      landscape: true,
      printBackground: true, // print background
      margin: { top: '20px', bottom: '20px' },
    });
    await browser.close();

    const base64path = Buffer.from(pdfBuffer).toString('base64');

    return res.status(statusCodes.OK).json({
      status: statusCodes.OK,
      data: base64path,
    });
  } catch (error) {
    next(error);
  }
};

exports.payheadWiseSalaryReport = async (req, res, next) => {
  try {
    const {
      companyMasterID,
      month,
      payheadMasterIDs = [],
      exportData = false,
    } = req.body;

    if (
      !companyMasterID ||
      !month ||
      !Array.isArray(payheadMasterIDs) ||
      payheadMasterIDs.length === 0
    ) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: message.usermessage.requiredMessage(
          'companyMasterID, month and payheadMasterIDs',
        ),
      });
    }

    /*
     * Validate and normalize month.
     * Supported values:
     * 202606
     * 2026-06
     */
    const normalizedMonth = moment(String(month), ['YYYYMM', 'YYYY-MM'], true);

    if (!normalizedMonth.isValid()) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: 'Invalid month format. Use YYYYMM or YYYY-MM.',
      });
    }

    const salaryYYYYMM = normalizedMonth.format('YYYYMM');
    const currentYYYYMM = moment().format('YYYYMM');

    if (Number(salaryYYYYMM) > Number(currentYYYYMM)) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: 'You cannot retrieve salary data for a future month.',
      });
    }

    /*
     * Remove duplicate and invalid payhead IDs.
     */
    const selectedPayheadIDs = [
      ...new Set(
        payheadMasterIDs
          .map((payheadMasterID) => Number(payheadMasterID))
          .filter(
            (payheadMasterID) =>
              Number.isInteger(payheadMasterID) && payheadMasterID > 0,
          ),
      ),
    ];

    if (selectedPayheadIDs.length === 0) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: 'Please provide valid payhead IDs.',
      });
    }

    const filterDate = normalizedMonth
      .clone()
      .endOf('month')
      .format('YYYY-MM-DD');

    /*
     * Accessible employee conditions.
     */
    const userAccessCondition = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: false,
    });

    const accessWhere = userAccessCondition?.where || {};
    const accessIncludeModels = userAccessCondition?.includeModels || [];

    /*
     * Fetch selected payhead details.
     */
    const selectedPayheads = await Payheadmaster.findAll({
      where: {
        payheadMasterId: {
          [Sequelize.Op.in]: selectedPayheadIDs,
        },
      },
      attributes: ['payheadMasterId', 'payheadName'],
      order: [['payheadMasterId', 'ASC']],
      raw: true,
    });

    if (selectedPayheads.length === 0) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: 'Selected payheads were not found.',
      });
    }

    const payheadNameMap = new Map();

    for (const payhead of selectedPayheads) {
      const payheadMasterID = Number(payhead.payheadMasterId);

      if (!payheadNameMap.has(payheadMasterID)) {
        payheadNameMap.set(
          payheadMasterID,
          payhead.payheadName || `Payhead-${payheadMasterID}`,
        );
      }
    }

    /*
     * Include used only for employee count and paginated employee IDs.
     *
     * Do not use subQuery:true here because nested required includes can
     * generate:
     * missing FROM-clause entry for table "hrSalaryTrasactions"
     */
    const salaryFilterInclude = {
      required: true,
      model: HrSalaryTransaction,
      attributes: [],
      where: {
        salaryYYYYMM,
      },
      include: [
        {
          required: true,
          model: HrSalaryMaster,
          as: 'HSM',
          attributes: [],
          include: [
            {
              required: true,
              model: GradeSalaryStructure,
              as: 'GSS',
              attributes: [],
              include: [
                {
                  required: true,
                  model: HRSalaryFields,
                  as: 'HSF',
                  attributes: [],
                  where: {
                    payheadMasterId: {
                      [Sequelize.Op.in]: selectedPayheadIDs,
                    },
                  },
                },
              ],
            },
          ],
        },
      ],
    };

    /*
     * Count unique employees having selected payhead salary transactions.
     */
    const totalCountResult = await UserMaster.count({
      where: {
        companyMasterId: companyMasterID,
        status: 1,
        ...accessWhere,
      },
      include: [...accessIncludeModels, salaryFilterInclude],
      distinct: true,
      col: 'userMasterID',
      subQuery: false,
    });

    const totalCount = Number(totalCountResult) || 0;

    const employeeIDRows = await UserMaster.findAll({
      where: {
        companyMasterId: companyMasterID,
        status: 1,
        ...accessWhere,
      },
      attributes: ['userMasterID', 'displayName'],
      include: [...accessIncludeModels, salaryFilterInclude],
      group: [
        Sequelize.col('userMaster.userMasterID'),
        Sequelize.col('userMaster.displayName'),
      ],
      order: [
        ['displayName', 'ASC'],
        ['userMasterID', 'ASC'],
      ],
      subQuery: false,
    });

    const selectedUserIDs = [
      ...new Set(
        employeeIDRows
          .map((user) => Number(user.userMasterID))
          .filter(Number.isFinite),
      ),
    ];

    if (selectedUserIDs.length === 0) {
      return res.status(statusCodes.OK).json({
        status: statusCodes.OK,
        totalcount: totalCount,
        data: [],
      });
    }

    /*
     * Fetch complete employee and salary details for the employee IDs
     * selected in the pagination query.
     */
    const detailIncludeModels = [
      ...accessIncludeModels,
      {
        required: true,
        model: HrSalaryTransaction,
        where: {
          salaryYYYYMM,
        },
        attributes: ['EmployeeSalaryAmount'],
        include: [
          {
            required: true,
            model: HrSalaryMaster,
            as: 'HSM',
            attributes: ['gradeSalaryStructureID'],
            include: [
              {
                required: true,
                model: GradeSalaryStructure,
                as: 'GSS',
                attributes: ['gradeSalaryStructureID'],
                include: [
                  {
                    required: true,
                    model: HRSalaryFields,
                    as: 'HSF',
                    attributes: ['payheadMasterId'],
                    where: {
                      payheadMasterId: {
                        [Sequelize.Op.in]: selectedPayheadIDs,
                      },
                    },
                  },
                ],
              },
            ],
          },
        ],
      },
      {
        required: false,
        model: EmployeeJoiningDetails,
        as: 'emp_join',
        attributes: ['employeeCode'],
      },
      {
        required: false,
        model: EmployeeBranch,
        as: 'emp_branch',
        where: {
          status: 1,
          applicableDate: {
            [Sequelize.Op.lte]: filterDate,
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: filterDate,
              },
            },
            {
              endDate: {
                [Sequelize.Op.is]: null,
              },
            },
          ],
        },
        attributes: ['branchID'],
        include: [
          {
            required: false,
            model: BranchMaster,
            as: 'branchMaster',
            attributes: ['branchName'],
          },
        ],
      },
      {
        required: false,
        model: EmployeeDepartment,
        as: 'emp_dept',
        where: {
          status: 1,
          applicableDate: {
            [Sequelize.Op.lte]: filterDate,
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: filterDate,
              },
            },
            {
              endDate: {
                [Sequelize.Op.is]: null,
              },
            },
          ],
        },
        attributes: ['departmentID'],
        include: [
          {
            required: false,
            model: Department,
            as: 'department',
            attributes: ['departmentName'],
          },
        ],
      },
      {
        required: false,
        model: EmployeeDesignation,
        as: 'emp_desig',
        where: {
          status: 1,
          applicableDate: {
            [Sequelize.Op.lte]: filterDate,
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: filterDate,
              },
            },
            {
              endDate: {
                [Sequelize.Op.is]: null,
              },
            },
          ],
        },
        attributes: ['designationID'],
        include: [
          {
            required: false,
            model: Designation,
            as: 'designation',
            attributes: ['designationName'],
          },
        ],
      },
      {
        required: false,
        model: EmployeeDivision,
        as: 'emp_div',
        where: {
          status: 1,
          startDate: {
            [Sequelize.Op.lte]: filterDate,
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: filterDate,
              },
            },
            {
              endDate: {
                [Sequelize.Op.is]: null,
              },
            },
          ],
        },
        attributes: ['divisionId', 'startDate'],
        include: [
          {
            required: false,
            model: Division,
            attributes: ['divisionName'],
          },
        ],
      },
      {
        required: false,
        model: EmployeeWorkingArea,
        as: 'emp_area',
        where: {
          status: 1,
          startDate: {
            [Sequelize.Op.lte]: filterDate,
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: filterDate,
              },
            },
            {
              endDate: {
                [Sequelize.Op.is]: null,
              },
            },
          ],
        },
        attributes: ['workingAreaId', 'startDate'],
        include: [
          {
            required: false,
            model: WorkingArea,
            attributes: ['workingAreaName'],
          },
        ],
      },
    ];

    const userData = await UserMaster.findAll({
      where: {
        userMasterID: {
          [Sequelize.Op.in]: selectedUserIDs,
        },
        companyMasterId: companyMasterID,
        status: 1,
        ...accessWhere,
      },
      attributes: ['userMasterID', 'displayName'],
      include: detailIncludeModels,
      order: [
        ['displayName', 'ASC'],
        ['userMasterID', 'ASC'],
      ],
      subQuery: false,
    });

    /*
     * Prepare report response.
     */
    const finalUserData = userData.map((user) => {
      const employeeInfo = parseEmployeeInfoAlias(user);

      const userObject = {
        'Employee Code': employeeInfo.employeeCode || '',
        'User Name': user.displayName || '',
        Branch: employeeInfo.branch || '',
        Department: employeeInfo.department || '',
        Designation: employeeInfo.designation || '',
        Division: employeeInfo.division || '',
        'Working Area': employeeInfo.workingArea || '',
      };

      /*
       * Initialize all selected payheads with zero.
       */
      for (const payheadName of payheadNameMap.values()) {
        userObject[payheadName] = 0;
      }

      /*
       * Use the exact association property configured in your model.
       * Your current association appears to be hrSalaryTrasactions.
       */
      const salaryTransactions =
        user.hrSalaryTrasactions || user.hrSalaryTransactions || [];

      for (const salaryTransaction of salaryTransactions) {
        const salaryField = salaryTransaction.HSM?.GSS?.HSF;

        const payheadMasterID = Number(salaryField?.payheadMasterId);

        if (!payheadNameMap.has(payheadMasterID)) {
          continue;
        }

        const payheadName = payheadNameMap.get(payheadMasterID);

        const previousAmount = Number(userObject[payheadName]) || 0;

        const salaryAmount =
          Number(salaryTransaction.EmployeeSalaryAmount) || 0;

        userObject[payheadName] = Number(
          (previousAmount + salaryAmount).toFixed(2),
        );
      }

      return userObject;
    });
    if (finalUserData.length) {
      await generateExcel(
        finalUserData,
        'PayheadWise Salary Report',
        'xlsx',
        res,
      );
      return;
    } else {
      return res.status(statusCodes.OK).json({
        status: 401,
        message: 'No data found to generate the file!',
      });
    }
  } catch (error) {
    next(error);
  }
};

exports.employeeGPSTrackingSummaryReport = async (req, res, next) => {
  try {
    const { companyMasterID, date, userMasterID = [] } = req.body;

    if (!companyMasterID || !date) {
      return res.status(statusCodes.BAD_REQUEST).json({
        status: statusCodes.BAD_REQUEST,
        message: message.usermessage.requiredMessage('company and Date'),
      });
    }

    const reportDate = date;
    const start = `${date} 00:00:00.000`;
    const end = `${date} 23:59:59.999`;

    const detailIncludeModels = [
      {
        required: false,
        model: EmployeeJoiningDetails,
        as: 'emp_join',
        attributes: ['employeeCode'],
      },
      {
        required: false,
        model: EmployeeBranch,
        as: 'emp_branch',
        where: {
          status: 1,
          applicableDate: {
            [Sequelize.Op.lte]: reportDate,
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: reportDate,
              },
            },
            {
              endDate: {
                [Sequelize.Op.is]: null,
              },
            },
          ],
        },
        attributes: ['branchID'],
        include: [
          {
            required: false,
            model: BranchMaster,
            as: 'branchMaster',
            attributes: ['branchName'],
          },
        ],
      },
      {
        required: false,
        model: EmployeeDepartment,
        as: 'emp_dept',
        where: {
          status: 1,
          applicableDate: {
            [Sequelize.Op.lte]: reportDate,
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: reportDate,
              },
            },
            {
              endDate: {
                [Sequelize.Op.is]: null,
              },
            },
          ],
        },
        attributes: ['departmentID'],
        include: [
          {
            required: false,
            model: Department,
            as: 'department',
            attributes: ['departmentName'],
          },
        ],
      },
      {
        required: false,
        model: EmployeeDesignation,
        as: 'emp_desig',
        where: {
          status: 1,
          applicableDate: {
            [Sequelize.Op.lte]: reportDate,
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: reportDate,
              },
            },
            {
              endDate: {
                [Sequelize.Op.is]: null,
              },
            },
          ],
        },
        attributes: ['designationID'],
        include: [
          {
            required: false,
            model: Designation,
            as: 'designation',
            attributes: ['designationName'],
          },
        ],
      },
      {
        required: false,
        model: EmployeeDivision,
        as: 'emp_div',
        where: {
          status: 1,
          startDate: {
            [Sequelize.Op.lte]: reportDate,
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: reportDate,
              },
            },
            {
              endDate: {
                [Sequelize.Op.is]: null,
              },
            },
          ],
        },
        attributes: ['divisionId', 'startDate'],
        include: [
          {
            required: false,
            model: Division,
            attributes: ['divisionName'],
          },
        ],
      },
      {
        required: false,
        model: EmployeeWorkingArea,
        as: 'emp_area',
        where: {
          status: 1,
          startDate: {
            [Sequelize.Op.lte]: reportDate,
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: reportDate,
              },
            },
            {
              endDate: {
                [Sequelize.Op.is]: null,
              },
            },
          ],
        },
        attributes: ['workingAreaId', 'startDate'],
        include: [
          {
            required: false,
            model: WorkingArea,
            attributes: ['workingAreaName'],
          },
        ],
      },
      {
        required: true,
        model: UserTracking,
        as: 'userTracking',
        where: {
          trackStatus: 1,
        },
        attributes: [],
      },
      {
        required: true,
        model: Tracking,
        as: 'trackings',
        where: {
          Track_datetime: {
            [Sequelize.Op.between]: [start, end],
          },
        },
        // attributes: [
        //   'UserTrackingID',
        //   'userMasterID',
        //   'Lattitude',
        //   'Longitude',
        //   'Address',
        //   'Gps',
        //   'Wifi',
        //   'type',
        //   'Track_datetime',
        // ],
      },
    ];

    const userAccessCondition = accessibleRoleWiseUsers({
      userDetails: req.userDetails,
      includeCompany: false,
    });

    const userCondition = {
      companyMasterId: companyMasterID,
      ...userAccessCondition?.where,
    };

    if (Array.isArray(userMasterID) && userMasterID.length) {
      userCondition.userMasterID = {
        [Sequelize.Op.in]: userMasterID,
      };
    }

    const userData = await UserMaster.findAll({
      where: userCondition,
      attributes: ['userMasterID', 'displayName'],
      include: [
        ...detailIncludeModels,
        ...(userAccessCondition?.includeModels || []),
      ],
      order: [
        ['displayName', 'ASC'],
        ['userMasterID', 'ASC'],
        [
          {
            model: Tracking,
            as: 'trackings',
          },
          'Track_datetime',
          'ASC',
        ],
      ],
      subQuery: false,
    });

    const finalUserData = userData.map((user) => {
      const employeeInfo = parseEmployeeInfoAlias(user);

      const trackingData = [...(user.trackings || [])].sort(
        (a, b) =>
          new Date(a.Track_datetime).getTime() -
          new Date(b.Track_datetime).getTime(),
      );

      let firstTrackingTime = '';
      let lastTrackingTime = '';
      let totalTrackingMinutes = 0;
      let totalTrackingHours = '00:00';

      let trackingMinutesIn = 0;
      let trackingMinutesOut = 0;
      let trackingMinutesNotFound = 0;
      let trackingMinutesAppKilled = 0;

      let findGPSOffPointsCount = 0;
      let findInternetOffPointsCount = 0;
      let findAppKilledPointsCount = 0;

      const isCoordinateNotFound = (value) => {
        return (
          value === null ||
          value === undefined ||
          value === '' ||
          String(value).trim().toLowerCase() === 'not found' ||
          !Number.isFinite(Number(value))
        );
      };

      if (trackingData.length) {
        firstTrackingTime = trackingData[0].Track_datetime;
        lastTrackingTime = trackingData[trackingData.length - 1].Track_datetime;

        for (let index = 0; index < trackingData.length; index++) {
          const currentTracking = trackingData[index];

          if (String(currentTracking?.Gps).toLowerCase() === 'off') {
            findGPSOffPointsCount++;
          }

          if (String(currentTracking?.Wifi).toLowerCase() === 'off') {
            findInternetOffPointsCount++;
          }

          if (String(currentTracking?.type).toLowerCase() === 'outage') {
            findAppKilledPointsCount++;
          }

          // Last tracking point has no next point, so duration cannot be calculated.
          if (index === trackingData.length - 1) {
            continue;
          }

          const nextTracking = trackingData[index + 1];

          const currentTimeMs = new Date(
            currentTracking.Track_datetime,
          ).getTime();

          const nextTimeMs = new Date(nextTracking.Track_datetime).getTime();

          if (
            !Number.isFinite(currentTimeMs) ||
            !Number.isFinite(nextTimeMs) ||
            nextTimeMs <= currentTimeMs
          ) {
            continue;
          }

          const diffMs = nextTimeMs - currentTimeMs;

          if (diffMs <= 0) {
            continue;
          }
          const durationMinutes = diffMs / (1000 * 60); // e.g. 5.75 minutes

          totalTrackingMinutes += durationMinutes;

          const latitude =
            currentTracking?.Latitude ??
            currentTracking?.latitude ??
            currentTracking?.Lattitude ??
            currentTracking?.lattitude;

          const longitude =
            currentTracking?.Longitude ?? currentTracking?.longitude;

          const geofence = String(
            currentTracking?.geofence || '',
          ).toLowerCase();

          const trackingType = String(
            currentTracking?.type || '',
          ).toLowerCase();

          /*
           * Duration classification priority:
           * 1. Application killed
           * 2. Location not found
           * 3. Inside geofence
           * 4. Outside geofence
           */
          if (trackingType === 'outage') {
            trackingMinutesAppKilled += durationMinutes;
          } else if (
            isCoordinateNotFound(latitude) ||
            isCoordinateNotFound(longitude)
          ) {
            trackingMinutesNotFound += durationMinutes;
          } else if (geofence === 'in') {
            trackingMinutesIn += durationMinutes;
          } else if (geofence === 'out') {
            trackingMinutesOut += durationMinutes;
          } else {
            // Geofence value is missing or unknown.
            trackingMinutesNotFound += durationMinutes;
          }
        }
        const totalTrackingOnMinutes = Math.floor(
          (new Date(lastTrackingTime).getTime() -
            new Date(firstTrackingTime).getTime()) /
            (1000 * 60),
        );
        totalTrackingHours = minutesToHoursMinutes(totalTrackingOnMinutes);
      }

      return {
        'Employee Code': employeeInfo.employeeCode || '',
        'User Name': user.displayName || '',
        Branch: employeeInfo.branch || '',
        Department: employeeInfo.department || '',
        Designation: employeeInfo.designation || '',
        Division: employeeInfo.division || '',
        'Working Area': employeeInfo.workingArea || '',

        'First Tracking Time': firstTrackingTime
          ? moment(firstTrackingTime).format('DD-MM-YYYY HH:mm:ss')
          : '',

        'Last Tracking Time': lastTrackingTime
          ? moment(lastTrackingTime).format('DD-MM-YYYY HH:mm:ss')
          : '',

        'Total Tracking Hours': totalTrackingHours,

        'Tracking Minutes (In)': formatMinutesAndSeconds(trackingMinutesIn),
        'Tracking Minutes (Out)': formatMinutesAndSeconds(trackingMinutesOut),
        'Tracking Minutes (Not Found)': formatMinutesAndSeconds(
          trackingMinutesNotFound,
        ),

        'No. Time GPS Off': findGPSOffPointsCount,
        'No. Time Internet Off': findInternetOffPointsCount,
        'No. Time Application Killed': findAppKilledPointsCount,

        'Tracking Minutes (App Killed)': formatMinutesAndSeconds(
          trackingMinutesAppKilled,
        ),
      };
    });
    function formatMinutesAndSeconds(totalMinutes) {
      const minutes = Math.floor(totalMinutes);
      const seconds = Math.round((totalMinutes - minutes) * 60);

      // Handle rounding (e.g. 20.999 -> 21:00)
      if (seconds === 60) {
        return `${minutes + 1}.00`;
      }

      return `${minutes}.${String(seconds).padStart(2, '0')}`;
    }
    if (!finalUserData.length) {
      return res.status(statusCodes.OK).json({
        status: statusCodes.NOT_FOUND,
        message: 'No data found to generate the file!',
      });
    }

    await generateExcel(
      finalUserData,
      'Employee GPS Tracking Summary Report',
      'xlsx',
      res,
    );

    return;
  } catch (error) {
    next(error);
  }
};

